export default [{"id":1415,"question":"بالنسبة لترك الرأس كله، يعني ما يحلقه، هل هو سُنة؟","title":"هل ترك حلق الرأس من السُّنة؟","answer":"الجواب: هو مباح، لو إنسان فعله اتباعًا للنبي ﷺ وهو صادق؛ لا بأس، ولكن لا يقصد به شئ آخر كالتشبه بالنساء.","link":"https://binbaz.org.sa/fatwas/21510/هل-ترك-حلق-الراس-من-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في حلق الرأس.mp3","categories":["الآداب والأخلاق"]},{"id":1590,"question":"تربية الحيوانات في البيت –كالدجاج والغنم- هل هي من أذية الجار؟","title":"هل من أذيَّة الجيران تربية الحيوانات؟","answer":"الجواب:\nما لها تعلُّقٌ بالجار، يكفّ أذاها ولا بأس، يُربي الدجاج، ويربي كل شيءٍ ولا بأس، ولكن يكفّ الأذى عن الجار.","link":"https://binbaz.org.sa/fatwas/21694/هل-من-اذية-الجيران-تربية-الحيوانات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من أذية الجيران تربية الحوانات.mp3","categories":["الآداب والأخلاق"]},{"id":1599,"question":"المُعتبر في تحديد الجوار، هل مرده إلى العُرف؟","title":"ما الضابط المُعتبر في تحديد الجوار؟","answer":"الجواب:\nلا، قُرب البِيبَان، فكلَّما قرب البابُ فهو أقرب.\nس: لكن تحديد.....؟\nج: يُروى في هذا: أربعون دارًا، ولكن ما أعلم فيه حديثًا صحيحًا يُحدد، إنما كلَّما كان أقرب فهو أولى بالإحسان، كلما كان أقرب بابًا يعني.","link":"https://binbaz.org.sa/fatwas/21703/ما-الضابط-المعتبر-في-تحديد-الجوار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المعتبر في تحديد الجوار.mp3","categories":["الآداب والأخلاق"]},{"id":1776,"question":"الجار الذي له حقّ الجوار هو الملاصق بالجدار أو الذي في الحي؟","title":"من هو الجار الذي له حقّ الجوار؟","answer":"الجواب:\nكل مَن قرب منك فهو جار، كل مَن كان أقرب منك فهو جارك إلى أربعين دارًا، أحقهم أقربهم بابًا، مَن كان أقرب بابًا فهو أحق بالجوار.","link":"https://binbaz.org.sa/fatwas/21883/من-هو-الجار-الذي-له-حق-الجوار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من هو الجار الذي له حقّ الجوار.mp3","categories":["الآداب والأخلاق"]},{"id":1831,"question":"حلق الرأس بالكلية لغير النّسك هل هو من سُنُن الخوارج؟","title":"حكم حلق الرأس كاملًا في غير النُّسك","answer":"الجواب:\nلا بأس إذا حلقه ورأى المصلحة، والخوارج يُوجبون على أصحابهم التحليق، فهو من سيماهم، أما هو في  نفس الأمر فجائزٌ في الشرع؛ فالنبي حلق في حجة الوداع عليه الصلاة والسلام، وقصَّر في العمرة، وفي غير الحج والعمرة يجوز هذا، وهذا مثلما قال ﷺ: احلقه كله، أو دعه كله.","link":"https://binbaz.org.sa/fatwas/21939/حكم-حلق-الراس-كاملا-في-غير-النسك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم حلق الرأس بالكلية لغير النّسك.mp3","categories":["الآداب والأخلاق"]},{"id":1833,"question":"حلق شعر الطفلة الصغيرة؟","title":"ما حكم حلق شعر الطفلة الصغيرة؟","answer":"الجواب:\nلا يُحْلَق إلا من علةٍ، إذا كان لعلة، مرض؛ رأى الطبيبُ أو الطبيبةُ، إذا رأوا المصلحة لأجل الطب.","link":"https://binbaz.org.sa/fatwas/21941/ما-حكم-حلق-شعر-الطفلة-الصغيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم حلق شعر الطفلة الصغيرة.mp3","categories":["الآداب والأخلاق"]},{"id":1834,"question":"الصّلع هو: جوانب من الشعر ينبت أكثر.....؟","title":"حكم قص جوانب الرأس وترك جهة الصَّلَع","answer":"الجواب:\nإذا كان خِلْقةً ما فيه شيء، والحمد لله.\nس: لكن لو قصَّ من الجوانب وترك الجهة التي فيها صَلَع، هل يدخل في القَزَع؟\nج: لا يتعرض لشيءٍ.\nس: النَّهي للتحريم؟\nج: نعم، هذا الأصل، يقول الرسول ﷺ: ما نهيتُكم عنه فاجتنبوه، وما أمرتُكم به فأتوا به ما استطعتم، ويقول جل وعلا: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7]، هذه قاعدة عند أهل العلم: أنَّ النهي أصله التحريم، والأمر أصله الوجوب، إلا بدليلٍ.","link":"https://binbaz.org.sa/fatwas/21942/حكم-قص-جوانب-الراس-وترك-جهة-الصلع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الأصلع الذي يقص جوانب رأسه ويترك الجهة التي فيها صلع.mp3","categories":["الآداب والأخلاق"]},{"id":1867,"question":"بعض كبار السن يجلسون فيما يُسَمَّى \"المشراق\" (مكان يقابل طلوع الشمس)، هل مَنْهِيٌّ عنه؟","title":"حكم الجلوس فيما يُسمَّى \"المشراق\"","answer":"الجواب:\nلا، إذا قاموا بحقِّه فلا بأس، مثلما قال ﷺ: إذا كان يرد السلام، ويأمر بالمعروف، وينهى عن المنكر، ويكف الأذى؛ لا بأس. أما إذا كان يؤذي الناس: بحسدٍ، وغيبةٍ، ونميمةٍ؛ فلا يجوز، بعض الناس يجلس في السوق ويؤذي الناس، إن رأى هذا قال: هذا فيه ما فيه، وإن رأى هذا قال: هذا فيه ما فيه، وإن مرت عليه امرأةٌ قال: هذه امرأة فلان؛ يؤذي الناس.","link":"https://binbaz.org.sa/fatwas/21976/حكم-الجلوس-فيما-يسمى-المشراق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الجلوس في المشراق.mp3","categories":["الآداب والأخلاق"]},{"id":1868,"question":"مَن قال بأن الجلوس في الطريق مع إعطائه حقّه مكروه والأوْلى تركه؟","title":"حكم الجلوس في الطريق مع إعطائه حقه","answer":"الجواب:\nظاهر الحديث للمؤمن البُعْد عن الجلوس؛ لأنه قد لا يقوم بحق الطريق، مثلما قال ﷺ: إياكم والجلوس، لكن إذا كان ولا بدّ، يعني: يرغبون في الجلوس ويحتاجون إليه، فلا بدّ أن يعطوا الطريق حقها مثلما قال ﷺ، وإلا فالحذر خيرٌ لهم.\nس: القول بتركه مع إعطاء حقّه؟\nج: خيرٌ لهم، أفضل لهم؛ لأنهم قد لا يعطون حقَّه وقد يضعفون ولا يعطون حقَّه، وإذا جزموا أنهم يعطون حقَّه فهذا طيب، لكن مَن يجزم بهذا؟ ومَن يَقْوَى عليه؟","link":"https://binbaz.org.sa/fatwas/21977/حكم-الجلوس-في-الطريق-مع-اعطاىه-حقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الجلوس في الطريق مع إعطائه حقه.mp3","categories":["الآداب والأخلاق"]},{"id":1964,"question":"أحيانًا يُطلقون على مرض السرطان \"خبيث\"؟","title":"حكم وصف \"خبيث\" لمرض السرطان","answer":"الجواب:\nما أعلم فيه شيئًا، مثلما يقال: تمر خبيث، وَلَا تَيَمَّمُوا الْخَبِيثَ مِنْهُ تُنْفِقُونَ [البقرة:267] يعني: رديء، هذا هو، يعني: مرض مخيف.\nس: ما يكون من السبّ؟\nج: لا، ما هو سبّ.","link":"https://binbaz.org.sa/fatwas/22079/حكم-وصف-خبيث-لمرض-السرطان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إطلاق كلمة خبيث على مرض السرطان.mp3","categories":["الآداب والأخلاق"]},{"id":2076,"question":"هل يجوز لعن الدنيا ولعن الشيطان؟","title":"ما حكم لعن الدنيا ولعن الشيطان؟","answer":"الجواب:\nلعن الشيطان أحبّ.\nس: ولعن الدنيا: \"الله يلعن الدنيا\" هل يجوز؟\nج: تركه أوْلى؛ لأنَّ الرسول ﷺ أخبر عنها أنها مذمومة من جهة الله، وما قال: العنوها أنتم.","link":"https://binbaz.org.sa/fatwas/22194/ما-حكم-لعن-الدنيا-ولعن-الشيطان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لعن الدنيا ولعن الشيطان.mp3","categories":["الآداب والأخلاق"]},{"id":2214,"question":"التسمية بأسماء الحيوانات كعياض بن حمار؟","title":"حكم تسمية البشر بأسماء الحيوانات","answer":"الجواب:\nهذه من عادات العرب في الجاهلية، فكانوا يسمون: حمارًا، ويسمون: جحشًا، والعرب الآن يُسمون: جحشًا، ويُسمون: حمارًا، ويسمون: ثورًا، لكن الأحسن عدم التسمية بأسماء الحيوانات.","link":"https://binbaz.org.sa/fatwas/22337/حكم-تسمية-البشر-باسماء-الحيوانات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التسمية بأسماء الحيوانات.mp3","categories":["الآداب والأخلاق"]},{"id":2266,"question":"رجل طُلِّقت ابنته من زوجها، وكان زوجها سكِّيرًا، يقول: هل يجوز لي أن أُحذّر الناسَ منه من غير أن يسألوني أم لا بد أن يسألوني؟","title":"هل يجوز التحذير من السِكّير؟","answer":"الجواب:\nإذا استُنْصِحَ ينصح، ومن النَّصيحة أن ينصحه هو، أمَّا إذا كان يُظهر المعاصي فلا غيبةَ له، فإذا كان يشربها في الأسواق أو القهاوي ولا يُبالي فلا غيبةَ له.\nس: هو مُتَستِّر؟\nج: فقط ينصحه إذا استُنْصِحَ.\nس: إذن لا يجوز له أن يقول فيه شيئًا؟\nج: لا، هذا من الغيبة.","link":"https://binbaz.org.sa/fatwas/22389/هل-يجوز-التحذير-من-السكير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز التحذير من السِكّير.mp3","categories":["الآداب والأخلاق"]},{"id":2311,"question":"رجلٌ قال لعاملٍ مسلمٍ يعمل في الرياض: إن شاء الله سأحضر لك كتبًا إسلاميةً، وإلى الآن لم يفعل، يقول أنه ينسى، هل هذا من صفات المُنافقين: إذا حدَّث كذب؟","title":"هل يُوصف بالنفاق من وَعَد بشيء ونَسِيَه؟","answer":"الجواب:\nعلى كل حال، هذا يختلف: إذا لم يكن عن عمدٍ ولا عن قصدٍ، بل غلبته أمورٌ أخرى؛ ما يدخل في هذا إن شاء الله، إنما يدخل في هذا مَن تساهل.","link":"https://binbaz.org.sa/fatwas/22435/هل-يوصف-بالنفاق-من-وعد-بشيء-ونسيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وعد بشيء ونسي فهل يكون من صفات المُنافقين.mp3","categories":["الآداب والأخلاق"]},{"id":2353,"question":"مَن عاب الطعام هل يأثم؟","title":"هل يأثم مَن عاب الطعام؟","answer":"الجواب:\nلا، ما يأثم، إن قال: تراه مالحًا، غيّروه، أو: أَمْلِحُوه، أو كذا؛ فلا بأس، لكن من كمال الأخلاق عدم العيب، بل يُوجِّههم إلى ما يُريد من دون عيبٍ.","link":"https://binbaz.org.sa/fatwas/22478/هل-ياثم-من-عاب-الطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يأثم مَن عاب الطعام.mp3","categories":["الآداب والأخلاق"]},{"id":2444,"question":"حكم لعن المُعَيَّن؟","title":"حكم لعن المُعَيَّن","answer":"الجواب:\nالمشروع عدم اللعن إلا إذا كان فيه مصلحة، مثل: داعٍ إلى فجور، مقاتل المسلمين، حارب المسلمين، يُدعى عليه، أما إذا كان مسالمًا يُدعى له بالهداية، مثل ما قال النبي ﷺ في كفار دوس: اللهم اهد دوسًا وائت بهم، ومثل ما دعا على كفار قريش: اللهم العن فلانًا وفلانًا -الذين هم رؤوس في الكفر- اللهم العن فلان بن فلان، اللهم العن عتبة بن ربيعة وشيبة بن ربيعة وأبي جهل بن هشام؛لأنهم رؤوس الكفر، دعاة إلى الكفر، عذّبوا المسلمين، أما المُعْرِض المسالم لاـ، يُدعى له بالهداية، أما العموم: لعن الله الكافرين، لعن الله الفاسقين، لعن الله السُّراق، لا بأس، العموم لا بأس، ولما لعن رجل إنسانًا يشرب خمرًا عند النبي ﷺ قال: لا تلعنه فإنه يحب الله ورسوله، لا تعينوا عليه الشيطان.\nس:الضابط فيه يا شيخ أن يظهر العداوة والسب للإسلام؟\nالشيخ: سب الإسلام أو محاربة المسلمين.\nس: إذا كان المسلم داعية إلى الفجور هل يُدعى عليه أو يُلعن؟\nالشيخ: يُدعى له بالهداية وأن الله يكفيهم شره، إن كان مسلمًا يُدعى له بالهداية وأن الله يكفي المسلمين شره.","link":"https://binbaz.org.sa/fatwas/22573/حكم-لعن-المعين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم لعن المسلم المعين.mp3","categories":["الآداب والأخلاق","الأدعية والأذكار"]},{"id":2494,"question":"من كثرة العمالة الكافرة أحيانًا يتحرَّج الواحد من السلام، هل يُسَلِّم؟","title":"ما حكم السلام على جَمْعٍ فيهم غَيْرُ مسلمين؟","answer":"ما سمعت أيش النبي يقول لما سئل أي العمل أفضل؟ قال: أن تُطْعِم الطعام وتقرأ السلام على مَن عرفت ومَن لم تعرِف سَلِّم وبس.\nس: عموم الأدلة على السلام ألا تدل على الوجوب؟\nالشيخ: إفشاء السلام مشروع، وأن تبدأ أفضل، وإن بُدِئت فالرد عليك واجب، والمؤمن يسارع إلى الخيرات، حتى ولو ما هو بواجب يسارع بأن يبدأ، مثل لما سُئل: يا رسول الله أي الإسلام أفضل؟ قال: أن تُطْعِم الطعام، وتقرأ السلام على من عرفت ومن لم تعرف فالإنسان يبادر بالخيرات أفضل له.","link":"https://binbaz.org.sa/fatwas/22624/ما-حكم-السلام-على-جمع-فيهم-غير-مسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا كان في الحاضرين عمالة كافرة أو رافضة وغيرهم هل يسلم.mp3","categories":["الآداب والأخلاق"]},{"id":2849,"question":"بالنسبة للتورية: ما يستطيع أن يقابل أحدًا، ويقول: قولوا في المكتب، وهو في البيت، هل تُستخدم؟","title":"ما ضابط التورية حتى لا تكون كذبًا؟","answer":"الجواب: هذا كَذِب.\nس: في ناس يستخدمها الآن: يحط غرفة مكتبة، ويقولون: ذهب إلى المكتبة، أو كذا، هل تُعتبر كَذِبا؟\nالشيخ: إذا كان في المكتبة.\nس: لا يخصها، وكذا بدل ما يقولون له: ما هو في، يقولون: ذهب إلى المكتبة.\nالشيخ: إذا كان خلاف الحقيقة لا، أما إذا كان ما هو في المحل هذا.\nس: يقولون: من التورية؟\nالشيخ: إن في المعاريض مندوحة عن الكذب، إذا عَرَّض بشيء لا يتعمد فيه الكذب.\nس: ورد عن بعض السلف أنه كان له غرفة يسميها دمشق أو حلب، فإذا خرج أو إذا أراد ألا يزوره أحد وسألوا عنه قال: قولوا إنه في دمشق؟\nالشيخ: ما أعرفه، أقول: ما أعرف هذا. س: أحسن الله إليك، فكيف يُوَرِّي؟ الشيخ: المقصود: التورية بشيء ليس فيه تعمد الكذب، مثل أن يقول: ما هو هنا، يعني ما هو في المجلس، ما هو في مكان آخر وينوي المجلس، ليس هنا يعني في المجلس، يعني فليس هنا في المجلس، يُروى أن أحمد سُئل عن المروذي هل هو موجود؟ قال: ليس ها هنا.","link":"https://binbaz.org.sa/fatwas/23002/ما-ضابط-التورية-حتى-لا-تكون-كذبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل التورية من الكذب.mp3","categories":["الآداب والأخلاق"]},{"id":2923,"question":"الضابط في الاسم متى يكون تزكية؛ لِيُغَيَّر؟","title":"ما ضابط اختيار الاسم الطيّب دون تزكية؟","answer":"الجواب: الإنسان يتحرّى الأسماء الطيبة ويُسمِّي بها، وأحسنها ما عُبّد لله، وأسماء الأنبياء كلها طيبة، الأصل السلامة إلا ما عُبّد لغير الله.","link":"https://binbaz.org.sa/fatwas/23079/ما-ضابط-اختيار-الاسم-الطيب-دون-تزكية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تحري الأسماء الطيبة والتسمي بها.mp3","categories":["الآداب والأخلاق"]},{"id":2927,"question":"قول بعض الناس عندما يتلاقون الصباح يقولون: صباح الخير؟","title":"حكم قول \"صباح الخير\" للتحية","answer":"الجواب: لا، الأفضل السلام عليكم، ثم إذا سلم عليه قال: صبحك الله بالخير، أو كيف حالك، يبدأ بالسلام، هذه السنة، وذاك يقول: وعليكم السلام، ثم إذا أحب يقول له كيف حالك؟ كيف أولادك؟ فلا بأس.","link":"https://binbaz.org.sa/fatwas/23083/حكم-قول-صباح-الخير-للتحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم قول صباح الخير للتحية.mp3","categories":["الآداب والأخلاق"]},{"id":2997,"question":"المواضع التي تجوز فيها الغيبة، عددها؟ وما هي؟","title":"ما المواضع التي تجوز فيها الغِيبة؟","answer":"الجواب: ضبطها بعضهم بستة مواضع:","link":"https://binbaz.org.sa/fatwas/23154/ما-المواضع-التي-تجوز-فيها-الغيبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المواضع التي تجوز فيها الغيبة.mp3","categories":["الآداب والأخلاق"]},{"id":3042,"question":"إذا كان شخص مدعوًا في وليمة وصارت غَيبة ولا قَدَر أن يغيّرها، هل يأثم بجلوسه أو لا بد أن يخرج؟","title":"حكم مَنْ دُعي إلى وليمة وحَصَلت غِيبة","answer":"الجواب: إما يُنكر وإلا يخرج.\nس: إذا كان مدعوًا إلى وليمة؟\nالشيخ: ولَو، المقصود حضورُه، قد أجاب الدعوة، الأكل ما هو بلازم.","link":"https://binbaz.org.sa/fatwas/23202/حكم-من-دعي-الى-وليمة-وحصلت-غيبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من دُعي إلى وليمة وصارت غيبة.mp3","categories":["الآداب والأخلاق"]},{"id":3046,"question":"بعض الناس إذا ظُلم ينشر ظلم الظالم في غير محله، يذكر مثلًا أن الرجل ذاك ظلمه..؟","title":"ما حكم نَشْر ظلم الظالم؟","answer":"الجواب: لا لا، لمن ينفعه يذكره، لمن يفيده من القاضي أو الأمير أو رئيس الهيئة، الناس اللي يفيدونه في مَظْلَمَته.","link":"https://binbaz.org.sa/fatwas/23206/ما-حكم-نشر-ظلم-الظالم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم نشر ظلم الظالم.mp3","categories":["الآداب والأخلاق"]},{"id":3047,"question":"وجَرْح الرواة؟","title":"حكم جَرْح الرُّواة","answer":"الجواب: جَرْح الرواة من التعريف، ومن النصيحة، يدخل في الأمرين، يدخل في النصيحة ويدخل في التعريف، جرح الرواة: هذا ضعيف، هذا وضّاع، هذا مبتدع، هذا كثير الغلط، هذا من النصيحة لله ولعباده، ومن التعريف أيضًا، يدخل في التعريف وهو من النصيحة.\nس: هل تُذكر حسناتُهم؟\nالشيخ: لا ما لزوم، المقصود بيان العيب للحذر منه، ما هو المقصود بيان الحسنات، المقصود بيان العيوب التي يُحْذَر منها.","link":"https://binbaz.org.sa/fatwas/23207/حكم-جرح-الرواة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم جرح الرواة.mp3","categories":["الآداب والأخلاق","الحديث وعلومه"]},{"id":3049,"question":"لو شخص مثلًا قال لآخر: فلان هذا ما وجدت فيه خير، أو كذا مثلًا؛ لأنه ما نفعه في حاجة مثلًا، هل تُعتبر مِن الغِيبة؟","title":"هل مِن الغِيبة قول: فلان ما فيه خير، ونحوه؟","answer":"الجواب: إنْ كانت دَعَتْ له الحاجة وحَوّله عليه وقال: رح له يعطيك كذا وكذا وراح له... يعني له فائدة، أو أمره يتصل به، أو أوصاه به، وإلا من غير حاجة لا.\nس: يعني قصده أنه يغتابه؟\nالشيخ: لا، ما يصلح ما دام الشيء خفيًّا، لا، أما إن كان الشيء ظاهرا فلا بأس. القاعدة: الخفي ما يُبيّنه إلا عند الحاجة بس.","link":"https://binbaz.org.sa/fatwas/23209/هل-من-الغيبة-قول-فلان-ما-فيه-خير-ونحوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من الغيبة قول فلان هذا ما فيه خير ونحوه.mp3","categories":["الآداب والأخلاق"]},{"id":3054,"question":"ما يسمونه العامة من التنكيت على بعض القرى هل يُعتبر غِيبة؟","title":"هل مِن الغِيبة التَّنكيت على بعض البلدان؟","answer":"الجواب: الغيبة ذِكر إنسان مُعَيّن، المجهول ما هي غِيبة.\nس: يعني مثلا يقولون: البلد...؟\nالشيخ: بعض الناس يفعلون كذا، وبعض أهل البلاد يفعلون كذا، هذه ما هي بغِيبة، إلا إذا قيل فلان ابن فلان، المقصود إن ما سَمّي ما يصير غِيبة، البلد ما يضر.\nس: يُعَيّرون أصحاب البلد الفلانية؟\nالشيخ: البلد ما يصير غِيبة، الغِيبة للشخص المعيّن.","link":"https://binbaz.org.sa/fatwas/23214/هل-من-الغيبة-التنكيت-على-بعض-البلدان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التنكيت على بعض القرى هل يعتبر غيبة.mp3","categories":["الآداب والأخلاق"]},{"id":3068,"question":"غسل اليدين قبل الأكل هل ورد فيه شيء؟","title":"حكم غسل اليدين قبل الأكل","answer":"الجواب: ورد فيه حديث ضعيف، لكن إذا كان فيها شيء يغسلها.","link":"https://binbaz.org.sa/fatwas/23228/حكم-غسل-اليدين-قبل-الاكل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم غسل اليدين قبل الأكل.mp3","categories":["الآداب والأخلاق"]},{"id":3071,"question":"بعض الناس يجلسون على السفرة سواء، لكن يضعون في الغرفة صحنًا، وكُلٌّ يغرف في صحن صغير، هل هذا من التفرُّق أحسن الله إليك؟","title":"حكم الغرف بصحن مستقل في طعام جماعي","answer":"الجواب: لا، السُّنة أن يقدّم يديه ويأكل من الطعام المجتمع، وممكن الواحد يغرف لحاله.\nالسؤال: يعتبر من التفرق هذا إن كان غرف من حاله يا شيخ؟\nالشيخ: الأمر سهل، مثل ما لو أكل بيده، يقارب، لكنها تركُها أوْلى.","link":"https://binbaz.org.sa/fatwas/23231/حكم-الغرف-بصحن-مستقل-في-طعام-جماعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/السنة الأكل من الطعام المجتمع.mp3","categories":["الآداب والأخلاق"]},{"id":3077,"question":"أحسن الله إليك يا شيخ، هل ثبت أن النبي ﷺ نهى أن تُؤكل التمرتان في لقمة واحدة؟","title":"حكم أكل التمرتين في لقمة واحدة","answer":"الجواب: إذا كان معه مَن يأكل معه: إلا بإذن، إذا كان معه أصحاب يأكلون معه لا يأكل إلا بإذنهم، أما إذا كان وحده فله أن يأكل تمرتين ثلاثًا ما يخالف، لكن إذا كان معه أصحاب يأكلون لا يَقْرِن لا تمرتين ولا رمانتين ولا فاكهتين، يعني يستأذن في الإقران.\nس:إذا كان الأكل متوفرًا؟\nالشيخ: ولَوْ، إذا كان معه أصحاب لا يقرن إلا بإذنهم.\nس: لا بد من إذن أصحابه؟\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/23237/حكم-اكل-التمرتين-في-لقمة-واحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أكل التمرتين في لقمة واحدة.mp3","categories":["الأطعمة والأشربة","الآداب والأخلاق"]},{"id":3078,"question":"ورد نهيٌ عن إطالة الجلوس على الأكل بعد الانتهاء منه؟","title":"حكم الجلوس بعد الطعام والتصرف ببقاياه","answer":"الجواب: ما بلغني شيء.\n س: إذا كان إنكارٌ لهذا الفعل من شخص جاهل؟\nالشيخ: يُعَلَّم، الجاهل يُعَلَّم.\nس: ما يُعفى عما تناثر من الأكل، أحسن الله عملك؟\nالشيخ: هذا يُتصرف فيه: إما يُعطاه الدواب أو الدجاج أو يُدفن في محل طاهر، وإن أُكل فلا بأس، إذا كانت السفرة نظيفة إذا أُكل فلا بأس.\nس: ما يُنكر على مَن أكله، أحسن الله عملك؟؟\nالشيخ: إذا أُكل فلا بأس، وإن وُضع للدجاج أو غيره أو الحمام أو وُضع في محل طاهر في السطح للطيور؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/23238/حكم-الجلوس-بعد-الطعام-والتصرف-ببقاياه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجلوس على الأكل بعد الانتهاء منه، والتصرف ببقايا الطعام.mp3","categories":["الأطعمة والأشربة","الآداب والأخلاق"]},{"id":3095,"question":"بالنسبة في الحرم بعض الثلاجات يفتح الزرار أن يضغط بيده اليسرى ثم يشرب هل هذا منهي عنه؟","title":"حكم الشرب بالفم مباشرة من برّادة الماء","answer":"الجواب: إذا كان يصب في يده أو في الإناء؟\nس: يدوس على الزرار باليد اليسرى ويشرب بفمه على طول، يشرب بفمه من....\nالشيخ: الماسورة؟\nالطالب: الماسورة نعم.\nالشيخ: مثله تَرْكُه أولى إلا عند الحاجة؛ لأنه قد يخرج شيء يروح في فمه عود أو غيره أو قذاة، يشبه فِيّ السقاء.\nس: استخدام اليد اليسرى؟\nالشيخ: هذا يشبه فِيّ السقاء، يشبه الفم، والخطر من جهة خروج عود أو دابة صغيرة أو شيء يؤذيه.\nس: الحكمة من هذا يعني من باب الخطر؟\nالشيخ: من باب دفع الأذى.","link":"https://binbaz.org.sa/fatwas/23255/حكم-الشرب-بالفم-مباشرة-من-برادة-الماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/يضغط على زرار الثلاجة ليشرب مباشرة بفمه هل يكون من الشرب من في السقاء.mp3","categories":["الآداب والأخلاق"]},{"id":3102,"question":"هل ورد في السنة أن النبي ﷺ أكل بأكثر من ثلاث أصابع؟","title":"حكم الأكل بأكثر من ثلاث أصابع","answer":"الجواب: ما أتذكر شيئًا من هذا، لكن الأمر فيها واسع.\nس: لو أكل بخمس؟\nالشيخ: لا، الأمر فيها واسع، الأفضل ثلاث أصابع إذا تيسر.","link":"https://binbaz.org.sa/fatwas/23262/حكم-الاكل-باكثر-من-ثلاث-اصابع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأكل بأكثر من ثلاث أصابع.mp3","categories":["الآداب والأخلاق"]},{"id":3103,"question":"النهي عن الشرب من في القِرْبة: القصد أن لا يخرج شيء يضُرّه؟","title":"حُكم وحِكْمة النهي عن الشرب مِن فم القِرْبة","answer":"الجواب: ..... الظاهر والله أعلم لئلا يخرج شيء يضره.\nس: ولو في قارورة شفافة مثلًا تُبيّن ما فيها؟\nالشيخ: المقصود ما هو للتحريم، للكراهة، ولهذا شرب مِن فِيِّ القربة عند الحاجة إليه، ولكن إذا تيسر أن لا يشرب إلا في إناء فهو أحوط.","link":"https://binbaz.org.sa/fatwas/23263/حكم-وحكمة-النهي-عن-الشرب-من-فم-القربة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الشرب من في القربة.mp3","categories":["الآداب والأخلاق"]},{"id":3104,"question":"بعض الناس يقول: أن ماء زمزم الأفضل أن يشرب قائمًا؟","title":"حكم شرب ماء زمزم قائمًا","answer":"الجواب: لا، الأفضل قاعدًا لكن إذا ما تيسر يشرب قائمًا.....\nهذه قاعدة، النصوص إذا جاء فيها النهي وما يخالفه؛ دلّ على أن النهي ليس للتحريم.\nس: زمزم كانت الأرض وحلًا يعني لو شرب وهو واقف؟\nالشيخ: لا، شرب قائمًا في غير زمزم ﷺ، مثل حديث النزال بن سمرة وحديث علي ، يقول علي  إن النبي ﷺ شرب قائمًا وقاعدًا.","link":"https://binbaz.org.sa/fatwas/23264/حكم-شرب-ماء-زمزم-قاىما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شرب ماء زمزم قاعدا.mp3","categories":["الآداب والأخلاق"]},{"id":3170,"question":"حكم الأكل قائمًا؟","title":"ما حكم الأكل قائمًا؟","answer":"الجواب: لا بأس؛ الشرب قائما والأكل قائما، لكن الجلوس أفضل.\nس: الأكل نفسه يعني...؟\nالشيخ: الجلوس أفضل.","link":"https://binbaz.org.sa/fatwas/23333/ما-حكم-الاكل-قاىما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الأكل قائما.mp3","categories":["الآداب والأخلاق"]},{"id":3180,"question":"بالنسبة لوضع الرِّجْل على الرِّجْل: بعضهم يعتبرها من التَّكَبُّر حيث إن الإبن لا يضع رجله على الأخرى أمام أبيه أو أمام العالم؟","title":"هل وَضْعُ الرِّجْل على الرِّجْل مِن التَّكَبُّر؟","answer":"الجواب: ما فيه شيء وضع الرِّجْل على الرِّجْل.\nس: ما يكون من التَّكَبُّر؟\nالشيخ: ولا هو من التَّكَبُّر.\nس: جالس على الكرسي ويضع قدمه على ركبته؟\nالشيخ: إذا كان ما تبدو العورة فلا بأس، أي جلسة فعلها لا بأس، بس بشرط ضبط العورة.","link":"https://binbaz.org.sa/fatwas/23343/هل-وضع-الرجل-على-الرجل-من-التكبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم وضع الرجل على الرجل.mp3","categories":["الآداب والأخلاق"]},{"id":3181,"question":"وضع كلتا اليدين وراء ظهره والاتكاء عليها؟","title":"هل يجوز وضع كلتا اليدين وراء الظهر؟","answer":"الجواب: هكذا ما في بأس، النهي هكذا: يضع خلفه يسراه، يسراه خلف ظهره.\nس: إذا كانت اليسرى لا يجوز؟\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/23344/هل-يجوز-وضع-كلتا-اليدين-وراء-الظهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وضع اليدين وراء الظهر والاتكاء عليها.mp3","categories":["الآداب والأخلاق"]},{"id":3182,"question":"بالنسبة لجلسة المغضوب عليهم (الاتكاء على اليد اليُسرى خلف الظهر): في الصلاة فقط، أو في أي جلسة؟","title":"حكم جلسة المغضوب عليهم بالصلاة وغيرها","answer":"الجواب: ظاهر الحديث العموم.\nس: إذا كانت على اليد اليُسرى، فقط اليُسرى؟\nالشيخ: نعم.\nس: قوله: جلسة المغضوب عليهم هل هي ثابتة؟\nالشيخ: ظاهر الحديث النهي عن جلسة المغضوب عليهم.\nس: صحيح...؟\nالشيخ: لا بأس به.","link":"https://binbaz.org.sa/fatwas/23345/حكم-جلسة-المغضوب-عليهم-بالصلاة-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/جلسة المغضوب عليهم.mp3","categories":["الآداب والأخلاق"]},{"id":3208,"question":"الذي يَقْلِب نومه إلى النهار يقال إنه خالف السنة أو الفطرة، هل هذا صحيح؟","title":"ما حكم مَنْ يسهر بالليل وينام بالنهار؟","answer":"الجواب: لا شك أنه خلاف المشروع، المشروع أنه إذا صلى العشاء ينام، الرسول ﷺ كره النوم قبلها والحديث بعدها. الناس الآن كثير منهم يسهر في الليل وينام في النهار، هذا خلاف المشروع وخلاف السنة.","link":"https://binbaz.org.sa/fatwas/23371/ما-حكم-من-يسهر-بالليل-وينام-بالنهار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من خالف النوم في الليل فقد خالف السنة.mp3","categories":["الآداب والأخلاق"]},{"id":3209,"question":"الرؤيا خاصة بالمؤمن؟ يعني ما يرى هذه الرؤيا وتصدُق رؤياه إلا المؤمن أم الكافر والمؤمن؟","title":"هل الرؤيا الصادقة خاصة بالمؤمن؟","answer":"الجواب: هذا محل نظر، قد يرى الرؤيا الكافر وتصدق، ايش المانع؟ س: مثل صاحبي يوسف اللذين في السجن؟ الشيخ: المقصود أن هذا يفيد أن أصدق الناس في الدنيا حديثًا أصدقهم رؤيا، يعني أقرب، وإن لم يكون المؤمن، كونه كافرًا يرى أو العاصي يرى هذا لا مانع؛ لأن الرؤيا تقع من الكافر ومن الفاجر، لكن أصدق الناس رؤيا أصدقهم حديثا في الدنيا. س: أصدقهم حديثًا يعني في كل الأعمال الصالحة؟ الشيخ: يعني: كل ما كان أصدق في الدنيا كان أقرب إلى صدق رؤياه، ولاسيما إذا نام على طهارة، فأقرب الناس صدقًا في الرؤيا أقربهم صدقًا في الحياة وأكثرهم استقامة في الحياة. س: ذكر النووي في كتاب الأذكار أن عائشة رضي الله عنها كانت إذا أوت إلى فراشها تسأل الله عز وجل أن يريها رؤيا صادقة؟ الشيخ: ما أدري. س: هل يشرع للمؤمن...؟ الشيخ: الله أعلم.","link":"https://binbaz.org.sa/fatwas/23372/هل-الرويا-الصادقة-خاصة-بالمومن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الرؤيا الصادقة خاصة بالمؤمن.mp3","categories":["الآداب والأخلاق"]},{"id":3211,"question":"قوله: ولا يذكرها لأحد للتحريم؟","title":"ما حكم التحديث بالرؤى المنامية؟","answer":"الجواب: في رواية إلا من يحب يُحَدّث بها من يحب. أما رؤية الشيطان لا يُحَدّث بها أحدا.\nس: للكراهة أم للتحريم؟\nالشيخ: الأصل في النهي التحريم، هذا هو الأصل، هذه قاعدة: الأصل في نهي النبي ﷺ التحريم، إلا ما يدل على الكراهة .","link":"https://binbaz.org.sa/fatwas/23374/ما-حكم-التحديث-بالروى-المنامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التحديث بالرؤيا.mp3","categories":["الآداب والأخلاق"]},{"id":3213,"question":"الرؤيا أو الحلم إذا استمر مع الشخص مدة طويلة مثل سنة أو سنتين، رؤيا يعني خبيثة، هل يحاول أنه يفسرها؟","title":"هل استمرار الرؤيا بالمنام مدة طويلة له دلالة؟","answer":"الجواب: لا ما لها أصل.\nس: ولو استمرت؟\nالشيخ: ما لها أصل ولو استمرت.","link":"https://binbaz.org.sa/fatwas/23376/هل-استمرار-الرويا-بالمنام-مدة-طويلة-له-دلالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا استمرت الرؤيا مدة طويلة.mp3","categories":["الآداب والأخلاق"]},{"id":3221,"question":"إذا ما ردّ السلام يكون آثما؟","title":"هل يأثم مَنْ لم يرد السلام؟","answer":"الجواب: الإثم على مَنْ لم يرد السلام، أنت تفشي السلام، والواجب رد السلام، والذي لا يرد يأثم.\nس: الرد عليه يكون بمثله؟\nج: بمثله وأحسن.","link":"https://binbaz.org.sa/fatwas/23384/هل-ياثم-من-لم-يرد-السلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يأثم من لم يرد السلام.mp3","categories":["الآداب والأخلاق"]},{"id":3223,"question":"المصافحة: من دخل المجلس وكان الناس جلوسًا: هل يجب أن يصافحهم واحدًا واحدًا؟","title":"هل يلزم مَن دخل مجلسًا مصافحة الجميع؟","answer":"الجواب: لا لا، إذا سلم عليهم كفى، ويجلس حيث ينتهي المجلس.","link":"https://binbaz.org.sa/fatwas/23386/هل-يلزم-من-دخل-مجلسا-مصافحة-الجميع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مصافحة من دخل المجلس.mp3","categories":["الآداب والأخلاق"]},{"id":3225,"question":"أحيانَا تأتي مكالمة لأحد الزملاء ثم يقول الزميل: \"لحظة شوية باشوفه فيه وإلا لا\"، يقوم الآخر من المكتب، يقول: الآن ما هو موجود على المكتب. هل يعتبر هذا كذبًا أو تورية؟","title":"حكم التَّوْرِية في الكلام عند الحاجة","answer":"الجواب: إن كان صادقًا ما هو بكذب، يعني يتكلم وهو ما هو موجود.\nس: هو يتأخر عن المكتب عشان ذاك يقول ما هو موجود؟\nالشيخ: هذا من باب التورية، مثل ما يُروى عن أحمد لما سُئل عن المروذي قال: المروذي ليس هاهنا، المروذي ما هو في راحته، المروذي.\nس: يعني ما في شيء؟\nالشيخ: التأويل إذا دعت الحاجةُ إليه ما فيه شيء، أو قال: في البيت ليس هنا، يعني ليس في المجلس اللي هو فيه، أو ليس في مكانه الذي هو فيه، عند الحاجة، وإلا لا ينبغي.","link":"https://binbaz.org.sa/fatwas/23388/حكم-التورية-في-الكلام-عند-الحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في التورية في الكلام.mp3","categories":["الآداب والأخلاق"]},{"id":3230,"question":"بعض الأمهات تَقُصّ على أولادها حتى يناموا قصصًا ما هي صحيحة؟","title":"حكم الكذب في قصص الأم لأولادها قبل النوم","answer":"الجواب: سواليف يعني؟\nس: نعم، هذا يعتبر من الكذب؟\nالشيخ: الله أعلم، الله أعلم، تتحرى الأشياء التي تناسب ولا تكذب.","link":"https://binbaz.org.sa/fatwas/23393/حكم-الكذب-في-قصص-الام-لاولادها-قبل-النوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم قصص الأمهات لأولادهن كي يناموا.mp3","categories":["الآداب والأخلاق"]},{"id":3260,"question":"لعنُ الكافر؟","title":"ما حكم لعن الكفّار والظَّلمة غير المعينين؟","answer":"الجواب: على العموم لا بأس، لعن الله الكافرين، لعن الله الظالمين، وأما المُعَيّن فتركه أحوط؛ لأنه قد يُسلم وقد يهديه الله، وهكذا الميت لا يُسَبّ.\nس: وكذلك لو كان كافرًا؟\nالشيخ: لا يُلعن الحيُّ المعيّن إلا إذا كان معروفًا بالشر والفساد على المسلمين، مثل ما لعن النبي ﷺ أعيانًا من جماعة مكة؛ لكفرهم الشديد وعنادهم وظلمهم للمسلمين.\nس: ومَنْ مات على الكفر؟\nالشيخ: لا تَسُبُّوا الأموات فقد أفضوا إلى ما قدموا يقوله ﷺ.","link":"https://binbaz.org.sa/fatwas/23424/ما-حكم-لعن-الكفار-والظلمة-غير-المعينين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لعن الكفّار والظلمة غير المعينين.mp3","categories":["الآداب والأخلاق"]},{"id":3273,"question":"بعض الناس إذا قلت له: لا تُعَيّره، قال: ما يعرفونه الناس إلا بمعايرته؟","title":"حكم مَناداة الشخص بعَيْبٍ لا يُعرف إلا به","answer":"الجواب: هذا إذا كان يُعرف بها ما يضر، مثل ما يقال الأعمش والأعرج، مثل التابعين الأعمش والأعرج؛ كلهم من التابعين ومن ثقاة الرواة، عُرفوا بهذا، كذلك الأعور عُرف بهذا، ما تصير غِيبة ما دام لقبٌ له يُعرف به، ما تصير غِيبة.","link":"https://binbaz.org.sa/fatwas/23437/حكم-مناداة-الشخص-بعيب-لا-يعرف-الا-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من كان لا يعرف إلا بمعايرته.mp3","categories":["الآداب والأخلاق"]},{"id":3282,"question":"الحق الدنيوي بينه وبين صاحبه يكون صاحبه مقيمًا على الظلم أو مقيمًا على الاحتقار له واحتقار الناس: هل يجوز له يَفُوت ثلاثة أيام؟","title":"حكم ومدة هَجْر المُقيم على ظلم أو منكر؟","answer":"الجواب: ثلاثة أيام فقط، يصير أفضل منه، يرد عليه، وإنْ ما رد فالإثم عليه، مَنْ بدأ بالسلام خيرهم، مثل ما قال في حديث أبي أيوب في الصحيحين: خيرهما الذي يبدأ بالسلام.\nس: وإنْ كان مقيمًا على الظلم؟\nالشيخ: وإنْ كان مقيمًا، يعني الحق لك.\nس: ما يكون الهجر للمعصية؟\nالشيخ: لا، هذا حق لك، حق للمخلوق.","link":"https://binbaz.org.sa/fatwas/23446/حكم-ومدة-هجر-المقيم-على-ظلم-او-منكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز الهجر أكثر من ثلاثة أيام لمن كان مقيما على الظلم.mp3","categories":["الآداب والأخلاق"]},{"id":3284,"question":"(ما) الفرق بين التَّجَسُّس والتَّحَسُّس ؟","title":"ما الفرق بين التَّجَسُّس والتَّحَسُّس؟","answer":"الجواب: التَّحَسُّس بالقول، والتَّجَسُّس بالفعل. نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/23448/ما-الفرق-بين-التجسس-والتحسس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفرق بين التجسس والتحسس.mp3","categories":["الآداب والأخلاق"]},{"id":3300,"question":"قد يَمُرُّ الإنسان بنصارى أو يهود أو لا يعلم بحالهم ألا يُسلّم عليهم؟","title":"حكم إلقاء السلام على مَنْ لا يُعْلَم بحالهم","answer":"الجواب: يُسلّم على من لَقِي، مثل ما قال ﷺ لما سئل: أي الإسلام أفضل؟ قال: تطعم الطعام وتقرأ السلام على من عرفت ومن لم تعرف، إلا إذا عرف أنه يهودي فلا يبدأه أو نصراني أو غيره من الكفرة لا يبدأه، أما إذا لم يَعْرِف يُسلّم على من لَقِي. س: إذا كان له حاجة عنده؟ الشيخ: لا يُسلّم عليه، يقول: كيف حالك؟ كيف أنت؟ كيف أبناؤك؟ ما يقول: السلام عليكم.","link":"https://binbaz.org.sa/fatwas/23465/حكم-القاء-السلام-على-من-لا-يعلم-بحالهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم إلقاء السلام على من لا يعلم بحالهم.mp3","categories":["الآداب والأخلاق"]},{"id":3339,"question":"يحتج بعض الناس بحديث: لا غيبة لفاسق؟","title":"حكم غيبة الفاسق ومَنْ أظهر المعاصي","answer":"الجواب: لا، الحديث ما أدري بصحته، لكن معروف من أدلة أخرى؛ يقول النبي ﷺ في الرجل الذي دخل عليه: بئس أخو العشيرة، احتجوا به على أن من أظهر المعاصي لا غيبة له.  لكن المؤمن يتحرّى، قد يكون في غيبته وهو مُظْهر فساد يترتب عليه شر، كَوْنُه ينصحه ويوجهه أحسن من كونه يغتابه مهما أمكن. لكن إثم الغيبة إنما يحصل فيمن لم يُعلِن المعاصي، أما من كان يُعلِن المعاصي، ويظهرها بين الناس، يشرب الخمر بين الناس، لا يصلي مع الجماعة، هذا لا غيبة له فيما أظهر، يدخّن في الأسواق عند الناس لا غيبة له، حالق لحيته الناس يرونها لا غيبة له، لكن إذا رأى من المصلحة أن ينصحه سرًّا، وأن لا يتكلم في عرضه؛ لعله يهتدي؛ قد يكون هذا خيرًا، وقد يترتب عليه خير عظيم.","link":"https://binbaz.org.sa/fatwas/23505/حكم-غيبة-الفاسق-ومن-اظهر-المعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم غيبة الفاسق، ومن أظهر المعاصي.mp3","categories":["شروح الحديث","الآداب والأخلاق"]},{"id":3341,"question":"إذا كان هذا المغتاب في المجلس لا يعرفه إلا المتكلّم؟","title":"حكم الغِيبة لمن لا يُعْرَف إلا للمتكلّم","answer":"الجواب: ولو، لا يسمّى أحدًا، يقول: الغيبة حرام، وحلق اللحية حرام، وأكل الربا، ولا يقول فلان الفلان، ما هو بلزوم.","link":"https://binbaz.org.sa/fatwas/23507/حكم-الغيبة-لمن-لا-يعرف-الا-للمتكلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الغيبة في المجلس لمن لا يُعرف إلا للمتكلم.mp3","categories":["الآداب والأخلاق"]},{"id":3342,"question":"بعض رواة الحديث كابن عُلَيَّة يقول: من سمّاني ابن علية فقد اغتابني؟","title":"هل مِن الغِيبة ذِكْرُ بعض الرواة بما يَكرهون؟","answer":"الجواب: ولو إذا كان ما يُعْرَف إلا بذلك لا حرج، مثلما يقال الأعور، والأعمى؛ للتعريف، ما هو بقَصد الغيبة، ولو قال، هذا من باب التعريف، ولهذا جرّح العلماء الرواة الضعفاء، والمجروحين، إذا كان في جَرْحه مصلحة، مثلما ضبطه بعضهم في البيتين: لأن الغيبة يحتاج إليها للمصلحة الشرعية. س: طيب النووي يا شيخ يقول: لا أجعل أحدًا في حل سمّاني أو لقبني محي الدين، فهل يُعْرَض عنه؟ الشيخ: ما أدري والله عن صحة هذا عن النووي، لكن هذه ما هي بغِيبة، هذه مصلحة.","link":"https://binbaz.org.sa/fatwas/23508/هل-من-الغيبة-ذكر-بعض-الرواة-بما-يكرهون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من الغيبة ذكر بعض الرواة بما يكرهون، واشتهروا به.mp3","categories":["الآداب والأخلاق","الحديث وعلومه"]},{"id":3343,"question":"إذا كان يترتب على غِيبة الفاسد مفاسد؟","title":"ما الحكم إذا ترتب على غِيبة الفاسد مفاسد؟","answer":"الجواب: لا يفعل، ينصحه، ولا يغتابه.  لكن المُعْلِن: إذا رأى أن في تركه مفاسد لا يتكلم فيه؛ لأن المؤمن يراعي المصالح والمفاسد، ما هو يهجم، وبس.","link":"https://binbaz.org.sa/fatwas/23509/ما-الحكم-اذا-ترتب-على-غيبة-الفاسد-مفاسد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا ترتب على غيبة الفاسد مفاسد.mp3","categories":["الآداب والأخلاق"]},{"id":3344,"question":"الأبيات التي تجمع الحالات التي تجوز فيها الغِيبَة: ما ذكر فيها كله صحيح؟","title":"ما الحالات التي تجوز فيها الغِيبَة؟","answer":"الجواب: والله هو الظاهر. كلها، واضحة: المُعَرِّف: الأئمة عرّفوا المجروحين. والمحذر من أهل البدع كذلك.  والناصح معروف كذلك. المُظْهِر لفِسْق، والمُستفتي: كالمرأة قالت: يا رسول الله إن أبا سفيان رجل شحيح، تستفتي. ومن طلب الإعانة في إزالة منكر، وتعاون ليزيل المنكر الموجود في المحل الفلاني.","link":"https://binbaz.org.sa/fatwas/23510/ما-الحالات-التي-تجوز-فيها-الغيبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حالات جواز الغيبة هل كلها صحيحة.mp3","categories":["الآداب والأخلاق"]},{"id":3345,"question":"المُسْتَشِير: هل يجوز غِيبة إنسان في زواج ؟","title":"ما حكم الغِّيبة عند الاستشارة في الزواج؟","answer":"الجواب: المُسْتَشِير مُسْتَنْصِح.\nس: يعني ما هو بغِيبة؟\nالشيخ: لا.","link":"https://binbaz.org.sa/fatwas/23511/ما-حكم-الغيبة-عند-الاستشارة-في-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تجوز الغيبة عند الاستشارة.mp3","categories":["الآداب والأخلاق"]},{"id":3423,"question":"تسمية البنت بإيمان، وببشرى، وبآلاء؟","title":"ما حُكم أسماء إيمان وبشرى وآلاء للبنات؟","answer":"الجواب: ما أعلم فيه شيء، بشرى، وآلاء، وإيمان، ما أعلم فيها شيء.","link":"https://binbaz.org.sa/fatwas/23597/ما-حكم-اسماء-ايمان-وبشرى-والاء-للبنات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تسمية البنات بإيمان، وببشرى، وبآلاء...mp3","categories":["الآداب والأخلاق"]},{"id":3746,"question":"من رد بدل السلام بـ\"هلا\" \"يا مرحب\" ما يكون عاصيًا؟","title":"حكم رد السلام بقول \"هلا\" أو \"مرحبا\"","answer":"الجواب: خالف السنة، الواجب عليه أن يرد \"وعليكم السلام\"؛ لأن الله قال: وَإِذَا حُيِّيتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا [النساء:86] ولكن يُعلَّم  ويُوَجّه إلى الخير.","link":"https://binbaz.org.sa/fatwas/23938/حكم-رد-السلام-بقول-هلا-او-مرحبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم رد السلام بهلا أو يا مرحب.mp3","categories":["الآداب والأخلاق"]},{"id":3747,"question":"السلام بالإشارة؟","title":"هل يجوز السلام بالإشارة دون كلام؟","answer":"الجواب: باللفظ، لكن إذا كان بعيدًا يشير له حتى يفهم حتى يعلم أنه سلم، يعني مر على النسوة فأشار إليهن.  المقصود إذا كان يحتاج إلى إشارة لبُعدهم أو قلة سمعهم يشير مع الكلام، ولا يجوز السلام بالإشارة.","link":"https://binbaz.org.sa/fatwas/23939/هل-يجوز-السلام-بالاشارة-دون-كلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم السلام بالإشارة.mp3","categories":["الآداب والأخلاق"]},{"id":3748,"question":"حكم رد السلام؟","title":"ما حكم رد السلام؟","answer":"الجواب: واجب، بخلاف البدء: هل يجب أو ما يجب؟ أما الرد واجب؛ لأن الله يقول: وَإِذَا حُيِّيتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا [النساء:86] فالتحية بالأحسن أفضل، والرد واجب.","link":"https://binbaz.org.sa/fatwas/23940/ما-حكم-رد-السلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم رد السلام.mp3","categories":["الآداب والأخلاق"]},{"id":3749,"question":"بعض الناس قد يرى شخصًا عليه فسق أو... أو إسبال، ولا يسلم عليه؟","title":"هل يُلقى السلام على صاحب المعصية؟","answer":"الجواب: لا، المشروع السلام وينصح فإنه قد يكون جاهلاً، السنة السلام؛ لما فيه من الإيناس والتقارب، وهو أيضًا مفتاح للنصيحة، إلا إذا كان معاندًا، وهو يعرف أنه معاند، ورأى أن هجره أصلح، وأنه يؤثر عليه وينفعه هجره، وإذا رأى أن هجره ليس بأصلح وأن الاستمرار في النصيحة والإنكار يكون أنفع؛ فعل ما هو الأصلح.\nس: من مر على شارب الدخان يسلم عليه؟\nالشيخ: نعم، تسلم، وتنصحه، تبين له أن هذا منكر.","link":"https://binbaz.org.sa/fatwas/23941/هل-يلقى-السلام-على-صاحب-المعصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/السلام على صاحب المعصية.mp3","categories":["الآداب والأخلاق"]},{"id":3750,"question":"المرأة تسلم على الرجال؟","title":"ما حكم سلام المرأة على الرجال؟","answer":"الجواب: نعم، والرجال يسلّمون على النساء إذا كان ما فيه ريبة، سلم النبي على النساء وسلمن عليه عليه الصلاة والسلام، وسلمن على الصحابة.","link":"https://binbaz.org.sa/fatwas/23942/ما-حكم-سلام-المراة-على-الرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تسلم المرأة على الرجال.mp3","categories":["الآداب والأخلاق"]},{"id":3752,"question":"فيه فرق بين \"السلام عليكم\" و\"سلامٌ عليكم\"؟","title":"ما الفرق بين \"السلام عليكم\" و\"سلامٌ عليكم\"؟","answer":"الجواب: هذا جائز وهذا جائز، والأفضل \"السلام عليكم\"، وإن قال: \"سلام عليكم\"؛ فلا بأس، يُسلّم في البدء، النبي ﷺ لما كتب إلى هرقل، قال: سلام على من اتبع الهدى؛ للتنكير كما ذكره الشارح في قول: سَلَامٌ عَلَى نُوحٍ فِي الْعَالَمِينَ[الصافات:79] وقول إبراهيم: سَلَامٌ قَوْمٌ مُنْكَرُونَ [الذاريات:25] فلا بأس.","link":"https://binbaz.org.sa/fatwas/23944/ما-الفرق-بين-السلام-عليكم-وسلام-عليكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفرق بين السلام عليكم وسلام عليكم.mp3","categories":["الآداب والأخلاق"]},{"id":3753,"question":"يبدأ بالمفرد \"السلام عليك\"؟","title":"حكم قول \"السلام عليك\" بالإفراد","answer":"الجواب: يجوز هذا وهذا، السلام عليك، والسلام عليكم، إذا كان واحدًا السلام عليك، والغالب أن النبي ﷺ كان يقول: السلام عليكم؛ فالأفضل الجمع.","link":"https://binbaz.org.sa/fatwas/23945/حكم-قول-السلام-عليك-بالافراد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قول السلام عليك بالمفرد في السلام.mp3","categories":["الآداب والأخلاق"]},{"id":3784,"question":"ما ثبت أنَّ النبي فعله من باب العادات يُعتبر سنةً أو عادةً؟ يعني: \"ما أكل على خوانٍ قط\" سنة ألا يأكل الإنسانُ على خوانٍ؟","title":"ما معنى \"خوان\"؟ وهل يجوز الأكل عليه؟","answer":"الجواب: هو جاء في بعض الروايات ما يدل على أنه أكل على خوانٍ في بعض الأحيان.  وهذه الأمور هي أشبه بالعادات، مثل: الملابس، والمآكل، والأواني، وأشباه ذلك، إلا الشيء الذي ثبت النَّهي عنه، مثل: الذهب والفضة، وإلا فالأصل أنَّ هذه من الأمور العادية التي يتفاوت الناسُ فيها ويختلفون، لا يُنكر فيها شيء.\nس: الخوان هو السُّفرة؟\nج: الخوان: شيء مُرتفع له قوائم، والسفرة أعم: الشيء الذي على قوائم، والشيء المبسوط في الأرض، مثل: الأنطاع يُقال لها: سفرة، والسفرة التي على قوائم كذلك مثل: الخوان.","link":"https://binbaz.org.sa/fatwas/23981/ما-معنى-خوان-وهل-يجوز-الاكل-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما أكل على خوانٍ قط هل من السنة ألا يأكل الإنسانُ على خوانٍ.mp3","categories":["شروح الحديث","الآداب والأخلاق"]},{"id":3790,"question":"ما ورد من النَّهي في التَّكلف للضيف صحيح؟","title":"هل صح شيء في النَّهي في التَّكلف للضيف؟","answer":"الجواب: ما أتذكر فيها شيئًا إلا قوله تعالى: قُلْ مَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ [ص:86].\nعلى كل حالٍ، النصوص إذا تأمَّلها المؤمنُ يظهر منها أنه لا ينبغي التَّكلف، وأنه ينبغي للمسلمين فيما بينهم أن يتسامحوا؛ حتى تحصل المودة، ويحصل التعاون والتَّزاور، أما مع التَّكلف فيقلّ ذلك، والواقع من فعل الصحابة يدل على هذا، وسمعت قصة عتبان بن مالك: \nدعا النبيَّ يُصلي في بيته، والمسافة بعيدة، ولم يصنع إلا عصيدة، عصيدة قدَّمها لهم، حريرة، والعصيدة تقدَّم لكم بيانها، وأنها عصيدة من الدقيق يُلقى فيها بعض الأحيان شيء من الشحم، وبعض الأحيان تُلقى فيها قطع صغيرة من اللحم، هذا معروف عند أهل نجد أيضًا، من قديم يصنعون هذه العصائد، يجعلون فيها شيئًا من الدهن –الشحم- أو شيئًا من اللحم القليل، قطعًا قليلة.\nوهذا... فيما مضى... في حالة المدينة من كل الوجوه، لا من جهة أنهم يعيشون على التمر، ولا من جهة الطعام، وأنه طعام خفيف، وأنه من الحنطة، وأنه يوضع فيه شيء قليل من الشحم أو من اللحم القليل الذي يُقددونه، كما فعلت العربُ، وهو اللحم الذي ييبس ثم \nيُؤكل منه قليلًا قليلًا في الطعام، كان هذا معروفًا في أول هذا القرن -في أول القرن الرابع عشر الماضي وفيما قبله- فيما ذكره العارفون بنجدٍ، لكن اتسعت الدنيا على الناس، كما اتسعت عليهم في عهد بني أمية، وعهد بني العباس، واتسعت هنا في النصف الأخير من \nالقرن الماضي، وفي هذا الوقت.","link":"https://binbaz.org.sa/fatwas/23988/هل-صح-شيء-في-النهي-في-التكلف-للضيف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النَّهي في التَّكلف للضيف.mp3","categories":["الآداب والأخلاق"]},{"id":3791,"question":"القِران خاصٌّ بالتمر، وإلا يكون في كل الطعام؟","title":"هل النهي عن القِران يشمل غير التمر؟","answer":"الجواب: مثلما قال المؤلف، فيما يُشبهه: حبّ العنب والزبيب وأشباه ذلك، الشيء الذي هو حبَّات تُؤكل، إلا إذا تسامحوا فيما بينهم وسمحوا له بأن يقرن ما في بأس.","link":"https://binbaz.org.sa/fatwas/23990/هل-النهي-عن-القران-يشمل-غير-التمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النهي عن القرآن في الأكل خاصٌّ بالتمر أو في كل الطعام.mp3","categories":["الآداب والأخلاق"]},{"id":3831,"question":"النَّهي للتَّحريم أو التَّنزيه؟","title":"حكم اختناث الأسقية (الشرب من فم القربة)","answer":"الجواب: ظاهره التنزيه؛ لأنه ورد الشرب منها عند الحاجة، فالأصل في هذا التحريم، لكن المراد من شربه منها في بعض الأحيان... للأدب والكراهة والحماية مما يضرّ الإنسان.","link":"https://binbaz.org.sa/fatwas/24033/حكم-اختناث-الاسقية-الشرب-من-فم-القربة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث سمعت رسول الله ينهى عن اختناث الأسقية، النهي للتحريم أو التنزيه.mp3","categories":["شروح الحديث","الآداب والأخلاق"]},{"id":3832,"question":"ترجم هذه الترجمة في السابق \"اختناث الأسقية\"؟","title":"حكم الشرب من فم السقاء","answer":"الجواب: الظاهر للتأكيد، يعني بيان حكمه، يعني أول الإشارة إلى قصة المرأة التي شرب النبيُّ من سقائها، وأن هذا للكراهة، وإلا هو مفهوم مما تقدَّم، الاختناث: الشرب مِنْ فِيها، فيكون معنى الثاني: هذا باب الشرب من فم السقاء، يعني حكمه، وأن حكمه الكراهة، بدليل أنه وُجد منه الشرب ﷺ في بعض الأحيان.\nوالمقصود: أنَّ الأصل هو النَّهي، والأصل فيه التَّحريم، فلما جاء شربه ﷺ من في السقاء في بعض الحاجات دلَّ على النهي للكراهة، لا للتحريم الذي فيه الإثم؛ لأنه من باب الأدب، ومن باب الحماية للإنسان مما يضرُّه، فيكون هذا من باب الكراهة، ومن باب التوجيه إلى الخير والمصلحة، فإذا دعت الحاجةُ إلى الشرب مِنْ فِيِّ السقاء زالت الكراهة.","link":"https://binbaz.org.sa/fatwas/24034/حكم-الشرب-من-فم-السقاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الشرب من فم السقاء.mp3","categories":["الآداب والأخلاق"]},{"id":3927,"question":"التلقيب بما يكره، ولو علم أنه يكره اللقب هذا؟","title":"هل مِن الغِيبة تلقيب الشخص بما يكره؟","answer":"الجواب: إذا عُرف به ما يضر، إذا كان معروفًا به ما يسمى غيبة.\nس: إذا كان له اسم، فلماذا ندعوه أعرج واسمه محمد؟\nالشيخ: ما يضر، إذا عُرف بذلك لا بأس.","link":"https://binbaz.org.sa/fatwas/24146/هل-من-الغيبة-تلقيب-الشخص-بما-يكره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من الغيبة التلقيب بما يكره.mp3","categories":["الآداب والأخلاق"]},{"id":3928,"question":"صنيع البخاري يرى النَّميمة مرادفة للغِيبة..؟","title":"هل النميمة مرادفة للغِيبة؟","answer":"الجواب: يظهر من ترجمته أن الغِيبة ملحقة بالنَّميمة، كما أن النميمة تثير الشر والفتن فهكذا الغِيبة؛ فإن المغتاب إذا بلغه الخبر تأثر، وربما أفضى إلى تضاربه أو تساببه مع صاحب الغِيبة أو ما هو أكبر من ذلك؛ فصارت من جنس النميمة من هذه الحيثية، ولهذا ترجم في ذلك ليحذر من الغِيبة بما جاء في النميمة.","link":"https://binbaz.org.sa/fatwas/24147/هل-النميمة-مرادفة-للغيبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل النميمة مرادفة للغيبة.mp3","categories":["الآداب والأخلاق"]},{"id":3931,"question":"الأثر \"لا غِيبة لمجهول\"؟","title":"هل صح في الأثر \"لا غِيبة لمجهول\"؟","answer":"الجواب: النبي ﷺ بيّن الغِيبَة، يعني ما حاجة إلى هذا الكلام الكثير، النبي ﷺ قال: ذكرك أخاك بما يكره ضبطها عليه الصلاة والسلام، هذا الكلام الذي نقل عن النووي وغيره، هذا هو كلام النبي ﷺ: ذكرك أخاك بما يكره النبي ﷺ ضبط هذا وحده.","link":"https://binbaz.org.sa/fatwas/24150/هل-صح-في-الاثر-لا-غيبة-لمجهول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لا غيبة لمجهول.mp3","categories":["الآداب والأخلاق"]},{"id":3933,"question":"من يدعي العلم وهو يدعو الناس إلى الخرافات والبدع يحذر منه، هل يعتبر غيبة؟","title":"هل من الغيبة التحذير من مُدّعي البدع؟","answer":"الجواب: يُحَذَّر من عمله السيئ.. الفاسق لا حرمة له.","link":"https://binbaz.org.sa/fatwas/24152/هل-من-الغيبة-التحذير-من-مدعي-البدع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من الغيبة التحذير من مدعي البدع.mp3","categories":["الآداب والأخلاق"]},{"id":3938,"question":"الحديث الأول في الباب الأول: باب من زار صاحبه بكرة وعشيًا؛ يدل على جواز الزيارة في البكرة؟","title":"حكم التزاور بكرة وعشيًّا","answer":"الجواب: نعم، نعم، وقول بعضهم \"زر غبًّا تزدد حبًّا\" ما له أصل يعتمد عليه، الزيارة تختلف على حسب الحاجة، قد تكون الحاجة كل يوم، قد تكون بكرة وعشيًّا، وقد تكون أكثر من ذلك، على حسب الحاجة.","link":"https://binbaz.org.sa/fatwas/24159/حكم-التزاور-بكرة-وعشيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/باب من زار صاحبه بكرة وعشيًا.. هل يجوز الزيارة في البكرة.mp3","categories":["الآداب والأخلاق"]},{"id":3952,"question":"الحياء المذموم هو الخجل؟","title":"ما حقيقة الحياء المذموم والخجل؟","answer":"الجواب: الضعف الذي يمنع من تعاطي الإنسان ما ينبغي من قول الخير وفعل الخير والصدع بالحق.","link":"https://binbaz.org.sa/fatwas/24175/ما-حقيقة-الحياء-المذموم-والخجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الحياء المذموم هو الخجل.mp3","categories":["الآداب والأخلاق"]},{"id":3955,"question":"الحياء خُلُق جِبِلِيٌّ وإلا مكتسب؟","title":"هل الحياء خُلُق جِبِلِيٌّ أم مُكتسب؟","answer":"الجواب: أصله خِلقة، ولكن يُكتسب بالمزيد.","link":"https://binbaz.org.sa/fatwas/24178/هل-الحياء-خلق-جبلي-ام-مكتسب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الحياء خلق جبلي أو مكتسب.mp3","categories":["الآداب والأخلاق"]},{"id":3958,"question":"متى يكون الجود مذمومًا؟","title":"ما الأحوال التي يكون الجود مذمومًا؟","answer":"الجواب: إذا كان في غير محله، يعطيه من يستعين به على المعاصي أو يعطيه السفهاء يلعبون بالأموال، أو الجود في غير محل الجود؛ في شراء ما حرم الله، أو في إضاعة الأموال. إنما يكون الجود في محله؛ للمحتاجين والفقراء والمساكين، في إقامة المشاريع الخيرية، قضاء دين المدينين، صرف الأموال للجهاد في سبيل الله، إعتاق الرقاب، وأشباه ذلك مما هو ممدوح شرعًا.","link":"https://binbaz.org.sa/fatwas/24183/ما-الاحوال-التي-يكون-الجود-مذموما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يكون الجود مذمومًا.mp3","categories":["الآداب والأخلاق"]},{"id":3973,"question":"بالنسبة للسلام على بنات العم أو بنات الخالة؟","title":"ما حكم السلام على بنات العم والخالة؟","answer":"الجواب: من الأقارب من الرحم التي توصل، لكن من دون مصافحة ومن دون تقبيل، بالكلام بس، مع الحجاب وعدم الخلوة.","link":"https://binbaz.org.sa/fatwas/24201/ما-حكم-السلام-على-بنات-العم-والخالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم السلام على بنات العم أو بنات الخالة.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":3975,"question":"قول \"مرحبًا\" بعد السلام؟","title":"حكم قول \"مرحبًا\" بعد السلام","answer":"الجواب: نعم بعد السلام، وبعد الرد، نعم.\nس: هل في الحديث ما يدل على أنه سلم ثم قال: مرحبا؟\nالشيخ: لا، عملًا بالأصل، الأصل مثل ما قال الله جل وعلا: وَإِذَا حُيِّيتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا [النساء:86] النبي ﷺ قال: وعليكم  فلا بدّ أن يفعل ما أمر به الناس عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/24203/حكم-قول-مرحبا-بعد-السلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم قول مرحبًا بعد السلام.mp3","categories":["الآداب والأخلاق"]},{"id":3979,"question":"هل يطلق الخبث على نفس الآخر، هذا نفسه خبيثة؟","title":"هل يجوز قوله \"هذا نفسه خبيثة\"؟","answer":"الجواب: على حسب حاله، كما يقال: الكافر خبيث، والمنافق خبيث، والكلمة خبيثة إذا كانت كلمته رديئة، والعمل خبيث إذا كان العمل معصية: وَيُحِلُّ لَهُمُ الطَّيِّبَاتِ وَيُحَرِّمُ عَلَيْهِمُ الْخَبَائِثَ [الأعراف:157]","link":"https://binbaz.org.sa/fatwas/24207/هل-يجوز-قوله-هذا-نفسه-خبيثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يقال هذا نفسه خبيثة.mp3","categories":["الآداب والأخلاق"]},{"id":3990,"question":"المعاريض هذه قد يقع من بعض الناس لمصالحه الخاصة؟","title":"حكم استعمال المعاريض للمصلحة الخاصة","answer":"الجواب: المعاريض فيها مندوحة عن الكذب، وهي أن يأتي بكلمة تسد الباب ولا يحصل بها الكذب، ولكن قد يُفهم منها غير المطلوب؛ لأنه لا يريد أن يكذب، يتحرّج أن يكذب؛ فيأتي بكلمة لا تعتبر كذبًا ويعتبر بها قد تخلص إذا كان ليس بظالم، إذا كان ليس بظالم بل مظلوم، أو أنه لا ظالم ولا مظلوم، هذا لا بأس. أما إن كان ظالمًا ما ينفعه التأويل، مثل ما قال النبي ﷺ: اليمين على نية المستحلف، وفي اللفظ الآخر: يمينك على ما يصدقك عليه صاحبك رواه مسلم، فإذا كان ظالماً لا ينفعه التأويل، بل هو مؤاخذ، فلو قال مثلًا يدّعي عليه إنسان يقول إنك عندك لي ألف ريال أو مائة ريال أو أكثر أو أقل ثمن كذا أو ثمن كذا أو قرض ثم حلف وتأوّل في حلفه قال: والله ما عندي لك شيء، يعني شيء أكثر من هذا، يعني تأويل شيء أكثر من هذا، أو ما عندي شيء صفته كذا وصفته كذا، يتأول، ما ينفع التأويل، تسمى يمينه غموسًا؛ لأنه ظالم في هذا التأويل، ما ينفعه التأويل. لكن واحد جاءك يقول مثلًا: عندك فلان تخاف أنه يضره تخاف أنه يفعل به ما يؤذيه، تقول: والله ما هو عندي، تنوي ما هو عندك في المكان الذي أنت واقف فيه، وإن كان عندك في حجرة في الداخل، لكن ما هو عندك في المكان هذا أو في المجلس، وهو يحادثك في المجلس، وهو في الغرفة الأخرى، تقول: والله ما هو عندي، يعني في هذا المجلس، فهذا ينفع؛ لأنك لست بظالم، تدافع عن أخيك، أو لأسباب أخرى أو ما أشبه ذلك، يدّعي عليك أشياء باطلة فتحلف وتتأول تأويلًا نافعًا ليس بكذب؛ لدفع هذا المبطل.","link":"https://binbaz.org.sa/fatwas/24220/حكم-استعمال-المعاريض-للمصلحة-الخاصة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم استعمال المعاريض للمصلحة الخاصة.mp3","categories":["الآداب والأخلاق"]},{"id":4005,"question":"من قال: إذا سلم عليه قال: أهلًا ومرحبًا؟","title":"ما حكم رد السلام بقول: أهلا ومرحبا؟","answer":"لا، خالف السنة، لا بدّ يقول مثل ما بين النبي ﷺ: وعليك السلام ورحمة الله، فإذا زاد بعد هذا: أهلًا ومرحبًا، مثل ما فعل النبي مع أم هانئ؛ طيب.","link":"https://binbaz.org.sa/fatwas/24238/ما-حكم-رد-السلام-بقول-اهلا-ومرحبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رد السلام بقول أهلا ومرحبا.mp3","categories":["الآداب والأخلاق"]},{"id":4007,"question":"بعضهم إذا سُلّم عليه يقول: عليه وعلى رسول الله الصلاة والسلام؟","title":"ماذا يُقال لمن بلغه أن فلانًا يقرئه السّلام؟","answer":"الجواب: ما بلغنا هذا، ما نعرف له أصلًا، إنما يسلم على مَنْ سلّم عليه يقول: وعليك وعلى فلان السلام، ويكفي، أو على فلان السلام.","link":"https://binbaz.org.sa/fatwas/24241/ماذا-يقال-لمن-بلغه-ان-فلانا-يقرىه-السلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ماذا يقال إذا قيل فلان يقرئك السّلام.mp3","categories":["الآداب والأخلاق"]},{"id":4008,"question":"زيادة \"ومغفرته\" في الرد؟","title":"حكم زيادة \"ومغفرته\" في رد السلام","answer":"الجواب: ما نعرف فيها شيئًا يصح، إنما يُروى عن بعض السلف عن ابن عمر وعن غيره.","link":"https://binbaz.org.sa/fatwas/24242/حكم-زيادة-ومغفرته-في-رد-السلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم زيادة ومغفرته في الرد في السلام.mp3","categories":["الآداب والأخلاق"]},{"id":4010,"question":"التسليم ثلاثًا...؟","title":"الحكمة فيما جاء بالسنة من تكرار السلام ثلاثًا","answer":"الجواب: محمول على أنه إذا كانوا كثيرين، وإلا لم يفهموا، ولهذا في اللفظ الآخر: حتى تفهم عنه وأما إذا فهموا انتهى، ما عاد في حاجة للتكرار.  كان يسلم ثلاثًا لأسباب: إما لكثرة القوم وتباعدهم؛ حتى يفهموا كلامه، وإما لأسباب أخرى تقتضي ذلك.  وهكذا إعادة الكلمة حتى تُفهم عنه؛ لأنه مشرّع لا ينطق عن الهوى، ولهذا أراد أن يفهموا ما يقول وأن يحفظوه جيدًا؛ حتى لا ينقلوا عن النبي ﷺ إلا أشياء مثبوتة.","link":"https://binbaz.org.sa/fatwas/24245/الحكمة-فيما-جاء-بالسنة-من-تكرار-السلام-ثلاثا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تكرار السلام ثلاثًا.mp3","categories":["الآداب والأخلاق"]},{"id":4011,"question":"الآن يصعب على المؤمن الاستئذان ثلاثًا.. لابد من أكثر، خاصة في البيوت التي بَعُدت أبوابُها؟","title":"حكم الزيادة على السلام ثلاثًا في الاستئذان؟","answer":"الجواب: يفعل الشيء المبلّغ: مثل ضرب الجرس، مثل ضرب الحلقة، الشيء الذي يسمعهم مع السلام.\nس: لكن... يزيد عن ثلاث إذا عرف أنهم ما سمعوا؟\nالشيخ: أما السلام ثلاث هذه السنة، أما كونه يعمل شيئا آخر وزيادة مثل ضرب الحلقة ضرب الجرس مثل أشباه ذلك مما يشعرهم؛ لأنهم قد لا يسمعون الصوت.\nس: الجرس؟\nالشيخ: ما فيه شيء لأن هذا من باب التنبيه، مثل جرس الساعة والتلفون، ليس قصده قصد الجاهلية من تعليقه.\nس: ما يمنع الملائكة؟\nالشيخ: ما يمنع إن شاء الله.","link":"https://binbaz.org.sa/fatwas/24246/حكم-الزيادة-على-السلام-ثلاثا-في-الاستىذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الاستئذان مع السلام.mp3","categories":["الآداب والأخلاق"]},{"id":4019,"question":"تقبيل اليد؟","title":"حكم تقبيل اليد لمن له منزلة","answer":"الجواب: إذا فعل لحاجة بعض الأحيان لا بأس، لكن ما ينبغي أن يتخذ دائمًا، لكن إذا فعل بعض الأحيان فلا بأس، فقد فُعل مع النبي بعض الأحيان، ما يكون طريقة متبعة.\nس: إذا كان رئيس العمل....\nالشيخ: لا حرج إذا كان لأجل هذا لدفع الشر فلا بأس، النبي ﷺ سأله بعض اليهود عن مسائل فلما أخبرهم صدقوه وقبلوا يده ورجله، عليه الصلاة والسلام.\nس: بعض مشايخ الصوفية يستدلون بهذا الحديث فينحنون على أيديهم وعلى ركبهم؟\nالشيخ: على كل حال الصوفية عندهم ما هو أكبر، عندهم الشرك الأكبر، عندهم ما هو أكبر من هذا؛ لكن من كان فيه خير يُنصح ويُوجه إلى الخير، الكلام فيمن يخاف الله ويتقيه، أما مع المشركين والخرافيين فأمرهم آخر.","link":"https://binbaz.org.sa/fatwas/24255/حكم-تقبيل-اليد-لمن-له-منزلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تقبيل اليد.mp3","categories":["الآداب والأخلاق"]},{"id":4020,"question":"إذا قام الرجل فقيم معه عند مغادرته؟","title":"هل يُشرع القيام للرجل عند مغادرته؟","answer":"الجواب: ما في بأس، كان الصحابة إذا قام النبي ﷺ  قاموا معه حتى يتوارى عنهم.","link":"https://binbaz.org.sa/fatwas/24256/هل-يشرع-القيام-للرجل-عند-مغادرته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم إذا قام الرجل، فقيم معه عند مغادرته.mp3","categories":["الآداب والأخلاق"]},{"id":4021,"question":"اتخاذ كلما قدم والده قبّل رأسه وقام له؟","title":"حكم القيام للوالد وتقبيل رأسه","answer":"الجواب: الأمر في هذا واسع، في حديث فاطمة كلما دخل عليها قامت عليه، وكلما دخلت عليه قام إليها، هكذا روى جماعة من أهل العلم بإسناد صحيح، أبو داود وجماعة، وذكره الحافظ العلامة ابن مفلح في كتاب الآداب فيما ينبغي للولد مع أبيه، فلا حرج في هذا.","link":"https://binbaz.org.sa/fatwas/24257/حكم-القيام-للوالد-وتقبيل-راسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/القيام للوالد، وتقبيل رأسه.mp3","categories":["الآداب والأخلاق"]},{"id":4024,"question":"تقبيل الرِّجْل...؟","title":"حكم تقبيل الرِّجْل (القدم)","answer":"الجواب: إذا فعل بعض الأحيان لمصلحة شرعية، الأمر سهل، سلف الأمة خير منا.","link":"https://binbaz.org.sa/fatwas/24260/حكم-تقبيل-الرجل-القدم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تقبيل الرجل.mp3","categories":["الآداب والأخلاق"]},{"id":4025,"question":"\"كيف أصبحت\" من السنة؟","title":"هل قول \"كيف أصبحت\" من السُّنة؟","answer":"الجواب: هذا من عمل المسلمين، ولا فيه شيء عن النبي ﷺ، إنما سأل الصحابة عليًا: كيف حال النبي؟ كيف أصبح النبي؟ فقال: أصبح بحمد الله بارئًا. هذا مما يستعمله المسلمون، ومن الكلمات الطيبة، كان يفعلها الصحابة ويفعلها الأخيار.","link":"https://binbaz.org.sa/fatwas/24261/هل-قول-كيف-اصبحت-من-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل قول كيف أصبحت من السنة.mp3","categories":["الآداب والأخلاق"]},{"id":4026,"question":"بعض الناس إذا دخل المجلس وسلم يجلس ولا يصافح؟","title":"هل الأفضل لمن دخل مجلسًا أن يصافحهم؟","answer":"الجواب: هو مخير إن صافح فلا بأس، وإن سلم وجلس فلا بأس، الأمر واسع. من باب العناية؛ إن صافح من باب العناية فحسن، وإن كان يكلف الناس وإلا كذا ورأى أن هذا يكلف الناس وهم كثير، كونه يجلس قد يكون أريح للناس حتى لا يكلفهم، وإن صافح فلا ينكر؛ لأن الصحابة كانوا إذا تلاقوا تصافحوا.\nس: ما هو مرغب فيه عشان تَحُتّ الذنوب والخطايا؟\nالشيخ: عند اللقاء مستحب، كان الصحابة إذا تلاقوا وإذا لقوا النبي ﷺ تصافحوا، لكن المجلس فيه الجم الغفير، قد يتعبهم أو يتعب نفسه، أو يشغلهم عما هو أهم، يلاحظ المعنى، ينبغي للداخل يلاحظ، قد يكون عدم مصافحته لهم يشق عليهم يرونه جفاء فيه، قد يرى مصافحته تؤذيهم تشق عليهم، ينبغي للداخل أن يلاحظ الأمور، لا يكون عنده غفلة، ويكون عنده عدم فطنة، يلاحظ.","link":"https://binbaz.org.sa/fatwas/24262/هل-الافضل-لمن-دخل-مجلسا-ان-يصافحهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل في المصافحة.mp3","categories":["الآداب والأخلاق"]},{"id":4031,"question":"حديث النهي عن الاتكاء؟","title":"حكم الاتكاء عند الأكل","answer":"الجواب: ما فيه نهي، إنما هو يقول: لا آكل متكئًا، أخبر أنه لا يأكل متكئًا، فتركه أفضل.\nس: إن أكل متكئًا يأثم؟\nالشيخ: لا ما يأثم، لكن تركه أفضل؛ لأن الرسول قال: لا آكل متكئًا، ما قال: لا تأكلوا، قال: لا آكل.. يفيد أن هذا هو الأفضل، وأن السنة التأسي به في هذا عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/24267/حكم-الاتكاء-عند-الاكل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النهي عن الاتكاء عند الأكل.mp3","categories":["الآداب والأخلاق"]},{"id":4043,"question":"الكهرب والسخانات والدفايات التي للبرد، كيف؟","title":"هل تُطفأ السخانات والدفايات للأمر في الحديث","answer":"الجواب: الظاهر - والله أعلم - أنها غير داخلة في هذا؛ لأن هذه مقصودة لدفء المحل، ما هو مقصود النور، ثم هذه ما هي نار، هذه قوة خاصة داخلية تحصل بها الحاجة التي من أجلها وجدت وهي الدفء أو التبريد ولا يحصل بها خطر في الغالب، بخلاف الأنوار التي لا حاجة إليها؛ تُطفأ لأن الناس ينامون وما لهم حاجة في النور.","link":"https://binbaz.org.sa/fatwas/24279/هل-تطفا-السخانات-والدفايات-للامر-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تطفأ السخانات والدفايات التي للبرد.mp3","categories":["الآداب والأخلاق"]},{"id":4164,"question":"هل أكتم السرّ على أهل المعاصي؟","title":"هل يُشرع كتمُ سر أهل المعاصي؟","answer":"الجواب: المجاهر يُبين حاله حتى يردع، أما مَن كان سرًّا مثلما قال الرسولُ ﷺ: مَن ستر مسلمًا ستره الله في الدنيا والآخرة.","link":"https://binbaz.org.sa/fatwas/24418/هل-يشرع-كتم-سر-اهل-المعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يكتم السر عن أهل المعاصي.mp3","categories":["الآداب والأخلاق"]},{"id":4304,"question":"حكم تقبيل اليد؟","title":"ما حكم تقبيل اليد؟","answer":"الجواب: تركها أولى.\nس: ما فعل مع النبي ﷺ؟\nج: قد فعله بعض الناس مع النبي ﷺ وبعض الأئمة يشدد فيه، ولكن على كل حال تركه أولى. \nبعض أهل العلم يسميه \"السجدة الصغرى\" لكن تركها أولى، لا ينبغي التشديد ولا ينبغي التساهل، تركه أولى..","link":"https://binbaz.org.sa/fatwas/24578/ما-حكم-تقبيل-اليد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تقبيل اليد.mp3","categories":["الآداب والأخلاق"]},{"id":4305,"question":"هل يجوز للإنسان يقبل قدم والديه؟","title":"هل يجوز تقبيل قدم الوالدين؟","answer":"الجواب: لا، المصافحة تكفي، أو تقبيل ما بين عينيه رأسه.\nس: والذي يفعل هذا؟\nج: تركه أولى، تركه أولى.","link":"https://binbaz.org.sa/fatwas/24579/هل-يجوز-تقبيل-قدم-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تقبيل قدم الوالدين.mp3","categories":["الآداب والأخلاق"]},{"id":4362,"question":"حكم النوم على البطن؟","title":"ما حكم النوم على البطن؟","answer":"الجواب: ما ينبغي، جاءت الأحاديث لكن ما أعرف حال سندها، جاء النهي عن النوم على البطن.","link":"https://binbaz.org.sa/fatwas/24639/ما-حكم-النوم-على-البطن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم النوم على البطن.mp3","categories":["الآداب والأخلاق"]},{"id":4810,"question":"وردت بعض الروايات: من عطس يقول: الحمد لله، ومرة يقول: الحمد لله رب العالمين؟","title":"ما صيغة الحمد عند العطاس؟","answer":"الحمد لله رب العالمين أو الحمد لله على كل حال، أو الحمد لله فقط، أو الحمد لله حمدًا كثيرًا؛ كله طيب.\nس: كلها ثابتة؟\nج: لا، ولكن جنس الحمد مشروع.","link":"https://binbaz.org.sa/fatwas/25207/ما-صيغة-الحمد-عند-العطاس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما الصحيح عند العطاس قول الحمد لله، أو الحمد لله رب العالمين.mp3","categories":["الآداب والأخلاق","الأدعية والأذكار"]},{"id":4818,"question":"صحة حديث أنس: طوبى لمن شغله عيبه عن عيوب الناس؟","title":"هل صح حديث «مَن شغله عيبه عن عيوب الناس»؟","answer":"لا بأس به، حسّنه الحافظ رحمه الله.\nس: ذكر العيب على سبيل التحذير كيف يكون؟\nج: يعني إذا نظر في عيوب الناس يحذرها. يتأملها ليحذرها، عيوب الناس في الغضب، عيوب الناس في العجلة، عيوب الناس في الغيبة، يتأمل ما يترتب عليها من الشر؛ حتى يحذرها.","link":"https://binbaz.org.sa/fatwas/25222/هل-صح-حديث-من-شغله-عيبه-عن-عيوب-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث طوبى لمن شغله عيبه عن عيوب الناس.mp3","categories":["الحكم على الأحاديث","الآداب والأخلاق"]},{"id":4972,"question":"الأكل بالمِلْعَقة من غير حاجة؟","title":"حكم استعمال الملعقة في تناول الطعام","answer":"الجواب: ما أعلم فيه بأسًا، لكن باليد أفضل.","link":"https://binbaz.org.sa/fatwas/27871/حكم-استعمال-الملعقة-في-تناول-الطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم استعمال الملعقة في تناول الطعام.mp3","categories":["الأطعمة والأشربة","الآداب والأخلاق"]},{"id":4990,"question":"عندنا في الجامعة يكثر الرافضة.. ابتداؤهم بالسلام؟","title":"حكم ابتداء الرافضة والمبتدعة بالسلام","answer":"الجواب: إذا كنت تعلمهم أنهم رافضة يُظْهِرون بدعتهم لا تبدأهم ولا ترد عليهم؛ يُهْجَرُون، أما إذا ما أظهروها وستروها؛ سَلِّم عليهم.\nس: لا يصلون في المسجد؟\nالشيخ: لا يصلون مع الجماعة، هذا مِن البِدَع.\nس: يعني لا يرد عليهم؟\nالشيخ: ولا يبدؤون؛ حتى يصلوا مع المسلمين، حتى يَنصروا السنة ويبتعدوا عن البدعة.\nس: وغلاة الصوفية؟\nالشيخ: الصوفية إذا أظهروا بدعتهم وإلا سَلِّم عليهم، إذا أظهروا بدعتهم المُكَفِّرة أو مُوجِبًا للهجر فلا تُسَلِّم ، وإذا ما أظهروا شيئًا مع المسلمين في صلاتهم وفي أعمالهم، يُسَلَّم عليهم، ليس لك إلا الظاهر.","link":"https://binbaz.org.sa/fatwas/28502/حكم-ابتداء-الرافضة-والمبتدعة بالسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم ابتداء الرافضة والمبتدعة بالسلام.mp3","categories":["الآداب والأخلاق"]},{"id":4996,"question":"بالنسبة للبداية: يُنتظر أن يبدأ كبيرُ القوم، والنهاية؟","title":"حكم مراعاة كبير القوم في بدء الطعام وآخره","answer":"الجواب: كلّ مَن انتهى خلاص، لا يلزم أن ينتظر، لكن إذا كانت عادتُهم ألا يقوموا إلا لأجله لا يقوم؛ لا يُكَدّر عليهم.","link":"https://binbaz.org.sa/fatwas/28700/حكم-مراعاة-كبير-القوم-في-بدء-الطعام-واخره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم مراعاة كبير القوم في بدء الطعام وآخره.mp3","categories":["الآداب والأخلاق"]},{"id":4997,"question":"التَّسمية مع كلِّ لقمةٍ؟","title":"ما حكم التسمية والحمد مع كل لقمة؟","answer":"الجواب: لا، التَّسمية في الابتداء تكفي.\nس: والحمد؟\nج: والحمد عند آخر شيء.","link":"https://binbaz.org.sa/fatwas/28701/ما-حكم-التسمية-والحمد-مع-كل-لقمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حكم التسمية والحمد مع كل لقمة؟.mp3","categories":["الآداب والأخلاق"]},{"id":4998,"question":"إذا استخدم الإنسانُ وهو يأكل يدَه اليُسرى مع اليمنى في تقطيع اللحم؟","title":"حكم استخدام اليسرى مع اليمنى في الطعام","answer":"الجواب: لا بأس، إذا استخدم اليُسرى يستعين بها فلا بأس، لكن لا يأكل إلا بيمينه، مثل النبي ﷺ كان يستعين باليُسرى في تقطيع اللحم ونحوه.","link":"https://binbaz.org.sa/fatwas/28702/حكم-استخدام-اليسرى-مع-اليمنى-في-الطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم استخدام اليسرى مع اليمنى في الطعام.mp3","categories":["الآداب والأخلاق"]},{"id":4999,"question":"يلعقها إذا كان فيها طعامٌ؟","title":"ما المشروع في لعق اليدين على الطعام؟","answer":"الجواب: إذا كان فيها شيءٌ يلعقها.","link":"https://binbaz.org.sa/fatwas/28703/ما-المشروع-في-لعق-اليدين-على-الطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما المشروع في لعق اليدين على الطعام؟.mp3","categories":["الآداب والأخلاق"]},{"id":5000,"question":"إذا كان القوم مدعوين عند شخصٍ، ولم يجلس معهم، لا يأكلون حتى يقول لهم: سمّوا، كما يُقال: سمّوا، الله يُحييكم؟","title":"هل يلزم إذن صاحب الدعوة لبدء الطعام؟","answer":"الجواب: .....، هو ما قُدِّم إلا ليأكلوا، ما يحتاج أحد، يعني: يعمل بالظاهر.","link":"https://binbaz.org.sa/fatwas/28704/هل-يلزم-اذن-صاحب-الدعوة-لبدء-الطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يلزم إذن صاحب الدعوة لبدء الطعام؟.mp3","categories":["الآداب والأخلاق"]},{"id":5020,"question":"رد السلام في دورة المياه؟","title":"حكم رد السلام في دورة المياه","answer":"الجواب: مكروه؛ يُكْرَه، مكروه عند أهل العلم.","link":"https://binbaz.org.sa/fatwas/28858/حكم-رد-السلام-في-دورة-المياه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم رد السلام في دورة المياه.mp3","categories":["الآداب والأخلاق"]},{"id":5053,"question":"إذا كان أقاربه مثلًا عندهم دشّ فهل له أن يزورهم ثم ينصرف؟","title":"حكم زيارة الأقارب الذين عندهم منكرات","answer":"الجواب: يزورهم وينصحهم عن الدش وغير الدش؛ عن المنكرات، وإذا أبوا وأصرُّوا على الباطل وأعلنوه؛ استحقّوا الهجر.\nس: من غير هجرٍ يزورهم قبلُ؟\nج: لا، ينصحهم.","link":"https://binbaz.org.sa/fatwas/29295/حكم-زيارة-الاقارب-الذين-عندهم-منكرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم زيارة الأقارب الذين عندهم منكرات.mp3","categories":["الآداب والأخلاق"]},{"id":5187,"question":"في حقِّ مَن تجوز الغيبة؟ وهل يصحّ حديث: لا غيبةَ لفاسِقٍ؟","title":"ما صحة أثر: لا غِيبةَ لفاسِقٍ؟ ومتى تجوز الغِيبة؟","answer":"الجواب: الحديث ليس بصحيحٍ فيما أعلم، لكن ذكر العلماءُ ستة أشياء تجوز فيها الغيبة: إذا أظهر الفسق، وهكذا في الاستفتاء، وهكذا في التَّظلم، وهكذا في جرح الشهود، وجرح الرواة، كل هذه أمور لا بأس فيها، وهكذا في المُناصحة؛ أن يستنصحك ويستشيرك، فهذه الأمور الستة ليس فيها غيبة: عند جرح الشهود، عند جرح الرواة، عند المُستفتي الذي يستفتيك عن كذا وكذا: تستفتيه امرأةٌ أن تأخذ من مال زوجها لأنه بخيلٌ ما يُعطيها حقوقها، يستفتيك في إنسانٍ ظلمه: هل يُخاصمه؟ هل يأخذ من ماله مقابل حقِّه؟ وما أشبه ذلك. فالإنسان إذا أظهر الفسق لا غيبةَ له: إذا أظهر حلق اللحية، وقال إنسانٌ: هذا فلان محلوق اللحية، ما هي بغيبة، وإذا كان يُسبل ثيابه وقال بعضُ الناس فيه: إنه مُسْبِلٌ، ما هي بغيبةٍ؛ لأنه أظهرها، هو الذي أظهر المعصية، هو الذي فضح نفسه، فلا يُسمَّى: مُغتابًا -نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/30129/ما-صحة-اثر-لا-غيبة-لفاسق-ومتى-تجوز-الغيبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 156.mp3","categories":["الحكم على الأحاديث","الآداب والأخلاق"]},{"id":5239,"question":"فضيلة الشيخ، والدي رجلٌ متوسط في العمر، هداه الله، محافظٌ على الصَّلوات الخمس في المسجد مع الجماعة، ويأمرنا بالأمر بالمعروف، والنَّهي عن المنكر، ابتلاه الله بالخمر -والعياذ بالله- فهو يشربها بالأسبوع مرةً، ولا نراه عندما يشربها، ولا ندري أين يشربها؟ وهو يُحذرنا منها.أرجو من سماحتكم توجيه النَّصيحة له، وبيان حكمه، فهو معنا في هذا المسجد، والله يحفظكم.","title":"ما كيفية نصح الوالد الذي يشرب الخمر؟","answer":"الجواب: الخمر من أقبح الكبائر، من أقبح الموبقات -نعوذ بالله- فالواجب على كل مسلم أن يحذرها، وأن يبتعد عنها، وألا يشرب شيئًا منها مطلقًا، لا في الأسبوع، ولا في الشهر، ولا في السنة، ولا في جميع الأوقات، قال الله جلَّ وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالْأَنْصَابُ وَالْأَزْلَامُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ  ۝  إِنَّمَا يُرِيدُ الشَّيْطَانُ أَنْ يُوقِعَ بَيْنَكُمُ الْعَدَاوَةَ وَالْبَغْضَاءَ فِي الْخَمْرِ وَالْمَيْسِرِ وَيَصُدَّكُمْ عَنْ ذِكْرِ اللَّهِ وَعَنِ الصَّلَاةِ فَهَلْ أَنْتُمْ مُنْتَهُونَ [المائدة:90- 91]، قال عمر عندما سمع الآية: انتهينا، انتهينا. فالمقصود أنَّها من أقبح الكبائر، قال عليه الصلاة والسلام: إنَّ على الله عهدًا لمَن مات وهو يشرب الخمرَ أن يسقيه من طينة الخبال، قيل: يا رسول الله، ما طينة الخبال؟ قال: عُصارة أهل النار أو قال: عرق أهل النار. وثبت عنه ﷺ أنه لعن الخمر، وشاربها، وساقيها، وعاصرها، ومُعتصرها، وحاملها، والمحمولة إليه، وبائعها، ومُشتريها، وآكل ثمنها، عشرة -نسأل الله العافية. فالواجب الحذر، وعلى مَن يتعاطاها أن يتَّقي الله، وأن يُبادر بالتوبة النَّصوح، والله يتوب على مَن تاب، ويقول عليه الصلاة والسلام: لا يزني الزاني حين يزني وهو مؤمن، ولا يشرب الخمر حين يشربها وهو مؤمن، قال: وإن صلَّى وصام وزعم أنه مسلم، هذا وعيدٌ عظيمٌ، لو كان عنده إيمانٌ قوي لردعه، فهذا يدل على أنَّ إيمانه ضعيفٌ، ولهذا أقدم على هذه الفاحشة وهذه الجريمة. وأنتم أيها الأبناء عليكم نصيحته دائمًا، وألا تيأسوا، بالكلام الطيب، والأسلوب الحسن، ولو كان أباكم، عليكم أن تنصحوه دائمًا، مع الحكمة والأسلوب الحسن، وأن تُخوِّفوه من الله جلَّ وعلا، وأن تجتهدوا في أسباب سلامته من هذا البلاء، وأنتم على خيرٍ، لكن من دون أذًى، ومن دون عنفٍ.","link":"https://binbaz.org.sa/fatwas/30613/ما-كيفية-نصح-الوالد-الذي-يشرب-الخمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 371.mp3","categories":["الأطعمة والأشربة","الآداب والأخلاق","نصائح وتوجيهات"]},{"id":5468,"question":"الانحناء في التحية؟","title":"ما حكم الانحناء في التحية؟","answer":"الجواب: ما يجوز، لا، التحية لا، إلا إذا كان جالسًا، وطمّن يسلم عليه أو يقبّله، أما ينحني عند السلام لا، يسلم وهو مستقيم، يصافح أو يعانق، جاء في حديث فيه ضعف أن رجلا قال: يا رسول الله الرجل يلقى أخاه أينحني له؟ قال: لا، قال: يلتزمه ويقبله؟ قال: لا، قال: يأخذ بيده ويصافحه؟ قال: نعم. فالمصافحة أكمل، وإذا عانقه كما جاء في الحديث الصحيح؛ فلا بأس عند قدوم من السفر، قال أنس : «كان أصحاب النبي ﷺ إذا قدموا من سفر تعانقوا، وإذا تلاقوا في الطريق تصافحوا»، وكانت فاطمة إذا دخلت على أبيها عليه الصلاة والسلام قام إليها فقبلها وأخذ بيدها وأجلسها في مجلسه، وكان إذا دخل عليها هي قامت إليه وقبلته وأخذت بيده عليه الصلاة والسلام، المقصود أنه لا بأس بالتقبيل على الرأس، أو تقبيل بين العينين عند القدوم من السفر، عند المعانقة، أو مع الوالدة أو مع الأب، لا بأس، التقبيل، والمعانقة أفضل بالعنق، يقول: هذا بعنقه وهذا بعنقه، معانقة، يسمى معانقة، وكان أبو بكر الصديق قد يقبّل ابنته عائشة من خدّها، لما جاء وهي مريضة قبلها من خدّها .[1]","link":"https://binbaz.org.sa/fatwas/31339/ما-حكم-الانحناء-في-التحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/reyath_alsalhin 004.mp3","categories":["الآداب والأخلاق"]},{"id":5472,"question":"السلام على النساء؟","title":"ما حكم سلام الرجال على النساء؟","answer":"الجواب: كذلك السلام على النساء: السلام عليكن، لا بأس، ورد السلام كذلك، النبي كان يُسلم عليهن، ويرد السلام عليهن، السلام عليهن ما نعلم فيه شيئًا.[1]","link":"https://binbaz.org.sa/fatwas/31353/ما-حكم-سلام-الرجال-على-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/reyath_alsalhin 009.mp3","categories":["الآداب والأخلاق"]},{"id":5681,"question":"يوجد بعض من الشباب الواعي يتعصب لأشياء  قد تكون صدمة لدى الشباب الضعيف الذي في أمس الحاجة إلى موجه، ومن هذه الأشياء أنهم يقصرون ثوبهم تقصيرًا قد يصل إلى التشدد؟","title":"حكم الإسبال بين الغلو والتفريط","answer":"الجواب:\nهذه مسائل طفيفة، ومسائل خفيفة، المهم أن يحذروا من الإسبال، فإذا كان الثوب من نصف الساق إلى الكعب فهذا كله جائز، أعلاه نصف الساق كما جاء في الحديث إزرة المؤمن، والنهاية إلى الكعب لا ينزل عن الكعب.  وما دام الثوب من نصف الساق إلى الكعب فلا إنكار في ذلك، ولا ينبغي الإنكار في ذلك؛ بل هذا محل جواز من النصف إلى الكعب، ولا يجوز أن ينزل عن الكعبين كما قال النبي ﷺ: ما أسفل الكعبين من الإزار فهو في النار وتوعد المسبلين قال: لا يكلمهم الله ولا يزكيهم ولهم عذاب أليم. فلا يجوز الإسبال تحت الكعب، ولا بأس أن يكون فوق الكعبين من نصف الساق هذا محله، ولا ينبغي التشديد في هذا، ولا التزمت في هذا؛ بل ينبغي في هذا التسامح، وعدم الإنكار على من رفع إلى نصف الساق، وعدم الإنكار على من نزله إلى الكعب لا هذا ولا هذا. السؤال: أحسن الله إليك يا شيخ، بالنسبة للحديث أمر الرسول ﷺ الصحابي بإعادة الوضوء؟ الجواب: هذا في الإسبال جاء فيه حديث فيه ضعف، وجاء في حديث آخر ما يدل على صحة المعنى، ولكن المقصود من ذلك التحذير من الإسبال، وليس معناه أنك تعيد الصلاة، النبي أمرهم بإعادة الوضوء من باب التشديد، والتحذير، ولم يأمرهم بقضاء الصلاة، وإعادتها -عليه الصلاة والسلام- وقال أهل العلم: إن المراد من هذا التحذير من الإسبال، وأنه شيء قبيح ينبغي فيه الحذر من تعاطيه، ولاسيما في الصلاة. السؤال: إذا كان هناك إنسان خياط، ثم يأتيه الرجل يشترط عليه أن يجعله تحت الكعبين؟ الجواب: يتعلم الخياط، ينكر على الخياط، لا يزيدهم تحت الكعبين إلا إذا كان القصد أنه يرفعه تحت الكعبين، ثم يرفعه إذا غسله؛ لأنه بعض الخرق إذا غسل يشمر، ويرتفع، فإذا كان فيه إسبال أطلقوه حتى يكون مناسبًا بعد ذلك، إذا كان القصد هكذا فلا بأس،.. ثم يرفع، فإذا احتيج إلى إطلاقه أطلقه؛ بشرط أن لا ينزل عن الكعب.","link":"https://binbaz.org.sa/fatwas/973/حكم-الاسبال-بين-الغلو-والتفريط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_02.mp3","categories":["الآداب والأخلاق","اللباس والزينة"]},{"id":5685,"question":"سؤال آخر: إذا لبست العقال حيث بعض الإخوان قال لي: لا تلبسه فهو حرام؟","title":"حكم لبس العقال","answer":"الجواب:\nليس بشيء العقال ليس بشيء، لو لبس عقالًا، أو  خيطًا، أو عمامة لا بأس، كله لا بأس. أمور اللباس هذه ما فيها بأس إلا على وجه يكون فيه مشابهًا للكفار، فالشيء الذي فيه مشابهة للكفار لا يفعله ما دام ملابسه يلبسها المسلمون فلا بأس.","link":"https://binbaz.org.sa/fatwas/988/حكم-لبس-العقال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_17.mp3","categories":["الآداب والأخلاق","اللباس والزينة"]},{"id":5690,"question":"الشغار معروف أنه حرام، ولكن فيه اثنين وقعوا فيه، وجاء لهم عيال الآن بعد خمس سنوات، أو سبع سنوات، فماذا عليهم؟","title":"كيفية التخلص من زواج الشغار","answer":"الجواب:  يجددوا النكاح، ولا عليهم شيء، يجددوا النكاح مع التوبة والاستغفار، إذا كانت الزوجة ترغب في زوجها يجددوا النكاح بدون شرط الأخرى، يعقد عقدًا جديدًا بدون شرط المرأة الأخرى، كل واحد مع التوبة والاستغفار، والتي ما تبيه يطلقها طلقة واحدة. السؤال: لازم من التجديد بارك الله فيك؟ الجواب: كل واحد يجدد النكاح بدون الشرط القبيح، بدون شرط المرأة الثانية.","link":"https://binbaz.org.sa/fatwas/995/كيفية-التخلص-من-زواج-الشغار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_24.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":5694,"question":"الشغار معروف أنه حرام، ولكن فيه اثنين وقعوا فيه، وجاء لهم عيال الآن بعد خمس سنوات، أو سبع سنوات، فماذا عليهم؟","title":"كيفية التخلص من زواج الشغار","answer":"الجواب:  يجددوا النكاح، ولا عليهم شيء، يجددوا النكاح مع التوبة والاستغفار، إذا كانت الزوجة ترغب في زوجها يجددوا النكاح بدون شرط الأخرى، يعقد عقدًا جديدًا بدون شرط المرأة الأخرى، كل واحد مع التوبة والاستغفار، والتي ما تبيه يطلقها طلقة واحدة. السؤال: لازم من التجديد بارك الله فيك؟ الجواب: كل واحد يجدد النكاح بدون الشرط القبيح، بدون شرط المرأة الثانية.","link":"https://binbaz.org.sa/fatwas/995/كيفية-التخلص-من-زواج-الشغار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_24.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":5722,"question":"منذ زمن دعت وسائل الإعلام بأشكالها خارج البلاد الإسلامية إلى ظهور المرأة في ميدان الرجل للتقدم، ثم تلتها صحف بلدنا بالدعوة، فهل بقاء المرأة في حدودها الحالية يعتبر تخلفًا للأمة، وهل يدوم سكوت العلماء حتى تشتد نزعة المرأة إلى ما لا يحمد عقباه؟","title":"خطورة مخالطة المرأة للرجال","answer":"الجواب: وهذا من الداء الذي ينشره الأعداء، ويستغل الأعداء جهل الجاهلين، وجهل الكثير من الشباب، فينشرون بينهم هذه الدعوة إلى ظهور المرأة، وبروزها في ميدان العلم بين الرجال، وفي المدارس، وفي كل مكان مع الصبي جنبًا إلى جنب حتى تكثر الفاحشة، ويعم الفساد، وتنحدر الأخلاق إلى أخلاق سافلة، أخلاق بهيمية، هذه مقاصد أعداء الله. فالواجب هو بقاء المرأة على حالها الإسلامية، أن تكون في بيتها معلمة لأولادها، وأطفالها مصلحة لبيتها، معتنية بزوجها، وإذا كانت عندها فضل تنفع المسلمين في تعليم البنات في مدارس البنات، في الطب، والتمريض للنساء فيما يتعلق بالنساء، هذه حدودها، وبهذا يكون لها النجاة، ويكون لشعبها، ومجتمعها الخير والفوز والصلاح. أما إذا خالطت الشباب في مدارسهم، وفي مجتمعاتهم، وصرن كاتبات في المكاتب ... وتعمل جنبًا إلى جنب مع الرجل، صار ذلك الفساد، وصار الخراب، والدمار، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/1026/خطورة-مخالطة-المراة-للرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_48.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":5735,"question":"خروجها مع السائق إلى المدرسة؟","title":"حكم خروج المرأة مع السائق","answer":"الجواب:  هذا خطر، نبهنا عليه غير مرة، مع السائق وغير السائق، مع أجنبي كونها تكون معه في غرفة، أو في حجرة يخلو بها ما يجوز، أو في السيارة مع السائق ما يجوز، بل لا بدّ أن يكون معها غيرها، أو السائق معه محرم، أو يكون معها امرأة، أو رجل آخر، حتى لا تصير خلوة، النبي ﷺ قال: لا يخلون رجل بامرأة فإن الشيطان ثالثهما نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/1055/حكم-خروج-المراة-مع-الساىق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_72.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":5756,"question":"ذهبت للحج مع أبي، ووجدت نقودًا مقدارها ألفان ومائتان وخمسون ريالًا سعوديًا عند الجمرة الوسطى، وأبي تبرع بها لمسجده فما حكم ذلك؟","title":"حكم لُقَطة مكة","answer":"الجواب: الواجب على من وجد لقطة في الحرم لا يتبرع بها للمسجد، ولا لغير المسجد؛ بل يعرفها دائمًا في الحرم، من له الدراهم؟ من له الذهب؟ من له كذا؟ دائمًا. النبي -عليه الصلاة والسلام- قال:  ولا تحل ساقطتها إلا لمعرف فلا تصرف في كذا، ولا في  كذا، بل ينادى عليها حتى يأتي أهلها، وإذا كان لا يستطيع ... في مكة، والهيئة معدة لهذا الشيء، وتبرأ ذمته حتى يأتي أهلها يسألون عنها. أما أنها تصرف في فقير أو في مزرعة أو في مسجد أو كذا لا ما يجوز، الرسول -عليه الصلاة والسلام- قال: ولا تحل ساقطتها إلا لمعرف وفي رواية : إلا لمنشد ينادي عليها: من له الذهب من له إلى آخره، وهكذا ... المدينة. السؤال: ولو تركها يا شيخ؟ الجواب: إن تركها فلا بأس .......","link":"https://binbaz.org.sa/fatwas/1067/حكم-لقطة-مكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_81.mp3","categories":["اللقطة واللقيط","الآداب والأخلاق"]},{"id":5774,"question":"ذهبت للحج مع أبي، ووجدت نقودًا مقدارها ألفان ومائتان وخمسون ريالًا سعوديًا عند الجمرة الوسطى، وأبي تبرع بها لمسجده فما حكم ذلك؟","title":"حكم لُقَطة مكة","answer":"الجواب: الواجب على من وجد لقطة في الحرم لا يتبرع بها للمسجد، ولا لغير المسجد؛ بل يعرفها دائمًا في الحرم، من له الدراهم؟ من له الذهب؟ من له كذا؟ دائمًا. النبي -عليه الصلاة والسلام- قال:  ولا تحل ساقطتها إلا لمعرف فلا تصرف في كذا، ولا في  كذا، بل ينادى عليها حتى يأتي أهلها، وإذا كان لا يستطيع ... في مكة، والهيئة معدة لهذا الشيء، وتبرأ ذمته حتى يأتي أهلها يسألون عنها. أما أنها تصرف في فقير أو في مزرعة أو في مسجد أو كذا لا ما يجوز، الرسول -عليه الصلاة والسلام- قال: ولا تحل ساقطتها إلا لمعرف وفي رواية : إلا لمنشد ينادي عليها: من له الذهب من له إلى آخره، وهكذا ... المدينة. السؤال: ولو تركها يا شيخ؟ الجواب: إن تركها فلا بأس .......","link":"https://binbaz.org.sa/fatwas/1067/حكم-لقطة-مكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_81.mp3","categories":["اللقطة واللقيط","الآداب والأخلاق"]},{"id":5789,"question":"ما حكم الإسلام في عمل المرأة في التعليم، والطب، والتمريض؟ وكيف يمكن التوفيق بين ذلك، وبين قول الله : وَقَرْنَ فِي بُيُوتِكُنَّ [الأحزاب:33]؟","title":"حكم عمل المرأة في التعليم والطب وغير ذلك","answer":"الجواب: المرأة لها أعمال، والرجل له أعمال، يشتركان في بعض، وينفرد كل واحد عن بعض، فالمرأة تعمل الأعمال المناسبة لها: كتدريس النساء، وإدارة مدارس النساء، وتمريض النساء، وتطبيب النساء، ونحو ذلك من الأعمال التي تكون في ميدان النساء، وما تدعو الحاجة إلى أن تعمل في حاجة الرجل، كأن تمرضه إذا دعت الحاجة إلى ذلك مع الحجاب، ومع العفة، والبعد عن الخلوة، ونحو ذلك، كما جرى للنساء مع النبي ﷺ في بعض الغزوات، كنا يسقين المرضى الماء، ويداوين الجرحى، ويكن مع المسلمين في المعسكرات للمصلحة مع الحجاب، ومع الستر، ومع العفة، ومع النزاهة، والبعد عن أنواع الريب.  فإذا كانت المرأة في هذا المقام، مقام الحجاب، والصيانة، والعفة، واحتيج إليها في طب الرجل عند عدم من يطبه من الرجال فلا بأس أن تسقيه الدواء، ولا بأس أن تعمل الدواء عند الحاجة، وإلا فميدانها هو ميدان النساء في الطب، والتعليم، والتمريض، وغير ذلك. والرجل ميدانه ميدان الرجال في الطب، والتعليم وغير ذلك، هذا هو المشروع، وهو الطريق المعروف، وهو الطريق المسلوك، وإذا دعت الحاجة إلى أن يقوم هذا بهذا أن يطب الرجل المرأة، وتطب المرأة الرجل عند الحاجة؛ فلا بأس، مع مراعاة الحجاب، ومراعاة عدم الخلوة، كما هو معلوم، كما جاءت به السنة عن رسول الله، عليه الصلاة والسلام.  ولا يخالف هذا قوله تعالى: وَقَرْنَ فِي بُيُوتِكُنَّ [الأحزاب: 33] فالآية لها معنيان: أحدهما: أن المعنى الزمن بيوتكن، ولا تخرجن إلا لحاجة، لمصلحة، وهذا هو الواقع فإن المرأة أفضل لها بيتها إلا من حاجة، إن خرجت لمصلحة تصلي في الجماعة مع حجاب وستر، كن يخرجن في عهد النبي ﷺ كن يخرجن إلى الصلاة مع النبي ﷺ، كذلك كن يخرجن لعيادة المريض في قضاء حاجة من الحاجات؛ لشراء حاجة من السوق تحتاج إليها، وما أشبه ذلك. فإذا كان الخروج لحاجة، ومصلحة فلا بأس، إنما المطلوب هو مكثها في البيت عند عدم الحاجة للخروج. المعنى الثاني: أنها من الوقار، والحشمة، وأن المعنى يعني الْزمن الحشمة، والزمن الوقار، ولا تكن متبذلات، ولا متساهلات، والمعنى الأول هو المشهور، وهو بمعنى اللبث، بمعنى الوقار في البيت، فلا منافاة بين هذا وهذا.","link":"https://binbaz.org.sa/fatwas/1111/حكم-عمل-المراة-في-التعليم-والطب-وغير-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_117.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":5848,"question":"رجل ماشي في الشارع، وتحصل على صنجل وأخذه، وهو لا يعلم ما هو، وبعد أن وصل عنده أهله في بلاد بعيدة أعطاه أهله، وتبين أنه ذهب، وجلس محتارًا كيف يصنع؟ ولم يقدر الآن، وله مدة ست، أو سبع سنوات، أو أكثر، فهل يجزئ عليه أن يدعو لصاحبه، ويستغفر له مع أنه لا يعلم من هو أفتوني؟","title":"حكم اللقطة","answer":"الجواب:  هذا الذي وجد الصنجل أظنه صنجل الساعة، إذا كان ذهبًا له أهمية؛ فهذا الواجب تعريفه، يعرفه سنة كاملة لعله يعرف، والآن أخره كثيرًا؛ فالواجب أن يعرفه إذا كان له قيمة، يعرفه في البلد التي وجدها فيها، من له صنجل الساعة الذي ضاع في كذا وكذا، سنة كذا وكذا؟ إن وجد أحدًا يعرفه بصفاته الخاصة؛ أعطاه إياه، وإن لم يوجد من يعرفه؛ تصدق به؛ لأنه قصر في تعريفه، ولم يعرفه في وقته، تصدق به على بعض الفقراء. أما إن كان الصنجل ما يسوى شيئًا، يسوى خمسين ريالًا، أو أربعين ريالًا، فهذا أمره سهل إن أكله؛ فلا بأس، وإن تصدق به؛ فلا بأس؛ لأنه ما يتحمل التعريف، لو أعطى واحدًا يعرفه أكل أجرته. فالحاصل: أن الشيء القليل يعفى عنه، عشرة ريالات، أو عشرين ريالًا، فهذه لا تتبعها النفوس اليوم، النفوس في أوساط؛ لأن المال كثر بين الناس، فالشيء القليل لا يتحمل التعريف، لكن إذا كان شيئًا له أهمية، يعرف سنة كاملة؛ فإن عرف وإلا فهو للذي وجده، كما قاله النبي -عليه الصلاة والسلام- يعرف في مجامع الناس، في الشهر مرتين، ثلاث، أربع عند اجتماع الناس، وعند خروجهم من الجمعة، وموضع السوق، إن كتب في الجريدة، أو أذيع في التلفاز، أو في الإذاعة؛ فهذا طيب أيضًا إذا تيسر ذلك. السؤال: سؤال آخر: أحد أصحاب السيارات وجد بطانية في سيارته، ولا يعرف صاحبها، ودارت سنة؟ الجواب: مثل هذا البطانية في السيارة مثل اللقطة، هذه من الركاب الذين ضيعوها، البطانية إن كان لها قيمة إن كان لها أهمية؛ تعرف سنة، إذا كانت تسوى شيئضا كثيرًا 200 ريال 300 ريال لها  أهمية أو 100 ريال على الأقل؛ لا بأس يعرفها سنة، فإن عرفت وإلا فهي له، من له البطانية التي نسيها في بعض السيارات؟ في البلد التي هو فيها، أو ما يقاربها في مجامع الناس سنة كاملة، فإن عرفت، وإلا فهي له، وإن كانت حقيرة ما تساوي شيئًا؛ فأمرها سهل إن استعملها؛ فلا بأس، وإن تصدق بها؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/1182/حكم-اللقطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_178.mp3","categories":["اللقطة واللقيط","الآداب والأخلاق"]},{"id":5852,"question":"هل المني طاهر، أم نجس؟ وهل يكفي فركه إن كان يابسًا، والغسل إذا كان رطبًا؟","title":"هل المني طاهر أم نجس؟","answer":"الجواب:  المني على الصحيح طاهر، وهو أصل الإنسان، والنبي ﷺ قالت عائشة: ربما غسله، وربما فركه، قالت: كنت أفركه من ثوبه، كنت أحكه يابسًا من ثوبه؛ فدل ذلك على أنه طاهر، إذ لو كان نجسًا؛ لغسل، لما اكتفي به بالحك، والتنظيف بإزالته بدون ماء، دل على طهارته؛ ولأنه أصل الإنسان؛ فالإنسان طاهر، وأصله طاهر، أصله التراب، والتراب طاهر، ثم المني بعد ذلك فهو طاهر، والإنسان طاهر.","link":"https://binbaz.org.sa/fatwas/1183/هل-المني-طاهر-ام-نجس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_179.mp3","categories":["الآداب والأخلاق","النجاسات وإزالتها"]},{"id":5857,"question":"هل المني طاهر، أم نجس؟ وهل يكفي فركه إن كان يابسًا، والغسل إذا كان رطبًا؟","title":"هل المني طاهر أم نجس؟","answer":"الجواب:  المني على الصحيح طاهر، وهو أصل الإنسان، والنبي ﷺ قالت عائشة: ربما غسله، وربما فركه، قالت: كنت أفركه من ثوبه، كنت أحكه يابسًا من ثوبه؛ فدل ذلك على أنه طاهر، إذ لو كان نجسًا؛ لغسل، لما اكتفي به بالحك، والتنظيف بإزالته بدون ماء، دل على طهارته؛ ولأنه أصل الإنسان؛ فالإنسان طاهر، وأصله طاهر، أصله التراب، والتراب طاهر، ثم المني بعد ذلك فهو طاهر، والإنسان طاهر.","link":"https://binbaz.org.sa/fatwas/1183/هل-المني-طاهر-ام-نجس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_179.mp3","categories":["الآداب والأخلاق","النجاسات وإزالتها"]},{"id":5919,"question":"هل يطلق الرجل امرأته لطلب والديه، أو أحدهما، مع أن الوفاق بين الزوجين سائد؟","title":"حكم طلاق الزوجة مراعاة لطلب والد الزوج","answer":"الجواب: تقدم هذا المعنى، وأن الواجب أن يحل المشكل بالكلام الطيب مع والديه، ومعها، فيحثها على إحسان السيرة معهما، والتلطف لهما، وكذلك يتكلم مع والديه بأنها امرأة صالحة، ومناسبة لي، فأرجو منكما يعني السماح، وعدم المطالبة بفراقها، يعني يفعل ما يستطيع إذا كانت في نفسها طيبة، وسليمة.  أما إذا كانت المطالبة من الأبوين لعلة فيها؛ لأنها منحرفة عن الطريق السوي، ومتهمة بالسوء، والقرائن ظاهرة، والأسباب ظاهرة؛ فالواجب طاعتهما في هذه الحال.","link":"https://binbaz.org.sa/fatwas/1273/حكم-طلاق-الزوجة-مراعاة-لطلب-والد-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_260.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":5922,"question":"هل الطلاق الذي يعد في عهد الرسول طلقة واحدة هل هو الذي يطلق ثلاث متتاليات، أي من ثلاث كلمات في مجلس واحد، أم هو نطق بالطلاق من لفظ واحد، مثل أن يقول: أنتِ طالق بالثلاث، نرجو بيان ذلك؟","title":"التفصيل في الطلاق بلفظ واحد","answer":"الجواب: ثبت عنه من حديث ابن عباس أنه قال: كان الطلاق على عهد النبي ﷺ الطلاق الثلاث بواحدة، فلما كان عمر قال: إن الناس استعجلوا في أمر كانت لهم فيه أناة، فأمضاه عليهم. والمشهور عند العلماء أن المراد بهذه الثلاث الطلاق بفم واحد كلمة واحدة، أنت مطلقة ثلاثًا، أنت طالق بالثلاث، هي طالق بالثلاث، هذا هو الأظهر في هذه المسألة: أن التطليق بكلمة واحدة ... الثلاث، وهذا هو المروي عن ابن عباس: أن التطليق بالثلاث .. واحدة أنت طالق بالثلاث، أنت مطلقة بالثلاث.  وذهب بعض أهل العلم إلى أن الطلاق بالثلاث، ولو تكرر ما دام في مجلس واحد، وبعضهم قال: حتى ولو في مجالس ما دام ما بينهما رجعة، ولا نكاح؛ فإنه لا يقع إلا الأولى، والثانية والثالثة لا تقعان، وجعل الحديث يعم الجميع، وليس هذا بواضح من الأحاديث، فإنها رجعية، المطلقة طلقة واحدة رجعية، فإذا طلقها الثانية؛ لحقتها الثانية، فإذا طلقها الثالثة؛ لحقتها، وإنما يمتنع اللحوق إذا كانت بائنة بخلع المخالعة المفسوخة، لم تلحقها الثانية، ولا الثالثة. أما إذا طلقها طلاقًا رجعيًا واحدًا، ثم أتبعها ثانية، وثالثة؛ فإن الأظهر من كلام العلماء أنه يقع عليها الطلاق، وتحرم في الثانية، والثالثة، وهذا هو الذي أفتي به، وهو الذي ظهر لي مما جاء في النصوص، ومن آثار الصحابة -رضي الله عنهم وأرضاهم- أن الطلاق بالثلاث تحتسب واحدة إذا جمعها بكلمة واحدة، أو كتبه جملة واحدة، هي طالق بالثلاث كتابة أو لفظًا، كان هذا واحدة في عهد النبي ﷺ وفي عهد الصديق، وفي أول خلافة عمر، ثم نظر عمر في هذا وقال : إن الناس استعجلوا في هذا الأمر ... فيه فلأمضينه عليهم، فأمضاه عليهم  وتابعه أكثر الصحابة في هذا. وروي عن علي، والزبير، وعبدالرحمن بن عوف، وابن عباس أنهما جعلوه واحدة على ما كان في عهد النبي ﷺ وهذا هو الأرجح للدليل، وهذا هو الأنفع للمسلمين أيضًا، والأرفق بهم.","link":"https://binbaz.org.sa/fatwas/1274/التفصيل-في-الطلاق-بلفظ-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_261.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":5923,"question":"......؟","title":"حكم جلوس الرجال والنساء في مجلس واحد للتحدث","answer":"الجواب: إذا كان النساء مع النساء، والرجال مع الرجال ما في كشف للرجال، ولا إظهار زينة؛ لا بأس. أما أن يجتمعوا جميعًا من غير تحجب، ومن غير مبالاة؛ فلا يجوز هذا، بل إذا كانت النساء مع النساء في وقت ما ليس فيه سهر، ولا إضاعة أوقات، ولا يجتمعن على باطل، لا بأس، إذا زار النساء الجيران، هذا طيب بين الجيران، لكن بشرط أن يكون ذلك على غير سوء، على غير عمل صالح، يعني حتى لا يكون هذا على عمل سيئ، ولا يكون معه التكشف للجار، أو لزوج الجارة، أو ما أشبه ذلك، بل يكون معه احتشام، وتستر، وحجاب، والنساء مع النساء، والرجال مع الرجال في غير معصية، بل زيارات مناسبة في حد مناسب، وفي اجتماع مناسب للتنفيس عن النفس، والترويح عنها، وللتحدث الذي جرت به العادة بين الجيران، فهذا لا بأس به.","link":"https://binbaz.org.sa/fatwas/1268/حكم-جلوس-الرجال-والنساء-في-مجلس-واحد-للتحدث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_255.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":5925,"question":"كيف الجمع بين قول الله تعالى: وَاضْرِبُوهُنَّ [النساء:34] وبين قول الرسول ﷺ: ليس من خياركم من يضرب زوجته أو كما قال؟","title":"التفصيل في حكم ضرب الزوجة","answer":"الجواب: لا منافاة؛ فإن الرسول ﷺ أراد بذلك أن لا يسارعوا بالضرب، وليس من الصفات الخيرة المسارعة إلى الضرب، بل الضرب آخر الطب، الضرب يكون هو آخر الطب، قبله الهجر، وقبله الوعظ.  فينبغي للزوج أن لا يلجأ إلى الضرب إلا عند الضرورة، وعند الحاجة، وعند عدم جدوى الوسائل الأخرى؛ لأن الضرب قد يغيرها عليه أكثر، وقد يسيئ أخلاقها، ويسبب فراقها، ويثير أهلها أيضًا، ولاسيما في هذا العصر، الضرب في هذا العصر يسبب مشاكل كثيرة، فينبغي للزوج أن لا يعجل، وألا يسارع إلى الضرب إلا عند الحاجة، وأمن العاقبة، أمن العواقب السيئة. فإذا كان ضربها يفضي إلى فراقه لها، وإلى قيام أهلها عليه، وإلى حصول مشكلة كبرى؛ فينبغي تجنب الضرب، والصبر على ما قد يقع من سوء الأخلاق، حتى يعجل الله الحال بطرق العلاج الذي هو الوعظ، والتذكير، أو الهجر، فالزوج ينبغي أن يكون حكيمًا؛ لأن الضرب يترتب عليه مشاكل، وربما أفضى إلى غير المطلوب، والمراد به التعديل، والمراد به أن تراجع خطأها، فإذا كان الضرب يفضي إلى خلاف ذلك، وإلى مزيد السوء، وإلى مزيد المشاكل، وإلى تفاقم الأمور، فينبغي تركه، وعدم فعله. الحاصل: أن الضرب رخصة، رخص فيها ربنا  للتأديب إذا دعت الحاجة إليه بعدما قدم عليه من الوعظ، والهجر، وليس من الأفضل أن يسارع إليه، أو يفرح به، أو يتخذه علاجًا دائمًا لا، بل الأفضل أن يؤخر، وأن لا يعجل؛ جمعًا بين النصوص.","link":"https://binbaz.org.sa/fatwas/1280/التفصيل-في-حكم-ضرب-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_267.mp3","categories":["الحقوق الزوجية","الآداب والأخلاق"]},{"id":5926,"question":"هل الطلاق يكون طلقة في كل طهر، أم الأفضل أن يطلق طلقة واحدة في طهر، ثم يتركها حتى تنتهي العدة، فيكون بذلك بائن بينونة صغرى؟","title":"حالات الطلاق السني","answer":"الجواب:\n\nهذا هو السنة، أن تطلقها طلقة واحدة في طهر لم يجامعها فيه، ثم يتركها حتى تنتهي عدتها، أو يراجعها، أما كونه يطلق في كل طهر لا، هذا يروى عن ابن عباس، لكن ليس بجيد، بل يفوتها عليه، ويضره بدون حاجة، وإنما السنة أن يطلقها واحدة في طهر لم يجامعها فيه، كما أمر بذلك النبي ﷺ ابن عمر، ثم ليمسكها، فإذا طهرت بعد الحيضة الثانية؛ فليطلقها قبل أن يمسها، فتلك العدة التي أمر الله أن تطلق لها النساء، لقوله سبحانه: يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ[الطلاق:1] الآية، فتطليقها للعدة أن يطلقها طاهرة بغير جماع، هذا هو الطلاق الشرعي. \n\nوالمرأة لها أحوال خمسة: ثلاث حالات الطلاق فيها بدعي، وحالان الطلاق فيها شرعي، فالطلاق البدعي في حال الحيض، وفي حال النفاس، وفي حال الطهر الذي جامعها فيه، في هذه الأحوال الثلاثة لا يطلقها، لا في الحيض، ولا في النفاس، ولا في طهر جامعها فيه.\n\nأما الحالتان اللتان فيهما الطلاق الشرعي فهما: حال الحمل كونها حاملًا، وكذلك إذا طلقها في طهر لم يجامعها فيه، فهذا هو الطلاق الشرعي المندوب.\n\nوينبغي للرجل أن يلاحظ هذه الأشياء، وأن لا يعجل في الطلاق؛ لأن الطلاق مبغوض إلى الله، أبغض الحلال إليه الطلاق، والله -جل وعلا- يحب بقاء النكاح، لا فصل النكاح؛ لما فيه من المصالح، والفوائد الكثيرة. \n\nفينبغي للزوج أن لا يعجل، وأن يتحرى أوقات الطلاق الشرعي إذا عزم على الطلاق، وألا يعجل في الأمور، فليتأنى، وينظر، فإذا طابت نفسه، ورأى أن الطلاق أصلح؛ طلقها طلقة واحدة في طهر لم يجامعها فيه، ثم يتركها حتى تنتهي عدتها، فتكون بائنة بذلك بينونة صغرى، لا يحلها إلا عقد شرعي، هذا هو المشروع في هذه المسائل.","link":"https://binbaz.org.sa/fatwas/1275/حالات-الطلاق-السني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_262.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":5927,"question":"رجل متزوج، لكن أهله يرغبون أن يطلق زوجته لعدم التفاهم معها، بينه وبين إخوته في المنزل، ولم تأت بشيء يوجب طلاقها، علمًا بأن المحبة، والتفاهم سائد بين الرجل، وامرأته، فما العمل، جزاكم الله خيرًا؟","title":"ما حكم تطليق الرجل تلبية لرغبة أهله؟","answer":"الجواب: إذا تزوج الرجل امرأة لم تناسب أهله، ولم يحصل تواطؤ بينها، وبين أهله، فهذا محل تفصيل، إن كان ذلك لسوء تصرفاتها، وسوء عملها، وأنها تتهم بالشر، فينبغي له فراقها، والنساء سواها كثير.  أما إذا كان لأمر آخر؛ فينبغي له أن يعالج الأوضاع بالهدوء، والكلام الطيب، والعبارات الحسنة، والأساليب الطيبة، ولا يعجل في الأمور، بل ينبغي أن يعالجها بالعلاج الحسن، ولاسيما إذا كان الخلاف بينه، وبين إخوته فأمره أسهل. أما إن كان بين الأبوين فهو أشد، فينبغي له أن يجتهد في علاج الموضوع مع أبويه؛ لأن حقهما عظيم؛ ولأن برهما واجب، فينبغي أن يعالج الأوضاع بأن يقول لها: أن تتأدب معهما، وأن تحسن الصلة بهما، وأن تكف عما يسيئ إليهما إذا كانت صالحة في نفسها؛ حتى تهدأ الأمور، وحتى يرضيا عنها، وتزول أسباب المطالبة بفراقها. أما إذا كان هذا لانحرافها، وسوء عقيدتها، أو سوء خلقها باتهامها بالفواحش، والانحراف عن الدين؛ فينبغي أن يطيع إخوته، ووالديه في ذلك، وأن يبعدها ،وسوف يغنيه الله خيرًا منها، كما قال الله -جل وعلا-: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا  ۝  وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ [الطلاق:2، 3] وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] نسأل الله للجميع الهداية.","link":"https://binbaz.org.sa/fatwas/1270/ما-حكم-تطليق-الرجل-تلبية-لرغبة-اهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_257.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":5931,"question":"رجل متزوج، لكن أهله يرغبون أن يطلق زوجته لعدم التفاهم معها، بينه وبين إخوته في المنزل، ولم تأت بشيء يوجب طلاقها، علمًا بأن المحبة، والتفاهم سائد بين الرجل، وامرأته، فما العمل، جزاكم الله خيرًا؟","title":"ما حكم تطليق الرجل تلبية لرغبة أهله؟","answer":"الجواب: إذا تزوج الرجل امرأة لم تناسب أهله، ولم يحصل تواطؤ بينها، وبين أهله، فهذا محل تفصيل، إن كان ذلك لسوء تصرفاتها، وسوء عملها، وأنها تتهم بالشر، فينبغي له فراقها، والنساء سواها كثير.  أما إذا كان لأمر آخر؛ فينبغي له أن يعالج الأوضاع بالهدوء، والكلام الطيب، والعبارات الحسنة، والأساليب الطيبة، ولا يعجل في الأمور، بل ينبغي أن يعالجها بالعلاج الحسن، ولاسيما إذا كان الخلاف بينه، وبين إخوته فأمره أسهل. أما إن كان بين الأبوين فهو أشد، فينبغي له أن يجتهد في علاج الموضوع مع أبويه؛ لأن حقهما عظيم؛ ولأن برهما واجب، فينبغي أن يعالج الأوضاع بأن يقول لها: أن تتأدب معهما، وأن تحسن الصلة بهما، وأن تكف عما يسيئ إليهما إذا كانت صالحة في نفسها؛ حتى تهدأ الأمور، وحتى يرضيا عنها، وتزول أسباب المطالبة بفراقها. أما إذا كان هذا لانحرافها، وسوء عقيدتها، أو سوء خلقها باتهامها بالفواحش، والانحراف عن الدين؛ فينبغي أن يطيع إخوته، ووالديه في ذلك، وأن يبعدها ،وسوف يغنيه الله خيرًا منها، كما قال الله -جل وعلا-: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا  ۝  وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ [الطلاق:2، 3] وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] نسأل الله للجميع الهداية.","link":"https://binbaz.org.sa/fatwas/1270/ما-حكم-تطليق-الرجل-تلبية-لرغبة-اهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_257.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":5942,"question":"هل الإسلام يأمر بإخفاء البشرة، أو يأمر بإخفاء العضو نفسه؟ فإذا كان يأمر بإخفاء العضو نفسه، فما بال الرجال الذين يلبسون الملابس الأوروبية التي لا تستر من الجسم إلا البشرة، وتترك العضو كما هو هل ذلك مقبول في الإسلام؟","title":"كيفية ستر المسلم والمسلمة لجسديهما","answer":"الجواب:  الستر مطلوب، والرجال، والنساء يختلفون في هذا، فالمرأة عورة كلها، وأمرها خطير، وقد سمعت أيها السائل قول النبي ﷺ: ما تركت بعدي فتنة أضر على الرجال من النساء فالواجب على النساء التستر، والعناية، وعدم إظهار حجم الأعضاء بالملابس الضيقة، أو الملابس الرقيقة. الواجب عليهن أمر كبير، وواضح المعنى، وخطر تفريطها في ذلك واضح كبير، فستر الأعضاء واجب عن غير المحارم، أما المحارم فقد سمعت في الندوة، ما سمعت، وأن المحرم يباح له النظر إلى ما ظهر منها غالبًا من وجه، وكفين، وقدمين، ونحو ذلك، كالقرط، والحلق، ونحو ذلك. وأما الرجل فأمره أوسع إذا ستر ما بين السرة، والركبة بشيء صفيق متين، يستر ما بين السرة، والركبة، فهذا كاف، فإن عورة الرجل ما بين السرة، والركبة، فإذا ستر ذلك سترًا كافيًا؛ يغطي العورة، ولا يبينها، لا عورة الفرج الدبر، ولا الذكر، ولا الخصيتين، يكون ساترًا سترًا كافيًا، فلا بأس بذلك.  وإذا كان في مواضع كما أشار الشيخ عبدالله بن جبرين، إذا كان في مواضع قد يستقبحون ظهور الصدور، أو ظهور الظهر، فستر ذلك عندهم كان ذلك أكمل، فإن العرف يختلف، والبلدان تختلف، والمجامع تختلف، فلا ينبغي للإنسان أن يتساهل في مثل هذه الأمور، بل ينبغي له أن يفعل ما لا يستنكر، ولا يستقبح في عرف الناس، حتى لا يرمى بالتساهل في دينه، أو يرمى بشيء آخر مما يضره. كذلك إذا كان صاحب بدن جميلًا، وشابًا خطيرًا فإنه ينبغي التستر الستر الكامل، فإن بعض الناس قد يعشق المردان أعظم مما يعشق النساء؛ فينبغي في مثل هذا الحذر، ولا يقال في حق الأمرد أنه يبدي صدره، ويبدي أكتافه، ويبدي سيقانه؛ فإنه قد يضر الناس بهذا، وقد يفتن الناس بهذا، وقد يبتلى هو، فينبغي له في مثل هذا أن يتستر، وأن يلبس القمص الساترة، وأن يحذر من بلاء الجمال، وبلاء فتنة الناس في بعض المردان، فهذا شيء خطير. وأقل شيء في حق الشاب، أقل شيء أن يستر ما بين الركبة، والسرة سترًا كافيًا، صفيقًا، عظيمًا؛ لعله ينجو، وإذا أطال الستر حتى ستر أغلب الساق؛ فهو خير، وإذا ستر صدره، وظهره بفانيلة جيدة ساترة؛ فهو أكمل، وأكمل، وهكذا ما يقع في لعب الكرة، ينبغي فيه التستر غاية التستر، وأن تكون الفخذ مستورة سترًا كاملًا؛ فإنها عورة، وإذا ستر مع ذلك الساق، وستر مع ذلك ما فوق السرة بالفانيلة؛ كان أكمل، وأسلم في حقه، وأسلم في حق غيره أيضًا، رزق الله الجميع العافية.","link":"https://binbaz.org.sa/fatwas/1314/كيفية-ستر-المسلم-والمسلمة-لجسديهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_283.mp3","categories":["الآداب والأخلاق","اللباس والزينة"]},{"id":5947,"question":"ما رأيكم فيمن يرى أن حجاب المرأة المسلمة، وتسترها يكون سببًا في الشوق إلى رؤيتها، وأنها إذا كشفت وجهها، وذراعيها يكون سببًا في عدم الشوق إلى التطلع، أو النظر إليها؟","title":"الرد على القائل: إن الحجاب دافع للتطلع والافتتان بالمرأة","answer":"الجواب: هذا من دسائس أعداء الله، وهذا من مكائد الشيطان، يقول لهم أعداء الله، ويقول لهم الفجرة من النساء: لو تكشفت، لو أنها كشفت وجهها، وذراعيها؛ صار ما عدى لها قيمة، ولا أهمية، ولا ينظر الناس إليها، وإذا تحجبت؛ فتن الناس بها، هذا من مكائد الشيطان بعد قد يقولون لها: لو أنها مشت عارية؛ لكان أحسن، هذا النتيجة، نسأل الله العافية. الحاصل: أن هذا من مكائد الشيطان، ومن مكائد أعداء الله، والله جعل الحجاب مانعًا للشر؛ قال  في كتابه العظيم، وهو أصدق القائلين: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] هكذا يقول ربنا  يقول: إن الحجاب أطهر لقلوبنا، وقلوب النساء جميعًا؛ فدل ذلك على أن عدم الحجاب أخبث للقلوب، ليس أطهر للقلوب، وأنه ينجسها.","link":"https://binbaz.org.sa/fatwas/1317/الرد-على-القاىل-ان-الحجاب-دافع-للتطلع-والافتتان-بالمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_286.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":5957,"question":"إذا صلى أمام الإمام في المسجد النبوي في المدينة في الزحام مثلًا؟","title":"حكم التقدم على الإمام حال الزحام","answer":"الجواب: ما يجوز الصلاة أمام الإمام، الصحيح لا يجوز، بل يكون خلف الإمام، بعض أهل العلم يقول: يجوز للضرورة، إذا كان للضرورة؛ صحت صلاته، لكن ينبغي أن يمنعوا من هذا، ينبغي أن يكونوا خلف الإمام، أو عن يمينه، وشماله، لا أمامه، هذا هو الذي ينبغي.","link":"https://binbaz.org.sa/fatwas/1325/حكم-التقدم-على-الامام-حال-الزحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_294.mp3","categories":["الآداب والأخلاق","صلاة الجماعة"]},{"id":5973,"question":"هل يجوز الزواج من زوجة والد زوجتي، أم لا؟","title":"حكم الزواج بزوجة والد الزوجة","answer":"الجواب: نعم، يجوز أن يتزوج زوجة والد زوجته إذا كانت ما هي أمها أجنبية، ما بينهم رضاع، ولا شيء؛ فيجمع بين امرأة، وبين زوجة أبيها التي ليست أمها، تزوج عبدالله بن جعفر من ابنة علي -رضي الله عنهم- التي ليست هي أمها.  المقصود: أنه لا بأس أن يجمع بين امرأتين، إحداهما زوجة أبي الأخرى.","link":"https://binbaz.org.sa/fatwas/1359/حكم-الزواج-بزوجة-والد-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_317.mp3","categories":["المحرمات من النساء","الآداب والأخلاق"]},{"id":5981,"question":"بر الوالدين واجب، وقد ورد ذكر بر الوالدين في آيات كثير من القرآن الكريم، ولكن إذا كان أحد الوالدين قاسيًا على ولده، وخرج منه، وقد أخذ الوالد يدعو عليه، هل يعتبر خروجه منه معصية، وعقوقًا لوالديه، أم لا؟","title":"هل يجوز الخروج على الوالد القاسي في معاملته؟","answer":"الجواب: هذا المقام فيه تفاصيل، وتقدم لكم أن الوالد له حق عظيم، والوالدة كذلك، وأنه ينبغي للوالد أن لا يكون  قاسيًا، ولا شديدًا، بل يكون لطيفًا رحيمًا؛ حتى يعين أولاده على بره، ويعينهم على بره بعبارته الطيبة، ولينه، وعدم قسوته.  ولكن بعض الأولاد أيضًا شر، بعض الأولاد شر يدعون إلى الشر، وهكذا بعض الزوجات كما قال الله -جل وعلا-: يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّ مِنْ أَزْوَاجِكُمْ وَأَوْلَادِكُمْ عَدُوًّا لَكُمْ فَاحْذَرُوهُمْ [التغابن:14] وقال: إِنَّمَا أَمْوَالُكُمْ وَأَوْلَادُكُمْ فِتْنَةٌ [التغابن:15] فهم فتنة، يعني اختبار، وامتحان، قد يختبر الله الآباء، والأمهات في أولادهم، فإن نصحوا لهم، ووجّهوهم إلى الخير؛ أثابهم الله، وإن تساهلوا معهم في المعاصي، والسيئات؛ استحقوا العقاب من الله .  والأولاد، والزوجات أيضًا قد يكونون شرًّا، قد تكون الزوجة شرًّا على زوجها، تدعوه إلى الباطل، تدعوه إلى الفساد، والمعاصي، وهكذا الولد قد يكون خبيثًا، يدعو والده إلى الشر، والبلاء، والفساد؛ فيجب على الوالد أن يحذر، وألا ينساق مع أولاده وأن لا ينساق مع زوجاته فيما لا ينبغي، بل ينظر فيما يدعون إليه ويختار الطيب، ولا يختار الخبيث.  إذا دعت الزوجة إلى شيء فلا يسارع إلى إجابتها حتى ينظر النتيجة، وهل هذا شيء يرضي الله، هل هو جائز، وما عاقبته، فيختار من ذلك ما فيه الخير، والعاقبة الحميدة، ولا يضره ذلك.  وهكذا الولد قد يكون شرًا، قد يكون فاسدًا، قد يكون منافقًا، قد يكون كافرًا يتلبس بالإسلام، فليحذر هذا الولد، ولا يأخذ من كلامه، ولا من دعوته، ولا من طلباته إلا ما كان يرضي الله، ومما أباح الله  ومما يرجو فيه العاقبة الحميدة حتى لا يقع في شر مما حذر الله منه. فإذا قال له أبوه، فإذا فعل معه أبوه ما يوجب الخروج، وخرج؛ فلا بأس، إذا كان والده ضيق عليه، وضيق على زوجته، ولم يمكنهما مما ينبغي مما أباح الله لهما لسوء خلق الوالد، فلا ينبغي له، بل يعالج الأمور بالتي هي أحسن، يرفق بوالده ويقول: يا والدي ارفق بنا أرجو أن تفعل كذا، وكذا، وإلا فاسمح لنا أن نخرج من هذا البيت إلى بيت آخر، يخاطبه بالتي هي أحسن، فإن استطاع أن يجلس مع والديه، ويرفق بهما؛ فهذا هو المطلوب، وهذا هو الذي ينبغي له، وإن لم يتيسر ذلك؛ لشدة الوالد، ولأنه يعامله معاملة قاسية تضره في دينه، ودنياه، وربما سببت عليه انحرافه عن الهدى، وربما سببت أيضًا عقوقه لوالده ووقوعه فيما حرم الله؛ فليخرج، وليعامل والديه بالتي هي أحسن، ولو دعوا عليه يرفق بهما، ويعاملهما بالتي هي أحسن، ويجتهد في برهما، وإرضائهما.","link":"https://binbaz.org.sa/fatwas/1355/هل-يجوز-الخروج-على-الوالد-القاسي-في-معاملته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_312.mp3","categories":["الدعوة والدعاة","الآداب والأخلاق"]},{"id":5985,"question":"ما حكم إذا صام الإنسان أيام البيض، وفي أثناء الصوم حلف أحد الأبوين بأن يفطر، فهل يفطر، أم يكمل الصوم؟","title":"حكم طاعة الوالدين في ترك أعمال مستحبة","answer":"الجواب: بر الوالدين واجب، وصوم البيض مستحب، فلا يقدم المستحب على الواجب، إذا كان والداه يعطفان عليه، ويخافان عليه؛ لأنه في وقت شدة الحر، أو ما أشبه ذلك، أو لأنه يعطل أسبابًا تنفعهم، يعطل ما ينفعهم ويحتاجون إليه من حاجات البيت من البيع، والشراء، والحرث، والفلاحة، ونحو ذلك، وهم في حاجة إلى ذلك. فالمقصود: إذا كان قصدهما خيرًا، وطيبًا فليجبهما، ولا يصم النافلة؛ لأن النافلة مستحبة، وبرهما واجب، والواجب مقدم على المستحب. السؤال: إذا كان المقصود العاطفة على الابن؟ الجواب: ولو ولو ، إذا كان الصوم يشوش عليهما، وربما أفضى إلى أن يقطعاه، ويغضباه عليه فليتق الله.","link":"https://binbaz.org.sa/fatwas/1356/حكم-طاعة-الوالدين-في-ترك-اعمال-مستحبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_313.mp3","categories":["الدعوة والدعاة","الآداب والأخلاق"]},{"id":6019,"question":"هل صوت المرأة عورة، مع ذكر الدليل؟","title":"حكم صوت المرأة","answer":"الجواب:  صوت المرأة ليس بعورة، النبي ﷺ سمع كلام النساء، وسمعه الصحابة، وكن يسألن النبي ﷺ والصحابة يسمعون، وقد طلبن من النبي ﷺ مجلسًا لهن، فجمعهن في محل، وجاء إليهن، فصوتهن ليس بعورة، فلها أن تسأل الرجال عن أحكام الدين، وعما أشكل عليها، ولها أن تخاصم من يدعي عليها، أو تدعي عليه.  لكن عليها ألا يكون صوتها فيه خضوع، وترقيق، بل هو صوت معتاد لا .. ولا ترقيق، بل بين ذلك، والله -جل وعلا- نهى نساء النبي ﷺ أن يخضعن بالقول فيطمع الذي في قلبه مرض، فلا يجوز لها أن تخضع بالقول حال كلامها، وخصومتها، فيكون قولها، وكلامها بالطريقة المعتادة التي ليس فيها ما يوهم أنها تريد شيئًا، أو أنها تُشهر في نفسها، فليكن الصوت معتادًا الذي ليس فيه تكسر، وليس فيه ترخيم، وليس فيه ما يدعو الرجال من خضوعها بقولها، ولكن صوتًا معتادًا بسؤالها، وكلامها، وخصومتها، وردها الخصومة إلى غير ذلك، الصوت المعتاد الذي لا يطمع فيها أصحاب المرض.","link":"https://binbaz.org.sa/fatwas/1383/حكم-صوت-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_339.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6027,"question":"هل صوت المرأة عورة، مع ذكر الدليل؟","title":"حكم صوت المرأة","answer":"الجواب:  صوت المرأة ليس بعورة، النبي ﷺ سمع كلام النساء، وسمعه الصحابة، وكن يسألن النبي ﷺ والصحابة يسمعون، وقد طلبن من النبي ﷺ مجلسًا لهن، فجمعهن في محل، وجاء إليهن، فصوتهن ليس بعورة، فلها أن تسأل الرجال عن أحكام الدين، وعما أشكل عليها، ولها أن تخاصم من يدعي عليها، أو تدعي عليه.  لكن عليها ألا يكون صوتها فيه خضوع، وترقيق، بل هو صوت معتاد لا .. ولا ترقيق، بل بين ذلك، والله -جل وعلا- نهى نساء النبي ﷺ أن يخضعن بالقول فيطمع الذي في قلبه مرض، فلا يجوز لها أن تخضع بالقول حال كلامها، وخصومتها، فيكون قولها، وكلامها بالطريقة المعتادة التي ليس فيها ما يوهم أنها تريد شيئًا، أو أنها تُشهر في نفسها، فليكن الصوت معتادًا الذي ليس فيه تكسر، وليس فيه ترخيم، وليس فيه ما يدعو الرجال من خضوعها بقولها، ولكن صوتًا معتادًا بسؤالها، وكلامها، وخصومتها، وردها الخصومة إلى غير ذلك، الصوت المعتاد الذي لا يطمع فيها أصحاب المرض.","link":"https://binbaz.org.sa/fatwas/1383/حكم-صوت-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_339.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6088,"question":"إذا تزوج رجل بنتًا، وبعد الدخول عليها لم يجدها بكرًا، فماذا يفعل؟","title":"حكم من تبين أنها ليست بكراً بعد الدخول بها","answer":"الجواب: هذا له أسباب قد تكون البكارة ذهبت بأسباب غير الزنا، فيجب حسن الظن إذا كان ظاهرها الخير، وظاهرها الاستقامة يجب حسن الظن في ذلك، أو كانت قد فعلت فاحشة، ثم تابت، وندمت، وظهر منها الخير لا يضره ذلك، وقد تكون البكارة زالت بشدة الحيض، فإن الحيضة الشديدة تزيل البكارة كما قال العلماء.  وكذلك تزول البكارة ببعض الوثبات إذا وثبت من مكان إلى مكان، وطمرت من مكان إلى مكان، أو نزلت من محل مرتفع إلى محل سافل بقوة، قد تزول البكارة، فليس من لازم البكارة أن يكون زوالها بالزنى، لا، فإذا ادعت أنها زالت البكارة بأمر غير الفاحشة؛ فلا حرج عليه، أو بأمر من فاحشة، ولكنها مغصوبة مكرهة، فإن هذا لا يضر أيضًا، إذا كان قد مضى عليها حيضة بعد الحادث، أو ذكرت أنها تابت، وندمت، وأن هذا الذي فعلته في حال سفهها، وجهلها، ثم تابت، وندمت؛ فإنه لا يضر، ولا ينبغي أن يشيع ذلك، بل ينبغي أن يستر عليها، فإن غلب على ظنه صدقه، واستقامتها؛ أبقاها، وإلا طلقها مع الستر، وعدم إظهار ما يسبب الفتنة، والشر.  السؤال: ..؟ الجواب: لا، ما يلزم إلا إذا عرف أنها فاحشة؛ لأن البكارة قد تزول بالحيض، وقد تزول بأسباب أخرى، وقد تكون مكرهة، والمكرهة لها حكم من لم يفعل شيئًا، وقد تكون أيضًا... فعلته عن موافقة، ولكن الله تاب عليها، وتحسنت حالها.\n\nالسؤال: بعض البلدان يحبوا أن يروا البكارة في الثوب، فإذا وجد رجل امرأته فيها غير بكارة، وأراد أن يستر ذلك، فكلمها بذلك، وفكها، هل لهم أن يردوا له فلوسه؟ الجواب: هذا إذا كان ضروري يمكن أن يفعل هذا بشيء آخر، بدم آخر للستر عليها، وهو بعد ذلك مخير، إن شاء أبقاها، وإن شاء طلقها، يمكن أن يجعل دمًا من غير البكارة إذا كان ضروريًا؛ لأنه لا بدّ من إظهار شيء في عاداتهم، فإذا لم يفعل اتهموها بالزنى، بإمكانه أن يضع شيئًا من دماء من دم آخر من باب الستر على الناس، والنبي يقول: من ستر مسلمًا؛ ستره الله في الدنيا، والآخرة.","link":"https://binbaz.org.sa/fatwas/1509/حكم-من-تبين-انها-ليست-بكرا-بعد-الدخول-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_439.mp3","categories":["الشروط والعيوب في النكاح","الآداب والأخلاق"]},{"id":6095,"question":"إذا اتفق الإخوة أن يزوجوا عيالهم كل واحد ابنة الثاني من دون مهر، فهل يدخل في ذلك الشغار؟","title":"حكم النكاح بين الأقارب إذا خلا من المشارطة والمهر","answer":"الجواب: ليس هذا من الشغار، إذا كان ما هو شرط، وهذا خطب هذه، وهذا خطب هذه، واتفق آباء الأولاد والنساء على ذلك من دون شرط؛ فلا بأس بذلك، ولكن لا بدّ من المهر، لكل واحدة مهر المثل، وإن لم يسموا؛ فلا بدّ من المهر؛ لأن الله -جل وعلا- قال: لَا جُنَاحَ عَلَيْكُمْ إِنْ طَلَّقْتُمُ النِّسَاءَ مَا لَمْ تَمَسُّوهُنَّ أَوْ تَفْرِضُوا لَهُنَّ فَرِيضَةً [البقرة:236] فالنكاح صحيح، ثم قال بعده وَمَتِّعُوهُنَّ [البقرة:236]،وفي الحديث الصحيح أن النبي ﷺ سئل عن المرأة التي لا يفرض لها، قال :  لها مهر نسائها، لا وكس، ولا شط.  السؤال:...؟ الجواب: إذا تراضوا به؛ لا بأس، إذا تراضوا على الكسوة، أو على دراهم، أو على حلي ذهب، وفضة؛ كفى.","link":"https://binbaz.org.sa/fatwas/1507/حكم-النكاح-بين-الاقارب-اذا-خلا-من-المشارطة-والمهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_437.mp3","categories":["الآداب والأخلاق","شروط وأركان الزواج"]},{"id":6100,"question":"من نوى التوقيت في الزواج هل يكون ذلك متعة؟","title":"من نوى التوقيت في الزواج هل يكون ذلك متعة؟","answer":"الجواب: التوقيت محل نظر، النية محل نظر إذا كان ليس بشرط، ولم يتفقا على شرط، فقد اختلف العلماء في ذلك، والأولى والأصح أنه لا يكون متعة، فلو تزوجها في الغربة، ونيته أنه إذا أراد الرجوع؛ طلقها، فالصحيح أن هذا لا حرج فيه؛ لأنه قد يعدل عن نيته، وقد يرغب بها، وينقلها ما دام لا مشارطة بينهما، وأنها في نيته أنه لا ينتقل بها إلى بلاده، فلا يضر هذا، ليس بشرط، وليس من المتعة على الصحيح. وذهب بعض أهل العلم إلى أنه يكون متعة إذا كان في نيته ذلك، ولكن الأرجح، والأقرب، والأظهر أنه ليس بمتعة، والناس يحتاجون إلى هذا، قد يكون في بلد غربة، أمريكا، أو إنجلترا، أو غير ذلك، ويخشى على نفسه الفتنة، فيسهل الله له زوجة مناسبة، فيتزوج، ونيته أنه متى أراد العودة طلقها؛ لأنها قد لا تناسب بلاده، أو لأسباب أخرى، فهذا لا يمنع من صحة النكاح، وهذه النية قد تنقلب، قد تنفسخ، قد يرغب فيها، وينقلها؛ فلا يضره هذه النية لعدم المشارطة.","link":"https://binbaz.org.sa/fatwas/1515/من-نوى-التوقيت-في-الزواج-هل-يكون-ذلك-متعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_445.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6102,"question":"هل يجب على المرأة الخروج إلى حاجتها إلى السوق بدون محرم؟ وهل يجوز للسائق الذي انتشر في هذه الآونة الأخيرة أن يصطحب النساء بدون محرم؟","title":"ضوابط وأحكام خروج المرأة","answer":"الجواب: خروج المرأة فيه تفصيل، إن كانت تخرج لحاجتها متسترة تعتني بنفسها؛ فلا بأس بخروجها، كان النساء يخرجن في عهد النبي ﷺ وعهد الصحابة لحاجاتهن، فإذا خرجت مع العناية، والستر، والحجاب؛ فلا حرج.  ولكن ينبغي مهما كان أن تقل الخروج، والحذر من عواقبه الوخيمة، وينبغي لأولياء المرأة مهما أمكن أن يقضوا حاجاتها، زوجها، وأخوها، وأبوها، ينبغي أن يقضوا حاجاتها، ولاسيما في هذا العصر الذي كثر فيه الشر، والفساد، وتعرض النساء للفساد، فينبغي في مثل هذا أن تقل الخروج، والحذر من شره، وينبغي للأولياء أن يقضوا حاجات المرأة؛ حتى يكفوهن مؤنة الخروج مهما أمكن، ولا يحتاج خروجها إلى محرم؛ لأنه ما هو بسفر، المحرم للسفر.","link":"https://binbaz.org.sa/fatwas/1517/ضوابط-واحكام-خروج-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_447.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6138,"question":"هل يجوز يا شيخ الحديث في المساجد في أمور الدنيا؟","title":"كراهة الحديث عن أمور الدنيا في المساجد","answer":"الجواب: لا ينبغي يكره إلا إذا كان شيء قليل، أحاديث الدنيا تكون في البيوت، وفي المجالس، أما المساجد تصان عن هذا إلا الشيء اليسير، ينبغي أن تكون المساجد محل القراءة، والتسبيح، والتهليل، ومذاكرة العلم لا في أمور الدنيا، لكن يعفى عن اليسير. السؤال: ما كان السلف الصالح يفعلونه؟ الجواب: ما كانوا يفعلونه لا، اللهم إلا الشيء اليسير.","link":"https://binbaz.org.sa/fatwas/1580/كراهة-الحديث-عن-امور-الدنيا-في-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_481.mp3","categories":["المساجد ومواضع السجود","الآداب والأخلاق"]},{"id":6153,"question":"ما حكم إزالة الشعر من اليدين، والساقين للنساء؟","title":"حكم إزالة الشعر من اليدين والساقين للنساء والرجال","answer":"الجواب: سبق أنه لا نعلم فيه شيئًا، أما النمص، وهو حلق الحاجبين فهذا لا يجوز، أما شعر البدن في اليدين، أو الرجل ما نعلم فيه شيئًا، إنما الحديث جاء بلعن النامصة، والمتنمصة، وذلك أخذ شعر الوجه من ... أو الحاجبين، نص عليه أهل العلم .. فلا يجوز أخذ الحاجبين، ولا نمصهما، ولا شعر الوجه العادي .. أما كونه يأخذ الرجل، أو المرأة شعر اليدين، أو الرجلين؛ فلا بأس، ويشرع للرجل، والمرأة جميعًا أخذ شعر الإبطين، والعانة تحلق، والإبطين تنتف، والشارب يقص، هذا هو السنة، والظفر يقلم، هذا سنة للجميع للنساء والرجال، السنة ألا يتأخر ذلك أكثر من أربعين ليلة، يقول أنس : وقت لنا في قص الشارب، وقلم الظفر، ونتف الإبط، وحلق العانة ألا نترك ذلك أكثر من أربعين ليلة. والمشروع للجميع للرجل، والمرأة قلم الظفر، ونتف الإبط، وحلق العانة في أقل من أربعين ليلة، يعني يتعاهد ذلك، والشارب في حق الرجل كذلك لا يترك أكثر من أربعين ليلة، بل يتعاهد، ويقص قبل ذلك؛ لأنه يطول، ويقبح.","link":"https://binbaz.org.sa/fatwas/1612/حكم-ازالة-الشعر-من-اليدين-والساقين-للنساء-والرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_506.mp3","categories":["الآداب والأخلاق","اللباس والزينة"]},{"id":6169,"question":"إذا طلب الزوج مقابلة المرأة دون خلوة، فما هو الدليل على ذلك، والرسول ﷺ يقول: كل المرأة عورة؟","title":"حكم النظر إلى المخطوبة وضوابط ذلك","answer":"الجواب: لا حرج فيها، المرأة عورة، مثل ما جاء في الحديث، لكن استثنى النبي ﷺ من ذلك ما يتعلق بالخاطب إذا خطب، وأحب أن ينظر فلا بأس، النبي ﷺ قال: إذا خطب أحدكم المرأة فإن استطاع أن ينظر منها ما يدعوه إلى نكاحها فليفعل إذا استطاع أن ينظر، ولو من بعد من غير علمها، فلا بأس، خطب جابر بن عبدالله الأنصاري  امرأة من الأنصار ولم يرها قال: فجعلت أتتبع النخل لعلي أراها حتى رأى منها ما أعجبه منها فتزوجها. فالمقصود: أنه إذا تيسر له أن يراها ولو من بعيد، ولو من طريق وجوده في بيت أهلها، فتمر وهم راضون بذلك، وما أشبه ذلك، وإذا تيسر أن أباها، أو أخاها يحضرونه عندهم، ويدخلونها عليه، ويراها بغير خلوة بحضرة أبيها، أو أخيها، أو أمها، أو نحو ذلك فلا بأس، هذا أذن فيه النبي ﷺ ورخص.","link":"https://binbaz.org.sa/fatwas/1628/حكم-النظر-الى-المخطوبة-وضوابط-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_519.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":6171,"question":"إذا كان عند بعض الإخوان فتاة فتقدمت منها، فقال: إنه يريد أن يتزوج منا كما زوجناه، فهل هذا شغار، أو جائز؟","title":"حقيقة الشغار وحكمه","answer":"الجواب: هذا شغار، تقدمت إلى زيد، وقال: نعم، أزوجك لكن بشرط أن تزوجني أختك، أو بنتك، لا، النبي نهى عن الشغار، وقال: الشغار أن يقول الرجل: زوجني بنتك وأزوجك بنتي، أو زوجني أختك وأزوجك أختي فهذا هو الشغار، وهو نكاح البدن، فلا يجوز، فهذا يفضي إلى ظلم النساء، وإلى فتن، وإلى شرور كثيرة، ويفضي إلى إسقاط المهور .... بالفروج إلى غير ذلك.  وقد صحت عن النبي ﷺ أحاديث تنهى عن نكاح الشغار، ولو كان فيه مهر، وقد قال بعض العلماء: إذا كان فيه مهر كامل، مهر العادة؛ كفاه، وجاز، ولكنه قول مرجوح. والصواب: أنه لا يجوز، ولو كان فيه مئات الألوف، ما يجوز ما دام فيه هذا الشرط، وقد ثبت عن معاوية  أنه بلغه أن فلانًا وفلاًنا تزوجا نكاح الشغار، وقد سميا مهرًا، فكتب إلى أمير المدينة أن يبطل النكاح، وقال: هذا هو الشغار الذي نهى عنه النبي، عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/1626/حقيقة-الشغار-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_517.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6177,"question":"إذا طلب الزوج مقابلة المرأة دون خلوة، فما هو الدليل على ذلك، والرسول ﷺ يقول: كل المرأة عورة؟","title":"حكم النظر إلى المخطوبة وضوابط ذلك","answer":"الجواب: لا حرج فيها، المرأة عورة، مثل ما جاء في الحديث، لكن استثنى النبي ﷺ من ذلك ما يتعلق بالخاطب إذا خطب، وأحب أن ينظر فلا بأس، النبي ﷺ قال: إذا خطب أحدكم المرأة فإن استطاع أن ينظر منها ما يدعوه إلى نكاحها فليفعل إذا استطاع أن ينظر، ولو من بعد من غير علمها، فلا بأس، خطب جابر بن عبدالله الأنصاري  امرأة من الأنصار ولم يرها قال: فجعلت أتتبع النخل لعلي أراها حتى رأى منها ما أعجبه منها فتزوجها. فالمقصود: أنه إذا تيسر له أن يراها ولو من بعيد، ولو من طريق وجوده في بيت أهلها، فتمر وهم راضون بذلك، وما أشبه ذلك، وإذا تيسر أن أباها، أو أخاها يحضرونه عندهم، ويدخلونها عليه، ويراها بغير خلوة بحضرة أبيها، أو أخيها، أو أمها، أو نحو ذلك فلا بأس، هذا أذن فيه النبي ﷺ ورخص.","link":"https://binbaz.org.sa/fatwas/1628/حكم-النظر-الى-المخطوبة-وضوابط-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_519.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":6183,"question":"وآخر يسأل ما حكم نوم العصر؟","title":"حكم النوم بعد العصر","answer":"الجواب: لا نعلم فيه شيئًا، نوم العصر لا نعلم فيه شيئًا ولا حرج فيه، كل الأوقات لا نعلم فيها شيء، إلا المغرب كره النوم قبلها -عليه الصلاة والسلام- كان يكره النوم قبلها÷ أي قبل العشاء، والحديث بعدها. أما العصر، والظهر، والضحى، والصبح فليس فيه شيء، لكن يتحرى الإنسان الأوقات المناسبة إذا تيسر له الظهر، فهو أفضل من العصر، وإن تيسر له القيلولة قبل الظهر فهو أفضل، لكن بسبب الأعمال اليوم، كثير من الناس لا يحصل له قائلة، ولا ظهر؛ فلم يبق عنده إلا بعد العصر. وإذا نام أول النهار؛ فلا بأس، ولكن إذا تيسر له ألا ينام قبل النهار، بل يجلس، ويذكر الله، ويقرأ القرآن، أو في طلب العلم حتى ترتفع الشمس، ثم ينام بعد طلوعها قليلًا، يكون هذا أولى من نومه بعد الصلاة مباشرة، ولا حرج في ذلك، والحمد لله.","link":"https://binbaz.org.sa/fatwas/1641/حكم-النوم-بعد-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_532.mp3","categories":["الدعوة والدعاة","الآداب والأخلاق"]},{"id":6236,"question":"إذا كان أخت زوجتي الأرملة عندي، ولستُ محرمًا لها، فهل يجوز لي أن أسافر بها مع أهلي في مكان بعيد مثل الطائف مثلًا؟","title":"حكم سفر الرجل بأخت زوجته مع وجود زوجته","answer":"الجواب: إذا كان ليس لها والي غيرك؛ فهي مع أهلك، كالخادمة التي ليس لها والي تكون مع أهلك، تسافر معهم، وليس هناك محرم للضرورة، أما إذا كان لها محرم؛ تكن معه.","link":"https://binbaz.org.sa/fatwas/1739/حكم-سفر-الرجل-باخت-زوجته-مع-وجود-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_582.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6239,"question":"وأيضًا أخ ألح عليّ أن أعرض هذا الخطاب إلى سماحتكم، يقول فيه: نعم أنا تزوجت قبل خمس سنوات، وعندي ولد، وبنت، وحصلت مشاكل بين أبي، وأب زوجتي الأولى، وقد تغربت في السعودية حوالي سنة، ومن ثم ذهبت إلى اليمن، وزوجتي في بيت أبيها، ذهبت إلى والد زوجتي لاسترجاعها إلى بيت أبي، فطلب مني عمي أن أحضر أنا وزوجتي في بيته، لكن قال أبي: أنت تنفق عليها، وتكسوها، وهي تساعد أهلها في البيت، ولا تساعدنا، والآن والدي يخيرني بين أمرين، اختار طريق الجنة، وتتزوج امرأة غيرها، أو أن تذهب إلى طريق آخر، ولا أعرفك، ولا تعرفني، ولا أنا أبوك، تزوجت امرأة أخرى على شور أبي، وطلب مني أبي أن أطلق الأولى، وسألني عمي والد زوجتي الأخيرة: هل طلقت زوجتك الأولى، فقلت له: نعم، وأنا لم أطلقها، بل وعدته، وأنا لا أريد أن أطلق زوجتي الأولى، ولا أن أطلق الثانية، والآن أنا محتار بهذا الوعد الذي وعدت به عمي بطلاق زوجتي الأولى، وللمعلومية فإني متزوج بالثانية، فإني أخذت ابنته، وزوجت أختي من ابنه بدلًا يعني، وكل ما فكرت بالذهاب إلى اليمن؛ يضيق صدري بهذه المشاكل التي أخاف إن ذهبت أن تحصل، ما هو الحل، أرجو عند سماحتكم؟","title":"حكم طاعة الوالد في طلاق الزوجة","answer":"الجواب:  عليك يا أخي أن تجتهد في إرضاء أبيك، والمعاملة معه المعاملة الطيبة؛ لأن بره واجب، والزيارة له مهمة، عليك أن تعتني بوالدك، وتجتهد في إرضائه، ومخاطبته بالتي هي أحسن، وأن توسل بأقاربك الطيبين من أعمام، وغيرهم على أن يقنعوه إذا كانت الزوجة طيبة، إذا كانت الزوجة طيبة، ولا محذور فيها مستقيمة في دينها، فلا تحرص على طلاقها، ولا تعجل في طلاقها إذا كانت مستقيمة. أما إذا كان أبوك انتقدها؛ لأنها فاسدة، فهذه لا ينبغي بقاؤها، تطيع أباك، وتفارقها، أما إن كانت مستقيمة، دينة، معروفة بالصلاة، وغيرها من أمور الدين، ولكن أباك ما وضع الله في قلبه لها المحبة، فلا تعجل، ولا يلزمك الطلاق حينئذ إنما الطاعة في المعروف، الطاعة في المعروف لا فيما يضرك. فعليك أن لا تعجل، وأن تخاطب أباك بالتي هي أحسن، وأن تتوسل إلى إرضائه بأقاربه الطيبين، وجيرانه، ونحو ذلك؛ لعله يقنع، ولعله يرضى؛ حتى تبقى معك الزوجة، وتفوز بمرضاتك والدك، وبره. أما الزوجة الأولى التي قلت لأبيها: إنك طلقتها؛ فيقع بهذا عليها طلقة، إذا قلت: إنك طلقتها؛ فأنت مؤاخذ بإقرارك، إذا قلت طلقتها؛ فهي عليك طلقة، وعليك أن تراجعها إذا كانت في العدة، عليك أن تراجعها، فإن كانت خرجت من العدة؛ لم تحل إلا بنكاح جديد، ومهر جديد، بعد رضاها، وأولياءها بذلك، ولا ينبغي أن تستعجل في الطلاق أبدًا، ينبغي لك أن تعالج الأمور بالتي هي أحسن، بالأسلوب الطيب، وبالتعاون مع جيرانك، وإخوانك، وقراباتك على أبيك حتى يهديه الله. وخذها قاعدة: إذا كان أبوك انتقدها لأجل الدين، وسألت عنها، وعرفت أنها غير دينة، غير مستقيمة؛ فلا خير لك في بقائها، وطاعة الوالد في هذا حق، وإبعادها هو الواجب، والله يرزقك خيرا منها إذا طلقت، وأخلصت وَمَن يَتَّقِ اللَّهَ يَجْعَل لَّهُ مِنْ أَمْرِهِ يُسْراً [الطلاق:4].","link":"https://binbaz.org.sa/fatwas/1751/حكم-طاعة-الوالد-في-طلاق-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_590.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":6247,"question":"إذا كان أخت زوجتي الأرملة عندي، ولستُ محرمًا لها، فهل يجوز لي أن أسافر بها مع أهلي في مكان بعيد مثل الطائف مثلًا؟","title":"حكم سفر الرجل بأخت زوجته مع وجود زوجته","answer":"الجواب: إذا كان ليس لها والي غيرك؛ فهي مع أهلك، كالخادمة التي ليس لها والي تكون مع أهلك، تسافر معهم، وليس هناك محرم للضرورة، أما إذا كان لها محرم؛ تكن معه.","link":"https://binbaz.org.sa/fatwas/1739/حكم-سفر-الرجل-باخت-زوجته-مع-وجود-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_582.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6316,"question":"هناك نوعان من البيع والشراء تشكك الناس اليوم في صحتهما، نرجو توضيح الحكم فيهما، جزاكم الله خير الجزاء، أولاً: ما يجري الآن في سوق الجفرة بالرياض الذي لا يخفى على أحد من الاقتراض بزيادة، ثانيًا: التجارة الحديثة في البورصات الدولية، لاسيما وقد كثر المتعاملون فيها هذه الأيام من خلال البنوك الدولية المفتوحة حديثًا في المملكة.","title":"حكم الاقتراض بزيادة والتعامل في البورصة","answer":"الجواب: أما القرض بزيادة فهذا لا يجوز، كونه يقول: أعطني خمسة، وأعطيك ستة سبعة، أو أقرضني ألفًا، وأعطيك ألفًا، وعشرين، أو ألفًا، وثلاثين، أو ألفًا، وأربعين، كما تفعل البنوك، وغير البنوك، هذا منكر، وهذا من الربا المحرم بلا شك، كونه يقترض مالًا بالزيادة، ولو قليلة، فهذا لا يجوز. وله حيلة، وطريقة شرعية -بحمد الله- تغنيه عن هذا، يشتري إذا كان مضطرًا، يشتري سلعة إلى أجل، ويبيعها على اختياره، يشتري السلعة من زيد، أو عمرو من التاجر، ويقبضها، ويحوزها، ثم يتصرف فيها على مهله، يبيعها على مهلة بالنقد، ويقضي حاجته. وبعض الناس في هذا يغلط أيضًا، يشتري من إنسان ما عنده سلعة، يشتري منه، ثم يروح يشتريها من الثاني، لا، لا تشتري سلعة إلا وهي مملوكة لمن باعها، قد حازها في دكانه، في بيته، ثم يبيع عليك، ثم أنت إذا اشتريتها تحوزها أيضًا، وتنقلها إلى بيتك، أو إلى السوق، ثم تبيعها بعد ذلك على من يسر الله، وتقضي حاجتك، والزيادة التي عليك بالأجل سوف يسهل الله -جل وعلا- النبي ﷺ يقول: من أخذ أموال الناس يريد أداءها؛ أدى الله عنه.  ومن استدان لقصد حاجة للزواج، أو لقضاء دين، أو للإنفاق على عياله سوف يقضي الله عنه إذا صلحت نيته، سوف يقضي الله عنه، ويوفي عنه، والله أباح المداينة  إلى أجل، فلا بأس أن تستدين من إنسان عنده المال، في حوزته المال، تشتري منه المال بحوزته، ثم تنقله، وتقبضه ثم تبيع على مهلك، تبيع المال مرة واحدة، أو أجزاء تبيع، وتقضي حاجاتك، أما أن تقترض من البنك، أوغير البنك بالربا، الألف بألف بخمسمائة ألف ومائة، المائة ألف بمائة ألف وخمسة آلاف زيادة، كل هذا ربا لا يجوز، ولو مائة بمائة ونصف ريال، ما يجوز الزيادة، لا تصلح. وأما البورصة فقد بلغنا عنها أنها بيع في الهواء، بيع لا فيه قبض، ولا فيه شيء، فهو منكر، ومحرم، يتبايعون بالمكاتبات، ويبيع بجميع أنواع المكاتبات، من برقية، ومن لبس، ومن غير ذلك، أموال لا قبضوها، وهذا يبيع، وهذا يبيع، وهي موجودة عند أهلها، هذا منكر، وهي بيوعات باطلة، لا تصلح، لكن حب المال، وكثرة المال بين الناس ما وجدوا له مكانًا إلا هذا التصرف، نسأل الله السلامة!.","link":"https://binbaz.org.sa/fatwas/1873/حكم-الاقتراض-بزيادة-والتعامل-في-البورصة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_662.mp3","categories":["الربا والصرف","البيوع","الآداب والأخلاق"]},{"id":6358,"question":"هل في المنقول شفعة؟ وهل للجار شفعة إذا لم يكن هناك بينهما طريق مشترك؟","title":"الشفعة في المنقول وفي الجار الذي ليس له شركة","answer":"الجواب: هذه... عند العلماء، والشيء المنقول الصحيح فيه شفعة، ولكن فيه خلاف بين العلماء، وحكم القاضي يزيل الخلاف، إذا نظر فيها القاضي، ورأى الشفعة، وعدم الشفعة؛ فهذا إليه يجتهد فيما آتاه الله من العلم، ويعمل بما يترجح عنده من القولين، وأحد القولين: أنه لا شفعة لمنقول، والثاني فيه شفعة. وأما الجار الذي ليس له شركة، فلا شفعة له، يعني جار مجرد الطريق العابر الواسع، فهذا لا شفعة له، أما إن كان بينهما طريق خاص، قد يسد بينهم، وبين الجوارين، أو الثلاثة، والأربعة فبينهما شفعة على تفاصيل عند أهل العلم، يعرفها القضاة، ويحكم فيها القضاة.","link":"https://binbaz.org.sa/fatwas/1916/الشفعة-في-المنقول-وفي-الجار-الذي-ليس-له-شركة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_700.mp3","categories":["الدعوة والدعاة","الآداب والأخلاق"]},{"id":6403,"question":"خطبت امرأة، وطلب مني شرطً أن لا تخرج من هذه البلاد، كيف يكون ذلك إلا كان عندي منها أولاد فيما بعد، هل تكون في بلد، وأنا في بلد أخرى ؟","title":"حكم اشتراط الزوجة السكن في بلد معين","answer":"الجواب: المسلمون على شروطهم، إذا شرط أولياء المرأة عليه مكانًا معينًا، والتزم به؛ فعليه أن يبقى في البلد حتى يرضوا بمغادرته إياها، فإذا شرطوا عليه أن يكون هو وزوجته في الرياض، أو في المدينة، أو في مكة، أو الطائف، والتزم بذلك، أو في القاهرة، أو في دمشق، أو في أي مكان، والتزم بذلك؛ فعليه أن يوفي بالشرط، إلا بوجود أمر قاهر يقهرهما جميعاً؛ خوفًا على دينهما؛ خوفًا على أنفسهما، فهذا عذر شرعي. وأما التساهل بالشروط فلا، المسلمون عند شروطهم، ويقول عمر : \"مقاطع الحقوق عند الشروط\" فينبغي للمؤمن أن يفي بالشروط، ولا يعجل، ولا يخالف هذا الشرط، ولا يكن مثل المنافقين الذين لا يبالون، بل يلتزم بالشروط، ويقف عندها إلا بأمر ضروري، لا حيلة لهم فيه.","link":"https://binbaz.org.sa/fatwas/1966/حكم-اشتراط-الزوجة-السكن-في-بلد-معين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_753.mp3","categories":["الآداب والأخلاق","الشروط والعيوب في النكاح"]},{"id":6405,"question":"ما حكم زواج الشغار مع دفع المهر لكل من المتشاغرين، ولكن مع شرط أنه يزوج كل منهما الآخر، وإذا امتنع طرف منهما؛ فسوف يمتنع الطرف الآخر؟","title":"ما حكم زواج الشغار مع دفع المهر؟","answer":"الجواب: نكاح الشغار هو الذي يسميه الناس البدل، ما يجوز باطل، النبي ﷺ نهى عنه في أحاديث، وقال: الشغار أن يقول الرجل للرجل: زوجني بنتك، وأزوجك بنتي، أو زوجني أختك، وأزوجك أختي هذا هو الشغار المعروف عند الكثير من الناس بالبدل، نكاح البدل، وهو لا يجوز، نهى عن النبي ﷺ لما فيه من النزاع، والخصومات، واشتراط المرأة مهراً لامرأة أخرى. فالمهر عندهم لا قيمة له، وإنما المقصود المرأة بالمرأة، فالمهر لا يحل ذلك، هذا هو الصواب، وفي خلاف بين أهل العلم، بعض أهل العلم قال: مهرها المعتاد يكفي، ولكنه قول غير صحيح، ومخالف للأحاديث الصحيحة، فليس المقصود عدم المهر، المقصود شرط هذه مهراً لهذه، وهذا يفضي إلى إجبار النساء، وظلم النساء، ويفضي إلى النزاع الطويل، وكلما حصل بين هذا وزوجته شيء، حصل بين الآخر كذلك، كل واحدة مربوطة بالأخرى؛ فيحصل من الفساد، والشر ما لا يخفى على أحد، والنبي ﷺ نهى عن الشغار، ولم يقل إلا إذا كان معه مهر، أو إذا كان بمهر. وأما ما يروى في حديث ابن عمر (وليس بينهما مهر) فهذا من كلام أحد الرواة، وليس من كلام النبي ﷺ، بل هو من كلام نافع الذي هو الراوي عن ابن عمر، وإنما الذي قاله النبي ﷺ ما تقدم، وهو قوله: أن يقول الرجل للرجل: زوجني بنتك، وأزوجك بنتي، أو زوجني أختك، وأزوجك أختي هذا هو الذي جاء في الحديث عن أبي هريرة في صحيح مسلم، وثبت في حديث معاوية  أنه رفع إليه أن شخصين من قريش في المدينة تزوجا نكاح شغار، وكانا قد سميا مهرًا بينهما، فكتب معاوية  إلى أمير المدينة، وأمره أن يفرق بينهما، وقال: هذا هو الشغار الذي نهى عنه النبي ﷺ ولم يتلفت إلى ما ذكروا من المهر؛ لأنه غير مقصود، المقصود المرأة بالمرأة، هذا هو مقصود الشغار.","link":"https://binbaz.org.sa/fatwas/2113/ما-حكم-زواج-الشغار-مع-دفع-المهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_765.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6407,"question":"هل يجوز للفتاة أن تشترط على خاطبها عدم التعدد مطلقًا، أو عدم التعدد بدون مبرر على الأقل؟","title":"حكم اشتراط المرأة على الرجل عدم التعدد","answer":"الجواب: ذكر العلماء أن لها ذلك، لها أن تشرط عليه ألا يتزوج عليها؛ فإن تزوج عليها؛ فلها الخيار، ما يحرم عليه الزواج، لكن لها شرطها، النبي -عليه الصلاة والسلام- قال: المسلمون على شروطهم وقال -عليه الصلاة والسلام-: إن أحق الشروط أن يوفى به ما استحللتم به الفروج.  وقال عمر : مقاطع الحقوق عند الشروط، فإذا شرطت عليه أن لا يتزوج عليها؛ فلها شرطها، فإن صبر به، وثبت عليه؛ فهي زوجته، وإن أبى وأراد الزواج؛ فلها الخيار: إن شاءت بقيت، وإلا فسخ نكاحها منه عملًا بالشرط. السؤال: الشرط أليس غير مشروع؛ لأنه يناقض الإباحة التي يبيحها الإسلام؟ الجواب: هي ما حرمت عليه، هي ما تريد يتزوج عليها، فهو إن شاء قبل، وإن شاء رد ذلك، وترك ذلك. السؤال: يعني كأنها.... الجواب: لا، ما يخالف الحديث كل شرط ليس في كتاب فهو باطل هذا حق لها إذا طلبته؛ فلها ذلك، وهو مخير إن شاء قبل، وإن شاء ترك، ما هو ملزم به حتى ولو بعد العقد.","link":"https://binbaz.org.sa/fatwas/2114/حكم-اشتراط-المراة-على-الرجل-عدم-التعدد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_766.mp3","categories":["الآداب والأخلاق","الشروط والعيوب في النكاح"]},{"id":6410,"question":"هل يقع الطلاق البدعي؟ وهل الطلاق بالثلاث محرم، مثل أن يقول: أنت طالق، أنت طالق، أنت طالق في آن واحد؟ وهل هذا من الطلاق البدعي؟","title":"حكم وقوع الطلاق البدعي","answer":"الجواب: الطلاق البدعي مثل ما سمعت، الطلاق البدعي إذا كان باللفظ أنت مطلقة بالثلاث، أو فلانة مطلقة بالثلاث، لا يقع إلا وحدة على الراجح؛ لحديث ابن عباس أن الطلاق كان في عهد النبي ﷺ طلاق الثلاث واحدة، وهكذا في عهد الصديق، وفي أول خلافة عمر، ثم أمضاه عمر. فالصحيح: أنه لا يقع به إلا واحدة، يرد إلى السنة، أما إذا كررها، قال: طالق، ثم طالق، ثم طالق، أو أنت طالق، أنت طالق، أنت طالق، وأراد إيقاع الثلاث، أو ما أراد تأكيدًا، ولا إفهامًا، بل أطلقها هكذا: أنت طالق، أنت طالق، أنت طالق، يقع الطلاق، يقع الطلاق ثلاثًا.  أما في الحيض، والنفاس فهذا محل خلاف بين أهل العلم، فالقول بعدم وقوعه قوي جدًا؛ لأنه خالف أمر الله؛ فلا يقع، لكن الجمهور، والأكثر من أهل العلم على إيقاعه، وظاهر السنة، وظاهر القواعد الشرعية أنه لا يقع، وقد أفتى به جماعة من التابعين، وأفتى به ابن عمر نفسه  الذي وقعت عليه الحادثة، أفتى بأنه لا يقع؛ لأنه خالف السنة، خالف الشرع. السؤال: الطلاق البدعي لا يقع؟ الجواب: الذي في الحيض، والنفاس عند بعض أهل العلم، أما طلاق الثلاث جميعًا، فهذا يقع منه واحدة إذا كان بلفظ واحد أنت طالقة بالثلاث، أو مطلقة بالثلاث يقع واحدة. أما إذا كرره قال: أنت طالق، أنت طالق، أنت طالق، ولم ينو تأكيدًا، ولا إفهامًا، بل نوى الثلاث جميعًا، أو ما نوى شيئًا، بل كرره، وهكذا؛ يقع الثلاث. أو قال: أنت طالق، ثم طالق، ثم طالق، أو طلقها اليوم، ثم طلقها غدًا، ثم طلقها بعد غد في العدة؛ لحق الطلاق بها.","link":"https://binbaz.org.sa/fatwas/2125/حكم-وقوع-الطلاق-البدعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_773.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":6411,"question":"إذا تبين بعد الزواج أن أحد الزوجين فيه عيب، أو نقص جنسي، فما هو التعويض للزوج الآخر في هذه الحالة؟","title":"حكم فسخ عقد الزواج لوجود العيب","answer":"الجواب: هذا إذا وجدت عيبًا فيه، أو وجد فيها عيبًا إن اصطلحا، وإلا المحكمة تحكم بينهما، وهذا يحتاج إلى تفصيل، إذا وجدت المرأة في زوجها عيبًا كبرص داخلي، أو تعطل في النكاح، أو ما أشبه ذلك، أو وجد بها عيبًا كبرص داخلي، أو مرضي، شيء داخلي يعيبها؛ فإن اصطلحا فيما بينهما، ورضي كل واحد بالآخر، أو فارقها بنفسه، أو أعطته شيئًا، وفارقها، فالحمد لله، وانتهى الأمر. فأما إن أدى الأمر إلى النزاع، والخصومة، فهذا إلى المحاكم.","link":"https://binbaz.org.sa/fatwas/2117/حكم-فسخ-عقد-الزواج-لوجود-العيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_769.mp3","categories":["الآداب والأخلاق","الشروط والعيوب في النكاح"]},{"id":6412,"question":"... يكون بيد المرأة...؟","title":"حكم جعل العصمة بيد المرأة","answer":"الجواب: ما يصلح هذا، ما يكون بيد المرأة، العصمة بيد الزوج، فإذا أعطاها؛ يكون شرطًا باطلًا، إذا عقد على هذا؛ يكون شرطًا باطلاً، أما الوكالة إذا وكلها في بعض الأحيان؛ فما في بأس.","link":"https://binbaz.org.sa/fatwas/2119/حكم-جعل-العصمة-بيد-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_770.mp3","categories":["الآداب والأخلاق","الشروط والعيوب في النكاح"]},{"id":6413,"question":"ما حكم زواج الشغار مع دفع المهر لكل من المتشاغرين، ولكن مع شرط أنه يزوج كل منهما الآخر، وإذا امتنع طرف منهما؛ فسوف يمتنع الطرف الآخر؟","title":"ما حكم زواج الشغار مع دفع المهر؟","answer":"الجواب: نكاح الشغار هو الذي يسميه الناس البدل، ما يجوز باطل، النبي ﷺ نهى عنه في أحاديث، وقال: الشغار أن يقول الرجل للرجل: زوجني بنتك، وأزوجك بنتي، أو زوجني أختك، وأزوجك أختي هذا هو الشغار المعروف عند الكثير من الناس بالبدل، نكاح البدل، وهو لا يجوز، نهى عن النبي ﷺ لما فيه من النزاع، والخصومات، واشتراط المرأة مهراً لامرأة أخرى. فالمهر عندهم لا قيمة له، وإنما المقصود المرأة بالمرأة، فالمهر لا يحل ذلك، هذا هو الصواب، وفي خلاف بين أهل العلم، بعض أهل العلم قال: مهرها المعتاد يكفي، ولكنه قول غير صحيح، ومخالف للأحاديث الصحيحة، فليس المقصود عدم المهر، المقصود شرط هذه مهراً لهذه، وهذا يفضي إلى إجبار النساء، وظلم النساء، ويفضي إلى النزاع الطويل، وكلما حصل بين هذا وزوجته شيء، حصل بين الآخر كذلك، كل واحدة مربوطة بالأخرى؛ فيحصل من الفساد، والشر ما لا يخفى على أحد، والنبي ﷺ نهى عن الشغار، ولم يقل إلا إذا كان معه مهر، أو إذا كان بمهر. وأما ما يروى في حديث ابن عمر (وليس بينهما مهر) فهذا من كلام أحد الرواة، وليس من كلام النبي ﷺ، بل هو من كلام نافع الذي هو الراوي عن ابن عمر، وإنما الذي قاله النبي ﷺ ما تقدم، وهو قوله: أن يقول الرجل للرجل: زوجني بنتك، وأزوجك بنتي، أو زوجني أختك، وأزوجك أختي هذا هو الذي جاء في الحديث عن أبي هريرة في صحيح مسلم، وثبت في حديث معاوية  أنه رفع إليه أن شخصين من قريش في المدينة تزوجا نكاح شغار، وكانا قد سميا مهرًا بينهما، فكتب معاوية  إلى أمير المدينة، وأمره أن يفرق بينهما، وقال: هذا هو الشغار الذي نهى عنه النبي ﷺ ولم يتلفت إلى ما ذكروا من المهر؛ لأنه غير مقصود، المقصود المرأة بالمرأة، هذا هو مقصود الشغار.","link":"https://binbaz.org.sa/fatwas/2113/ما-حكم-زواج-الشغار-مع-دفع-المهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_765.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6414,"question":"هل يقع الطلاق بغير ألفاظه مثل أن يقول الرجل: اذهبي إلى أهلك، وينوي بذلك الطلاق؟","title":"حكم الطلاق بالكنايات","answer":"الجواب: نعم، إذا أوقعه بالكنايات وقع، قال: الحقي بأهلك، أو روحي لأهلك، أو اذهبي إلى أهلك ناوياً الطلاق؛ يقع واحدة.","link":"https://binbaz.org.sa/fatwas/2126/حكم-الطلاق-بالكنايات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_774.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":6421,"question":"هل طلاق الذي لا يحسن التصرف لكبر يعتبر طلاقًا، وهذه المرأة جلست معه أكثر من ثلاثين عامًا، لم ترزق منه بولد، وتريد الطلاق فهل عليها إثم، أم لا؟ والله الموفق.","title":"حكم طلاق من لا يحسن التصرف","answer":"الجواب: إذا طلقها وهو يعلم الطلاق، ما خرف، ولا زال عقله؛ يقع الطلاق، إذا طلقها وعقله معه يقع، أما هي فإن صبرت عليه؛ فهو أولى، تصبر عليه أحسن، وأولى، أما إن كان هناك عليها مشقة؛ لأنه عنيف عليها، أو يؤذيها، أو أسباب أخرى أوجبت ذلك؛ فلا حرج عليها في طلب الطلاق؛ لأن الرسول ﷺ قال: من غير ما بأس أما هذه قد وجدت بأسًا، قد وجدت ضررًا، فإن وجدت ضررًا، وإيذاء؛ فلا مانع من طلبها الطلاق، وإن صبرت عليه، وأحسنت فيه في كبره؛ فلها أجر عظيم.","link":"https://binbaz.org.sa/fatwas/2132/حكم-طلاق-من-لا-يحسن-التصرف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_780.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":6437,"question":"ما رأي سماحتكم في القائمة التي يكتبها أهل الزوجة على العريس، وتكون بالعكس الجهاز حتى إذا طلقها كان لها الحق في كل هذا العكس، هل هذا صحيح؟","title":"وجوب الوفاء بالشروط التي بين الزوجين","answer":"الجواب:\n\nلا بأس فيما يصطلحان عليه، لكن ينبغي لهما عدم التشديد، وينبغي أن يرفق بالزوج حتى لا ينفروا الناس من الخطبة، ومن بناتهم، ينبغي لأهل المرأة ألا يشددوا في هذه المسائل، وكما سمعتم في الندوة أن الخطباء، والنصحاء قد جدوا في هذا الأمر، ولكن قلَّ المستجيب. \n\nفالمشروع للمؤمن ألا يتكلف في المهر، ولا في الوليمة، لا من جهة الزوج، ولا من جهة الزوجة، بل ينبغي لأهل الزوج، والزوجة جميعاً أن يتعاونوا على الاقتصاد، وعدم التكلف؛ حتى يفسح المجال للناس في الزواج، وحتى يتيسر للشباب الزواج، وللفتيات الزواج. \n\nأما مع التكلف في المهور، والتكلف في الولائم فكل هذه عقبات -كما تقدم غير مرة- أن هذه عقبات ينبغي أن تزال، ينبغي للمؤمنين أن يتبصروا، وأن يعرفوا مصيبتهم، وأن يعرفوا داءهم؛ حتى يبصروا دواءهم.\n\nولا شك أن من الأدواء التكلف في المهور، والتكلف في الولائم، والتكلف في إيجاد المغنيات، والمطربات التي تضر، ولا تنفع، ونعوذ بالله، فينبغي في هذا للمؤمنين، والمؤمنات التعاون، على الزوج وأهله، والزوجة وأهلها، والجيران، والأقارب يتعاونون في كل شيء، من تخفيف المهور، وعدم التكلف في المهور، ومن تخفيف الولائم، وأن تكون وليمة مناسبة خفيفة للزوجين، وأقاربهما من غير إسراف؛ حتى لا يتكلف هؤلاء، ولا هؤلاء.\n\nوأما إذا اتفقوا على قائمة يعطيها كذا وكذا، عشرة آلاف ريال، خمسة آلاف ريال، غرفة نوم، حلية كذا وكذا بينهما متفق عليه، ما في شيء اتفقا على هذا؛ فالمسلمون على شروطهم، والنبي -عليه الصلاة والسلام- قال: إن أحق الشروط أن يوفى به ما استحللتم به الفروج متفق على صحته. أحق الشروط ما استحل به الزوج الفرج، فإذا شرط لها شيئًا، شرط لها سلعة معينة، شرط لها دراهم معلومة، وتم الزواج على ذلك، وجب عليه أن يوفي، وليس له التأخر عن ذلك؛ لأنه  استحل فرجها بهذا الأمر.","link":"https://binbaz.org.sa/fatwas/2157/وجوب-الوفاء-بالشروط-التي-بين-الزوجين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_798.mp3","categories":["الآداب والأخلاق","الشروط والعيوب في النكاح"]},{"id":6450,"question":"ما رأي سماحتكم في القائمة التي يكتبها أهل الزوجة على العريس، وتكون بالعكس الجهاز حتى إذا طلقها كان لها الحق في كل هذا العكس، هل هذا صحيح؟","title":"وجوب الوفاء بالشروط التي بين الزوجين","answer":"الجواب:\n\nلا بأس فيما يصطلحان عليه، لكن ينبغي لهما عدم التشديد، وينبغي أن يرفق بالزوج حتى لا ينفروا الناس من الخطبة، ومن بناتهم، ينبغي لأهل المرأة ألا يشددوا في هذه المسائل، وكما سمعتم في الندوة أن الخطباء، والنصحاء قد جدوا في هذا الأمر، ولكن قلَّ المستجيب. \n\nفالمشروع للمؤمن ألا يتكلف في المهر، ولا في الوليمة، لا من جهة الزوج، ولا من جهة الزوجة، بل ينبغي لأهل الزوج، والزوجة جميعاً أن يتعاونوا على الاقتصاد، وعدم التكلف؛ حتى يفسح المجال للناس في الزواج، وحتى يتيسر للشباب الزواج، وللفتيات الزواج. \n\nأما مع التكلف في المهور، والتكلف في الولائم فكل هذه عقبات -كما تقدم غير مرة- أن هذه عقبات ينبغي أن تزال، ينبغي للمؤمنين أن يتبصروا، وأن يعرفوا مصيبتهم، وأن يعرفوا داءهم؛ حتى يبصروا دواءهم.\n\nولا شك أن من الأدواء التكلف في المهور، والتكلف في الولائم، والتكلف في إيجاد المغنيات، والمطربات التي تضر، ولا تنفع، ونعوذ بالله، فينبغي في هذا للمؤمنين، والمؤمنات التعاون، على الزوج وأهله، والزوجة وأهلها، والجيران، والأقارب يتعاونون في كل شيء، من تخفيف المهور، وعدم التكلف في المهور، ومن تخفيف الولائم، وأن تكون وليمة مناسبة خفيفة للزوجين، وأقاربهما من غير إسراف؛ حتى لا يتكلف هؤلاء، ولا هؤلاء.\n\nوأما إذا اتفقوا على قائمة يعطيها كذا وكذا، عشرة آلاف ريال، خمسة آلاف ريال، غرفة نوم، حلية كذا وكذا بينهما متفق عليه، ما في شيء اتفقا على هذا؛ فالمسلمون على شروطهم، والنبي -عليه الصلاة والسلام- قال: إن أحق الشروط أن يوفى به ما استحللتم به الفروج متفق على صحته. أحق الشروط ما استحل به الزوج الفرج، فإذا شرط لها شيئًا، شرط لها سلعة معينة، شرط لها دراهم معلومة، وتم الزواج على ذلك، وجب عليه أن يوفي، وليس له التأخر عن ذلك؛ لأنه  استحل فرجها بهذا الأمر.","link":"https://binbaz.org.sa/fatwas/2157/وجوب-الوفاء-بالشروط-التي-بين-الزوجين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_798.mp3","categories":["الآداب والأخلاق","الشروط والعيوب في النكاح"]},{"id":6482,"question":"أحد الإخوة يسأل أن امرأة حملت من سفاح، وجاءت بمولود منذ أربع سنوات، واعترفت لزوجها، وعرف الحقيقة وهو الآن لا يدري هل يطلقها، أم يمسكها؟ وليس لها أحد إلا هو، واعترفت وهي تصلي، وتصوم، واعترفت بغلطتها، فما رأي سماحتكم؟","title":"حكم إبقاء الزوجة إذا زنت وتابت","answer":"الجواب: عليها أن تحسن إلى هذا الطفل، وتربيه لعل الله يهديه، وينفع به بعد ذلك، والإثم على من فعل الزنا لا عليه، وأما الإثم على من فعل الزنا من الزاني، والمرأة عليهما هما أصحاب الإثم -نسأل الله السلامة- والطفل لا حرج عليها بتربيته، والإحسان إليه، والقيام بحقه حتى ينشئه الله في الإسلام.  والمرأة إذا تابت، ورجعت إلى الله -جل وعلا- فزوجها يمسكها كونها زنت، فلا يحرمها عليه، ولكن عليها أن تتوب إلى الله توبة صادقة، وعليها أن ترجع عن هذا الباطل، وأن تتحفظ بعد ذلك، وعلى زوجها أن يلاحظها، وأن يعتني بها، وأن يحرص على أسباب حفظها، وسلامتها، ونجاتها من هذا الشيء، ولا حرج عليه في بقائها، فليس زناها يحرمها عليه إذا تابت، واستقامت. أما إذا كان يتهمها، ويظن أنها تخونه؛ فلا خير في بقائها عنده، لكن ما دام أظهرت التوبة، وظن بها الظن الحسن، وظهر منها ما يدل على رجوعها في الصواب، والحق، والهدى؛فلا بأس أن يستر عليها، ولا يبين هذا الشيء، بل يكون بينه وبينها فقط، وأن يحسن إليها بالنصيحة، والتوجيه، والإرشاد، والتحذير إلى العودة إلى ما حرم الله عليها، والله يتوب على التائبين .","link":"https://binbaz.org.sa/fatwas/2227/حكم-ابقاء-الزوجة-اذا-زنت-وتابت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_847.mp3","categories":["الحقوق الزوجية","الآداب والأخلاق"]},{"id":6497,"question":"أحد الإخوة يسأل أن امرأة حملت من سفاح، وجاءت بمولود منذ أربع سنوات، واعترفت لزوجها، وعرف الحقيقة وهو الآن لا يدري هل يطلقها، أم يمسكها؟ وليس لها أحد إلا هو، واعترفت وهي تصلي، وتصوم، واعترفت بغلطتها، فما رأي سماحتكم؟","title":"حكم إبقاء الزوجة إذا زنت وتابت","answer":"الجواب: عليها أن تحسن إلى هذا الطفل، وتربيه لعل الله يهديه، وينفع به بعد ذلك، والإثم على من فعل الزنا لا عليه، وأما الإثم على من فعل الزنا من الزاني، والمرأة عليهما هما أصحاب الإثم -نسأل الله السلامة- والطفل لا حرج عليها بتربيته، والإحسان إليه، والقيام بحقه حتى ينشئه الله في الإسلام.  والمرأة إذا تابت، ورجعت إلى الله -جل وعلا- فزوجها يمسكها كونها زنت، فلا يحرمها عليه، ولكن عليها أن تتوب إلى الله توبة صادقة، وعليها أن ترجع عن هذا الباطل، وأن تتحفظ بعد ذلك، وعلى زوجها أن يلاحظها، وأن يعتني بها، وأن يحرص على أسباب حفظها، وسلامتها، ونجاتها من هذا الشيء، ولا حرج عليه في بقائها، فليس زناها يحرمها عليه إذا تابت، واستقامت. أما إذا كان يتهمها، ويظن أنها تخونه؛ فلا خير في بقائها عنده، لكن ما دام أظهرت التوبة، وظن بها الظن الحسن، وظهر منها ما يدل على رجوعها في الصواب، والحق، والهدى؛فلا بأس أن يستر عليها، ولا يبين هذا الشيء، بل يكون بينه وبينها فقط، وأن يحسن إليها بالنصيحة، والتوجيه، والإرشاد، والتحذير إلى العودة إلى ما حرم الله عليها، والله يتوب على التائبين .","link":"https://binbaz.org.sa/fatwas/2227/حكم-ابقاء-الزوجة-اذا-زنت-وتابت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_847.mp3","categories":["الحقوق الزوجية","الآداب والأخلاق"]},{"id":6527,"question":"هل يدخل سفر المرأة من بلدها وحدها إلى زوجها في بلد عمله، والسفر حوالي أربع ساعات بالطائرة، هل يدخل ذلك تحت النهي عن سفر المرأة بغير محرم؟","title":"حكم سفر المرأة في الطائرة بدون محرم","answer":"الجواب: نعم يدخل السفر بالطائرة، أو بالقطار، أو بالسيارة كله داخل، النبي ﷺ قال: لا تسافر المرأة إلا مع ذي محرم الرسول ﷺ ما هو يخبر عن نفسه، عن شرع الله، الرسول يخبر عن شرع الله، والله يعلم ما يكون في آخر الزمان من الطائرات، والقطارات، والسيارات، وغير ذلك، يعلم كل شيء  والشرع عام، الله شرع لنا شرائع إلى يوم القيامة، ما هي خاصة بوقت النبي ﷺ بل هي عامة في وقته، وبعد وقته إلى يومنا هذا، وإلى ما بعد ذلك إلى يوم القيامة، شرع مستمر، فليس شرعًا خاصًا بيوم دون يوم، أو سنة دون سنة، أو دولة دون دولة، هو شرع لجمع، فليس للمرأة أن تسافر إلا مع ذي محرم سواء كان سفرها بالطائرات، أو بالسيارات، أو بالقطارات، أو بغير ذلك. السؤال: معها ولد صار عمره سبع سنين محرم لها؟ الجواب: ليس محرمها، المحرم البالغ الرجل البالغ الذي خمسة عشر سنة، فأكثر. السؤال: كثير من النساء يستقبلهن أزواجهن وأهلهم في المطارات، يجوز هذا؟ الجواب: ما هو بدليل، هذا ما يجوز، هذا غلط، تساهل. السؤال: والمضيفات اللاتي يسافرن في الطائرة دائماً؟ الجواب: المضيفات، وغير المضيفات. السؤال: المضيفات اللاتي يشتغلن في الطائرة؟ الجواب: الحكم واحد، الحكم واحد. السؤال: .. صحبة نساء؟ الجواب: ولو بصحبة نساء، ما عليه دليل، حتى الحج ما يجوز، حتى الحج ليس لها حج إلا إذا كان معها محرم، وإلا فهي معذورة حتى يكون لها محرم في الحج، وفي غير الحج، هذا الصواب من أقوال العلماء.","link":"https://binbaz.org.sa/fatwas/2385/حكم-سفر-المراة-في-الطاىرة-بدون-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_918.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6560,"question":"لي أخ من أبي، وله أخت من أمه، وقد تزوجها عمي، فهل يجوز لي مصافحتها؟","title":"حكم مصافحة الأخ أخت أخيه من أمه","answer":"الجواب:\n\nلا، أجنبية عنك، أخت أخيك من أمك لا، ما هي بأخت لك، أجنبية، وزوجة عمك أجنبية، ولكن تسلم عليها مع الحجاب، أما المصافحة فلا، لا بد من الحجاب، وعدم المصافحة، إنما تسلم عليها بالكلام، كيف حالك يا فلانة؟ كيف أولادك؟ كيف أبيك؟ ما في بأس.\n\nأما المصافحة لا، إلا مع المحرم، مع أختك، مع عمتك، خالتك، أمك ما يخالف، زوجة أبيك، زوجة جدك، زوجة ولدك لا بأس، أما زوجة عمك، وزوجة خالك لا، أجنبية.","link":"https://binbaz.org.sa/fatwas/2419/حكم-مصافحة-الاخ-اخت-اخيه-من-امه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_946.mp3","categories":["الآداب والأخلاق","المحرمات من النساء"]},{"id":6599,"question":"يا شيخ، المرأة عندما صافحت حطت البشت، وخفت أنهم يقولون: موسوسًا .. ؟","title":"حكم مصافحة المرأة الكبيرة","answer":"السؤال: لا تصافح أبدًا .. لا تصافح النساء أبدًا، إلا محارمك، إخواتك، وعماتك.. السؤال: حتى ولو عجوز..؟ الجواب: ولو عجوز، ولو عجوز.","link":"https://binbaz.org.sa/fatwas/2444/حكم-مصافحة-المراة-الكبيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_971.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6625,"question":"هل يجوز للأخ المسلم عند خطبته لفتاة مسلمة أن يجلس معها ليعلمها القرآن، ويتعرف على أخلاقها قبل العقد بها، والارتباط بها ؟","title":"حكم مجالسة المخطوبة للتعرف على أخلاقها","answer":"الجواب: له أن ينظر إليها فقط، أما يجلس معها، ويخلو بها ليس له ذلك، لا للقرآن، ولا لغيره، لكن ينظر إليها بحضرة أبيها، أو أخيها، أو غيرهم، لا يخلو بها، وينظر إليها؛ لعل الله يأدم بينهما؛ لعلها توافقه، ثم بعد هذا يعقد عليها إذا ناسبته، أما أنه يخلو بها، أو يجلس معها للتعليم، فالشيطان لا يؤمن أن ينزغ بينهما. السؤال: مرة، أو مرات؟ الجواب: النظرة الواحدة الكافية، وإذا مكثت ما رآها النظر الكافي، لا بأس أن ينظر مرة أخرى؛ ليتحقق عنها ما يريد.","link":"https://binbaz.org.sa/fatwas/2482/حكم-مجالسة-المخطوبة-للتعرف-على-اخلاقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_5739.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":6626,"question":"هل الماء النجس إذا كرر وصفي بطرق علمية، هل هو طاهر، علمًا أن أصله نجس، وأن رائحته، ولونه، وطعمه كالماء الطبيعي الطاهر تمامًا؟","title":"حكم الماء النجس إذا صفي بطرق علمية","answer":"الجواب: إذا كان كثيرًا، ونقي بما فيه طهر، فإذا كان مثلًا غفيرًا كثيرًا، أصابته نجاسة غير بها طعمه، أو لونه، أو ريحه، ثم زالت زال التغير، وعاد إلى صفائه، وطيب رائحته، وطعمه؛ طهر بذلك. أما القليل الذي فيه النجاسة، ذهب ريحها؛ ما يضر القليل، لكن إذا كان كثيرًا إذا زال بالمعالجة، أو بغير المعالجة؛ زال الريح، والطعم، واللون؛ فإن الماء يعود طهورًا إذا كان كثيرًا، قلتين فأكثر، أما ما دون القلتين؛ فهو محل خلاف، والقليل جدًا هذا لا يطهر بكل حال، القليل النجاسة لا تزال فيه، ولو ذهب ريحها، أو طعمها، أو لونها، ولهذا أمر النبي ﷺ بإراقة الإناء الذي شرب منه الكلب؛ لأن في الغالب يتغير الأواني، ماؤها قليل، ولهذا أمر بإراقته.","link":"https://binbaz.org.sa/fatwas/2476/حكم-الماء-النجس-اذا-صفي-بطرق-علمية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1003.mp3","categories":["المياه","الآداب والأخلاق"]},{"id":6640,"question":"هل يجوز للأخ المسلم عند خطبته لفتاة مسلمة أن يجلس معها ليعلمها القرآن، ويتعرف على أخلاقها قبل العقد بها، والارتباط بها ؟","title":"حكم مجالسة المخطوبة للتعرف على أخلاقها","answer":"الجواب: له أن ينظر إليها فقط، أما يجلس معها، ويخلو بها ليس له ذلك، لا للقرآن، ولا لغيره، لكن ينظر إليها بحضرة أبيها، أو أخيها، أو غيرهم، لا يخلو بها، وينظر إليها؛ لعل الله يأدم بينهما؛ لعلها توافقه، ثم بعد هذا يعقد عليها إذا ناسبته، أما أنه يخلو بها، أو يجلس معها للتعليم، فالشيطان لا يؤمن أن ينزغ بينهما. السؤال: مرة، أو مرات؟ الجواب: النظرة الواحدة الكافية، وإذا مكثت ما رآها النظر الكافي، لا بأس أن ينظر مرة أخرى؛ ليتحقق عنها ما يريد.","link":"https://binbaz.org.sa/fatwas/2482/حكم-مجالسة-المخطوبة-للتعرف-على-اخلاقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_5739.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":6641,"question":"هل الماء النجس إذا كرر وصفي بطرق علمية، هل هو طاهر، علمًا أن أصله نجس، وأن رائحته، ولونه، وطعمه كالماء الطبيعي الطاهر تمامًا؟","title":"حكم الماء النجس إذا صفي بطرق علمية","answer":"الجواب: إذا كان كثيرًا، ونقي بما فيه طهر، فإذا كان مثلًا غفيرًا كثيرًا، أصابته نجاسة غير بها طعمه، أو لونه، أو ريحه، ثم زالت زال التغير، وعاد إلى صفائه، وطيب رائحته، وطعمه؛ طهر بذلك. أما القليل الذي فيه النجاسة، ذهب ريحها؛ ما يضر القليل، لكن إذا كان كثيرًا إذا زال بالمعالجة، أو بغير المعالجة؛ زال الريح، والطعم، واللون؛ فإن الماء يعود طهورًا إذا كان كثيرًا، قلتين فأكثر، أما ما دون القلتين؛ فهو محل خلاف، والقليل جدًا هذا لا يطهر بكل حال، القليل النجاسة لا تزال فيه، ولو ذهب ريحها، أو طعمها، أو لونها، ولهذا أمر النبي ﷺ بإراقة الإناء الذي شرب منه الكلب؛ لأن في الغالب يتغير الأواني، ماؤها قليل، ولهذا أمر بإراقته.","link":"https://binbaz.org.sa/fatwas/2476/حكم-الماء-النجس-اذا-صفي-بطرق-علمية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1003.mp3","categories":["المياه","الآداب والأخلاق"]},{"id":6678,"question":"نذكر أمرين يحدثان في هذا المسجد يوم الجمعة خاصة: يحجز المكان الذي خلف الإمام لما يتسع لعدد من الناس، وإذا أحد جاء ليجلس فيه يمنع، ويقال: هذا محل شيخ، ثم يأتي من يجلس فيه بعد فترة، وإذا أتي بجنازة فإن من يأتي بها يكونون قبل الصف الأول، صف صغير بعد الإمام إلى اليسار، ولكن ليس كاملًا، آمل الإفادة حول ذلك، وهل لنا أن نجلس في المكان الخالي، حتى وإن غضب بعضهم؟","title":"حكم حجز الأماكن في المسجد","answer":"الجواب: الحمد لله وصلى الله وسلم على رسول الله، وعلى آله، وأصحابه، ومن اهتدى بهداه، أما بعد: فالمسجد بيت الله، أعد لعبادته وطاعته من الصلاة، وغيرها، فلا يجوز لأحد أن يتحجر ما خلف الإمام، ولا ما عن يمينه، ولا ما عن شماله، فهو لمن سبق، الصف الأول لمن سبق، ولهذا قال -عليه الصلاة والسلام-: لو يعلم الناس ما في النداء، والصف الأول، ثم لم يجدوا إلا أن يستهموا عليه؛ لاستهموا يعني لاقترعوا للمسابقة إليه، والحرص على أن يتقدموا.  فحجزه أمر لا يجوز، وغصب للمكان، ولا حق لمن غصبه، فالسابق أولى منه، وأحق منه في المكث فيه، والتقدم إليه، والواجب التنبيه على هؤلاء، وأن يعلموا أن هذا لا يجوز، وأن حجز الصف الأول، أو وسط الصف الأول لمن يأتي بعد ذلك لا يجوز. والواجب أن تزال هذه الأشياء، وألا تبقى في مكانها، بل يكون الصف لمن سبق، وكنا نعلم هذا من قديم، كان أهل الحل، والعقد، والآمرون بالمعروف، والناهون عن المنكر يلاحظون هذا، ويزيلون ما يضعه الناس في الصف الأول حتى يتقدم الناس بأنفسهم، لا بالخرق، ولا بغير الخرق، ولا بالسجادات، ولكن يتقدمون بأنفسهم إلى الصف الأول، فهو لمن سبق بنفسه لا لمن سبق بالسجادة، أو النعلين، أو غير هذا لا، هذا هو الحق، هذا هو الصواب، فالسابق أولى بالمكان. نعم إذا كان الإنسان تقدم في الصف الأول، ثم عرض له عارض، فقام يتوضأ فهو أحق بمكانه، حتى ولو ما جعل فيه شيئًا، هو أحق بمكانه أن يرجع إليه إذا عرض له عارض، فقام يتوضأ، أو لغير ذلك من العوارض التي تعرض، وجاء للإقامة في المسجد، والجلوس، والانتظار، فهذا ينبغي أن يعرف، ويعرفه جيرانه، ويقولون لمن جاء هذا المكان: له صاحب، قام لعارض، وهو أحق به، أما إنسان يتقدم بالسجادة، أو غيرها، ويبقى في بيته، أو يبقى في دكانه، هذا غلط، هذا لا يجوز. وأهل الجنازة إذا كان لهم في مكان في الصف الأول يدخلون في الصف الأول، أو في الثاني، وإذا كان ما لهم مكان يصفون خلف الإمام، لا معه، الإمام لا يكون معه أحد، يكونون خلفه، ولو كان صفًا قاصرًا، يكونون خلف الإمام، والجنائز يتسامح في صفوفها، ولهذا قال بعض الصحابة: إنه لا بأس أن تكون الصفوف ثلاثة، ولو كانت غير تامة. فالمقصود: أنه إذا تيسر أن يكونوا في الصف أن يدخلوا في الصف؛ كان الأولى، والأفضل، سواء كان في الصف الأول، أو من ورائه الصف الثاني، أو الثالث إذا تيسر لهم مكان، إذا صفوا خلف الإمام صفًا، ولو كان غير كثير لا بأس.","link":"https://binbaz.org.sa/fatwas/2537/حكم-حجز-الاماكن-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1032.mp3","categories":["المساجد ومواضع السجود","الآداب والأخلاق"]},{"id":6691,"question":"إذا ولشت المرأة عن الرجل في عيب من العيوب، علمًا بأنه لم يكتشف هذا العيب إلا بعد الدخول بها، فهل هذا يبرر إنهاء العلاقة؟","title":"حكم من اكتشف عيباً في زوجته بعد الدخول بها","answer":"الجواب: هذا بينه وبينها، إن شاء فارقها، وإن شاء اتصل بالمحكمة، والمحكمة تنظر في الأمر، هذا بينه، وبين المرأة، إذا عرف عيبًا فليس كل عيب يوجب الفسخ، وليس كل عيب يقتضي الترافع إلى المحكمة، بل هذا بين الزوج، والزوجة، إن رأى عيبًا يمكن الصبر عليه؛ صبر، وإن رأى عيبًا يوجب الفسخ؛ سأل أهل العلم، وسأل المحكمة، وعرض عليها الأمر، وإذا أحسن، وطلق من غير شيء، وإلا اتفق معهم على شيء يرضونه به، وطلق، هذه أمور داخلية بين الرجل، وأهل المرأة، والمرأة.","link":"https://binbaz.org.sa/fatwas/2572/حكم-من-اكتشف-عيبا-في-زوجته-بعد-الدخول-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1067.mp3","categories":["الآداب والأخلاق","الشروط والعيوب في النكاح"]},{"id":6707,"question":"تقوم إذاعة القرآن الكريم بمكة المكرمة، وذلك بين السادسة إلى الثامنة مساء بأن تقوم نساء، وبنات بتلاوة القرآن الكريم في برنامج ناشئ في رحاب القرآن، هل هذا الفعل جائز، وخصوصًا أن الرسول -عليه الصلاة والسلام- أمر النساء بأن لا يرفعن أصواتهن بالتلبية، كيف بين نوفق هذا وذاك؟","title":"حكم صوت المرأة في برامج تلاوة القرآن","answer":"الجواب:\n\n... وإنما هو من كلام أهل العلم، أهل العلم رأوا أن الأفضل خفض أصواتهن بالتلبية، ونحو ذلك؛ لأنه قد يفتن بعض الناس ببعض الأصوات، وإلا أصواتهن ليست عورة، في حاجاتهن، فقد كن يخاطبن النبي ﷺ والنساء يسمعون، ويسألون عن حاجاتهم، وصوتها مطلقًا ليس بعورة، وإنما العورة خضوع صوتها -يعني الخضوع بصوتها- والترخيم لصوتها، لقوله -جل وعلا-: فَلَا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ [الأحزاب:32].\n\nأما جنس الصوت للمرأة فليس بعورة، فلها أن تتكلم مع الرجال، تسأل عن حاجاتها، وتبيع، وتشتري .. لكن كونها تخضع بالقول بغنج، وشيء يطمع بها ضعفاء الإيمان، هذا هو المنكر، ولكن هذا برنامج ناشئ في القرآن ننظر فيه -إن شاء الله- ونعمل ما يلزم إن شاء الله.","link":"https://binbaz.org.sa/fatwas/2578/حكم-صوت-المراة-في-برامج-تلاوة-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1074.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6716,"question":"هل يجوز لولي البنت أن يأخذ من مهر ابنته شيئًا من المال وهي لا تعلم؟","title":"حكم أخذ الأب من مهر ابنته دون علمها","answer":"الجواب:   يجوز لأبيها أن يأخذ من مالها ما لا يضرها، لقوله ﷺ: إن أطيب ما أخذتم من كسبكم، وإن أولادكم من كسبكم فلأبيها أن يأخذ من مالها ما يرى من دون ضرر عليها، فيدع لها ما تحتاج إليه، ويأخذ منه ما ينفعه، ولا يضرها، لا بأس، أما غيره فلا إلا بإذنها إذا كانت رشيدة.","link":"https://binbaz.org.sa/fatwas/2588/حكم-اخذ-الاب-من-مهر-ابنته-دون-علمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1084.mp3","categories":["الصداق","الآداب والأخلاق"]},{"id":6754,"question":"ما حكم إذا خرجت المرأة للعمل في مجال لا اختلاط فيه، واستخدمت مربية مسلمة تقوم بالإشراف على أولادها أثناء غيابها للعمل، وكان زوجها موافقًا على هذا، والتزمت بالحجاب الإسلامي؟","title":"ضوابط خروج المرأة للعمل","answer":"الجواب:  لا حرج في ذلك -إن شاء الله- إذا كان هذا ما ذكرت من الشروط؛ فلا حرج في ذلك إذا كانت تلتزم بالحجاب، ويكون عملها في النساء، والأولاد عندهم من يتولاهم، ويحسن إليهم من النساء الطيبات المسلمات، وزوجها راض، ولا يكون خلوة من الزوج مع الموجودة في البيت، بل عندها من النساء من يمنع الخلوة، فهذا لا حرج فيه.  أما إذا كان يخلو بامرأة بعد زوجته؛ فهذا خطر عظيم، يجب أن تبقى المرأة في أولادها، ولا يحتاج إلى مربية تأتي للأولاد، وربما خلا بها الزوج، وربما وقعت الفتنة، فتبقى الزوجة مع أولادها، ولا حاجة إلى ذهابها، وعليه أن ينفق عليها، ويحسن إليها، ويقوم بحاجتها حتى تربي أولاده، وحتى تكون سكنًا له، ومرجعًا له يسكن بها، ويقضي متعته منها، وألا يقع في الفاحشة المنكرة في مربية أجنبية تقوم مقامها، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/2657/ضوابط-خروج-المراة-للعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1153.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6759,"question":"هل يجوز سفر المرأة بالطائرة، وغيرها بدون محرم، أو الذهاب بها إلى المدرسة، أو السوق مع غير محرمها؟ وإذا كان لا يجوز فبماذا تنصحون من يفعل ذلك، وهو شيء قد تفشى بين الكثير من المسلمين تهاوناً.. أعداء الإسلام؟","title":"حكم خروج المرأة أو سفرها بدون محرم","answer":"الجواب: أما سفر المرأة من دون محرم فهذا لا يجوز، وقد نص الشارع على ذلك، ونص النبي ﷺ على منع ذلك، فقال في الحديث الصحيح: لا تسافر المرأة إلا مع ذي محرم ولما أخبره رجل أن زوجته خرجت حاجة، وقد اكتتب في بعض الغزوات، قال له: ارجع فحج مع امرأتك فرده من الغزو، وأمره أن يذهب مع زوجته في الحج.  فالمقصود: أن سفرها بدون محرم لا يجوز، لا في الطائرة، ولا في السيارات، ولا في القطارات، ولا غيرها، وأما خروجها العادي من بيتها إلى المدرسة، أو إلى السوق، أو إلى كذا، أو إلى كذا، فكذلك لا يجوز أن تكون وحدها مع أجنبي. لكن لو اشترط المحرم سيكون معها غير المحرم؛ لأجل زوال الخلوة، يعني إن كان معها محرم؛ فهذا طيب، وإن لم يتيسر؛ كفى أن يكون معها من يوثق به، ومن تزول معه الخلوة، فإذا خرجت مع السواق، وزوجة السواق، أو مع امرأة أخرى من البيت، أو رجل آخر تحصل به الطمأنينة؛ فهذا يزيل الخلوة؛لأن النبي ﷺ قال: فثالثهما الشيطان فإذا كان معهما ثالث؛ زالت الخلوة؛ ولأن الحاجة ماسة لهذا الأمر، وليس من الميسور أن يكون المحرم معها في كل خرجة من الخرجات، فاكتفي بما يحصل به الطمأنينة، وزوال الخلوة.","link":"https://binbaz.org.sa/fatwas/2651/حكم-خروج-المراة-او-سفرها-بدون-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1147.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6765,"question":"ما حكم إذا خرجت المرأة للعمل في مجال لا اختلاط فيه، واستخدمت مربية مسلمة تقوم بالإشراف على أولادها أثناء غيابها للعمل، وكان زوجها موافقًا على هذا، والتزمت بالحجاب الإسلامي؟","title":"ضوابط خروج المرأة للعمل","answer":"الجواب:  لا حرج في ذلك -إن شاء الله- إذا كان هذا ما ذكرت من الشروط؛ فلا حرج في ذلك إذا كانت تلتزم بالحجاب، ويكون عملها في النساء، والأولاد عندهم من يتولاهم، ويحسن إليهم من النساء الطيبات المسلمات، وزوجها راض، ولا يكون خلوة من الزوج مع الموجودة في البيت، بل عندها من النساء من يمنع الخلوة، فهذا لا حرج فيه.  أما إذا كان يخلو بامرأة بعد زوجته؛ فهذا خطر عظيم، يجب أن تبقى المرأة في أولادها، ولا يحتاج إلى مربية تأتي للأولاد، وربما خلا بها الزوج، وربما وقعت الفتنة، فتبقى الزوجة مع أولادها، ولا حاجة إلى ذهابها، وعليه أن ينفق عليها، ويحسن إليها، ويقوم بحاجتها حتى تربي أولاده، وحتى تكون سكنًا له، ومرجعًا له يسكن بها، ويقضي متعته منها، وألا يقع في الفاحشة المنكرة في مربية أجنبية تقوم مقامها، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/2657/ضوابط-خروج-المراة-للعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1153.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6767,"question":"كثير من البرامج المذاعة في وسائل الإعلام يقوم بها نساء حتى في إلقاء اللقاءات الإسلامية، فهل يجوز لأي مسلم الاستماع لأصواتهن أفيدونا جزاكم الله خيرًا؟","title":"حكم سماع صوت المرأة في وسائل الإعلام","answer":"الجواب: صوتها ليس بعورة، وإنما العورة خضوعها، وتغنجها، وتكسرها بالصوت، كما قال الله -جل وعلا-: يَا نِسَاءَ النَّبِيِّ لَسْتُنَّ كَأَحَدٍ مِنَ النِّسَاءِ إِنِ اتَّقَيْتُنَّ فَلَا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ [الأحزاب:32].  ولا ينبغي أولًا استعمالهن في الإذاعة، والتلفاز، ونحو ذلك، ولكن متى وجد ذلك، فإن وجد من نفسه ميلًا إلى صوتها، وتلذذًا، وشهوة، فليحذر، وليبتعد، ولا يسمع، فإن كان هناك فائدة فيما تلقيه، ولا يحس من نفسه بشيء من التلذذ، والشهوة للصوت، وإنما أراد أن يسمع الكلام المفيد الذي قد تلقيه، أو الإنذار، أو البلاغ، أو ما أشبه ذلك، فأرجو أن لا حرج عليه في هذا  السماع الذي لا يضر دينه.","link":"https://binbaz.org.sa/fatwas/2652/حكم-سماع-صوت-المراة-في-وساىل-الاعلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1148.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6783,"question":"في مجلة آخر ساعة المصرية نشرت صور كثير من المحجبات، وهذه ظاهرة هناك الآن، ولكن كتب تحتها ظاهرة الحجاب لماذا؟ وعلق عليها الدكتور أحمد شلبي: الحجاب لا وجود له في الإسلام، وبالمناسبة لقد كثر الكلام، والجدال حول الحجاب، وأن المفروض أن تكشف المرأة عن وجهها، وكفيها لحديث الرسول ﷺ لأسماء، وعندما أقول لهم حديث ابن أم مكتوم أوعمياوان أنتما يقول: إنه حديث الرسول لأسماء حديث صحيح، نرجو الإفادة الشافية حيث إن الإخوة السائلين المختلفين موجودون هنا وشكرًا؟","title":"الرد على منكري الحجاب","answer":"الجواب: المنكر للحجاب إما جاهل، وإما مكابر، يقول الله -جل وعلا- في كتابه العظيم: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] هكذا في الآية الكريمة في سورة الأحزاب.  ويقول سبحانه في سورة النور: وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] الآية. بين  أن النساء عليهن غض الأبصار، وعليهن حفظ الفروج، وعليهن ألا يبدين زينتهن إلا ما ظهر منها، وهي الملابس الظاهرة، ثم بين من يبدى له الزينة، فقال: وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ إلى آخره، فدل ذلك على وجوب الحجاب، وأن الزينة يجب أن تستر الوجه، والشعور، وبدن المرأة كله محاسن، وكله زينة يجب أن تستر.  وأما حديث أسماء الذي ذكره السائل، وتعلق به بعض الناس: هو أن أسماء بنت أبي بكر دخلت على أختها عائشة، والنبي حاضر -عليه الصلاة والسلام- وعليها ثياب رقاق، فقال لها النبي ﷺ: يا أسماء إن المرأة إذا بلغت المحيض لا يصلح أن يرى منها إلا هذا، وهذا، وأشار إلى وجهه، وكفيه وهو حديث لا يصح عن النبي ﷺ والتعلق به تعلق بالباطل، فهو حديث رواه أبو داود بإسناد منقطع، عن عائشة، وبإسناد ضعيف، منقطع وضعيف، ضعيف من جهة انقطاعه، وضعيف من جهة بعض رواته، فهو حديث لا يصح عن النبي ﷺ. ولو صح لكان هذا قبل الحجاب، لأن الحجاب صريح، أنزل الله فيه الآيات، وأمر المرأة بالحجاب، فهذا لو صح؛ لكان قبل الحجاب، ولكنه غير صحيح، فإنه من رواية سعيد بن بشير، عن قتادة عن خالد بن دريك، عن عائشة، وسعيد بن بشير لا يحتج به، ضعيف في الرواية، ولا يحتج بروايته، وقتادة عن خالد معنعن، وهو مدلس؛ فلا يحتج بروايته إذا عنعن، وخالد بن دريك لا بأس به، لكنه لم يسمع من عائشة، لم يلق عائشة، ولم يسمع منها، فهو منقطع بين خالد، وبين عائشة، وضعيف من جهة رواية سعيد بن بشير، وضعيف من جهة عنعنة قتادة.  فالمقصود: أنه ضعيف من جهات ثلاث، فيه علل ثلاث: علة ضعف سعيد، وعلة تدليس قتادة، وعلة انقطاعه بين خالد، وبين عائشة، فهو ضعيف من وجوه ثلاثة، لا يحتج به، ولا يتعلق عليه، ولو فرضنا أنه صحيح، وجاء بإسناد صحيح؛ لكان هذا قبل أن يأتي الحجاب، وقبل أن يشرع الحجاب كان النساء يجلسون مع الرجال وهن كاشفات الوجوه، يتحدثن معهم، ثم أنزل الله الحجاب، وأمروا بالستر بعد ذلك كما جاءت السنة بذلك، قالت عائشة -رضي الله عنها- لما سمعت صوت صفوان بن معطل لما مر عليها حين خلفها الجيش -يحسبون أنها في هودجها- قالت: فسمعته يسترجع: إنا لله وإنا إليه راجعون لما رآها، قالت: فلما سمعته؛ خمرت وجهي، وكان قد رآني قبل الحجاب، فعرفني. المقصود: أن هذا يبين لنا أنهم كانوا قبل الحجاب يكشفون وجوههم، فلما جاء الحجاب؛ ستروا وجوههم، وهذا الحديث رواه البخاري ومسلم في الصحيحين عن عائشة -رضي الله عنها- أنها قالت: إنه رآني قبل الحجاب، فلما سمعت صوته؛ خمرت وجهي.","link":"https://binbaz.org.sa/fatwas/2649/الرد-على-منكري-الحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1145.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6787,"question":"الدين الإسلامي أوصى بصلة الرحم، فكيف توفق المرأة بين قوله تعالى: وَقَرْنَ فِي بُيُوتِكُنَّ [الأحزاب:33]، وبين زيارة أرحامها، وأقاربها، لا سيما إن كان لها الكثير من الإخوان، والأخوات، والأقارب، وهذا يقتضي خروجها ثلاثًا إلى أربع مرات في الأسبوع؟","title":"كيف توازن المرأة بين قرارها في بيتها وبين صلة أرحامها؟","answer":"الجواب: ليس من شرط الصلة الزيارة، إذا وصلتهم بالكلام، أو بالهاتف، أو بالمكاتبة، أو بإرسال الحاجة من النفقة، والمساعدة؛ حصل المقصود، ليس من اللازم أن تخرج كل ساعة لأصحابها، وأقاربها، فالصلة تكون بمال يرسل إليهم، وتكون بالمكاتبة، وتكون من طريق التلفون بالهاتف، كل هذا، وتكون من طريق الوصية، توصي فلانة، وفلانة يبلغون قريباتها السلام، وأقاربها السلام.  والزوج بالخيار إن شاء أذن لها، وإن شاء منعها، إن شاء أذن لها بالذهاب إليهن، والزيارة، وإن شاء منعها على حسب ما يراه من المصلحة، وإذا كانت الزيارة في أوقات متباعدة مع الحجاب، ومع الحشمة، ومع الاستقامة؛ فله أن يسمح لها في الأوقات المناسبة، تزور أختها، خالتها، عمتها، أمها، إلى غير ذلك. أما إذا كن يفسدن، ولا خير فيهن؛ فعدم الإذن لها أولى، إذا كن.. عمات، أو أخوات خبيثات منحرفات؛ فلا حاجة إلى ذلك، إذا أرادت أن تصلهن بالمال لفقرهن، تصلهن من دون حاجة إلى الذهاب إليهن، لفسادهن، وانحرافهن. فالمقصود: أنه ينظر في الأصلح، فإذا رأى أن الزيارة لأقاربها، أو لصواحباتها فيها المصالح الدينية، وهي ملتزمة، ومستقيمة في أوقات يحددها، فهذا من باب الإعانة على الخير، وإذا كانت الزيارة لأقاربها قد تفسدها، وقد تضر دينها، وأخلاقها؛ منعها، ينظر في الأصلح.","link":"https://binbaz.org.sa/fatwas/2660/كيف-توازن-المراة-بين-قرارها-في-بيتها-وبين-صلة-ارحامها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1156.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6843,"question":"شخص وجد بنتًا صغيرة لقيطة، عاشت عنده حتى الآن، وأنه ضمها في تابعيته، وأعطى لها اسمه، ما حكم علاقة البنت به شرعًا، وهل تستمر تسمية البنت بلقب العائلة، وهل يخبر البنت عند زواجها أنه ليس أبوها الحقيقي؟","title":"حكم تبني اللقيطة","answer":"الجواب: نعم، لا بد من هذا، تنسب إليهم؛ لأنهم أولياؤها، ربوها، وأحسنوا إليها، ولكن لا تكون بنتًا له، ينسبها إلى غيره، بنت عبدالله، بنت عبدالرحمن، الناس كلهم عباد الله، عبدالله، عبدالرحمن، عبداللطيف، ولا ينسبها إليه؛ لأنها لو نسبها إليه قد يظن أنها بنت له؛ فترث مع أولاده، وتصير محرمًا لهم، لا هذا لا يجوز، هذا فيه خطر عظيم.  أما كونه أحسن إليها، ورباها هذا له أجر في ذلك، لكن إذا كان ما رضعت من زوجته، ولا من بناته، ولا من أخواته، له زواجها، أجنبية يعتبرها، ولأولاده أن يتزوجوها، أما إذا كانت زوجته أرضعتها؛ لأنها كانت صغيرة قبل الفطام، يعني فأرضعتها زوجته، يكون أبًا لها، أو أرضعته بنته؛ يكون جدًا لها، أو أرضعته أخته؛ يكون خالًا لها.","link":"https://binbaz.org.sa/fatwas/2709/حكم-تبني-اللقيطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1208.mp3","categories":["اللقطة واللقيط","الآداب والأخلاق"]},{"id":6883,"question":"ما رأيكم إذا وجد الإنسان شاة، أو ناقة بأرض خلاء، وتولدت حتى كثرت؟ هل تحل للذي حفظها، وأسقاها، ورعاها، أم تحرم عليه؟ وهل يجب كفارة إذا أكل شيئًا منها؟","title":"حكم لقطة الغنم والإبل","answer":"الجواب: إذا وجد الإنسان شاة من الضأن، أو من المعز في مكان يخشى عليها منه؛ لأنها ليست قريبة من السكن من أهل السكان، ومن أهل الأغنام، ونحو ذلك؛فإن هذه تسمى لقطة، فإذا أخذها، وعرفها سنة في مجامع الناس، وفي مظان معرفتها، ولم يعرفها أحد؛ فإنها تكون له تكون من عرض ماله، ويتصرف فيها كسائر ماله بعد السنة، لكن يحفظ صفاتها، وعلاماتها؛ حتى إذا جاء طالبها يومًا من الدهر؛ أداها إليه، أو أدى قيمتها إن كانت مفقودة، هذا هو الواجب عليه في جميع اللقطات، أن يعرفها سنة كاملة في مجامع الناس، في كل شهر مرتين، ثلاث، أربع، على حسب ما تيسر، فإن عرفت .. فالحمد لله، وإلا استعملها كسائر ماله. وإذا كان بقاؤها في يده قد يضره، ويضر صاحبها؛ باعها، وحفظ ثمنها، وصفاتها حتى يجد ربها، وإذا كان في قرب المحاكم، والبلاد .. المحكمة، وضبطها عند المحكمة، وإن شاء جعلها عند المحكمة حتى تحفظ عندها، فإذا جاء ربها؛ سلمت له، وإن شاء حفظها عنده حتى تمر السنة، فإذا مرت السنة، ولم يجد أحدًا لها؛ فهي كسائر ماله، سواء بنفسها، أو قيمتها. أما الإبل فإنها لا تلتقط، النبي ﷺ قال: إن معها سقاءها، وحذاءها، ترد الماء، وتأكل الشجر، حتى يلقاها ربها ونهى عن التقاطها، فلا تلتقط، اللهم إلا أن تكون في محل مسبعة، يعني: على خطر من أن تتلف للسباع التي في الأرض، فحينئذ يسوقها إلى الأرض السليمة، حتى تبتعد عن الخطر، ويكون مأجورًا في ذلك، وأما أن يأخذها فلا؛ لأن الرسول ﷺ نهى عن التقاط الإبل، وقال: إن معها سقاءها، وحذاءها، ترد الماء، وتأكل الشجر، حتى يلقاها ربها. \n\nالسؤال: باقي السؤال: إذا وجد ناقة، لا يعرف صاحبها، ثم حلبها، وشرب لبنها، هل يوجد كفارة لذلك؟ الجواب: إذا وجدها في البر، وشرب منها؛ لا يضره -إن شاء الله- ولا حرج عليه في ذلك.","link":"https://binbaz.org.sa/fatwas/2764/حكم-لقطة-الغنم-والابل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1256.mp3","categories":["اللقطة واللقيط","الآداب والأخلاق"]},{"id":6889,"question":"إذا كنت أنا صاحب إبل، وجاءتني ناقة من الإبل، ولكن طردتها، ولم تذهب عن إبلي، وبالتالي استعملتها مثل الركوب، والظعن عليها حتى تلفت؟","title":"حكم من استعمل ضالة الإبل حتى تلفت","answer":"الجواب: هذا لا يجوز لك، ولو جاءت إلى إبلك عليك أن تطردها، أو تسلمها لولي الأمر، الأمير في بلدك، أو قاضي المحكمة، حتى تسلم من شرها، فإذا استعملتها؛ ضمنتها، وعليك غرامتها لصاحبها، أو لبيت المال حتى تصرف في وجوه الخير، لأنك قد عصيت ربك في إيوائها، وركوبها، واستعمالها.","link":"https://binbaz.org.sa/fatwas/2776/حكم-من-استعمل-ضالة-الابل-حتى-تلفت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1268.mp3","categories":["اللقطة واللقيط","الآداب والأخلاق"]},{"id":6902,"question":"أنا شاب أبلغ من العمر عشرين عامًا، والدي يعمل في التجارة، غير أنه يأخذ في بعض الأوقات قروضًا من البنك، ثم يردها إلى البنك، إضافة إلى الفائدة، وأنا بعض الأوقات أقوم بقضاء بعض الأعمال له،  هل يجوز لي أن آكل، أو آخذ من مال والدي؟","title":"حكم أكل الولد من مال والده المرابي","answer":"الجواب: ما دام والدك عنده دخول أخرى من الحلال، ولكنه قد يخطئ، فيأخذ سلفًا من البنك، لا حرج عليك أن تأكل مع والدك، وأن تعينه في الخير فقط، وتنصحه حتى لا يعود إلى القرض من البنك بالفائدة، تقول له: إن هذا محرم ولا يجوز لك، لعل الله يهديه بأسبابك، أو تقول لعمك، أو إخوانك الكبار، يقولون له بأسلوب حسن؛ حتى يهديه الله، ويقبل، عليك أن تفعل ما تستطيع من الخير، ولو بتحريك غيرك من أعمام، أو أخوال، أو إخوة كبار؛ حتى ينصحوه، ويتوجهوا إليه بما يعينه على ترك الربا.","link":"https://binbaz.org.sa/fatwas/2837/حكم-اكل-الولد-من-مال-والده-المرابي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1285.mp3","categories":["الربا والصرف","البيوع","الآداب والأخلاق"]},{"id":6907,"question":".. وبعيدة مع زوجتي وبناتي؟","title":"حكم سفر المرأة مع القريب غير المحرم","answer":"الجواب: السفر بغير المحارم لا يجوز، سواء كانت زوجة أخيك، أو زوجة عمك، أو خالك، أو غيرها، أما إذا كانت محرمًا لك، كزوجة ابنك، أو زوجة أبيك، أو أختك، أو بنتك؛ لا بأس بذلك.  وأما السفر بغير محارمك؛ فلا يجوز إلا إذا كان غير سفر، كالخروج العادي في ضواحي البلد، ولست وحدك، بل معك غيرك، لا تخلو بها، مع عائلتك، فلا بأس تذهب بها مع عائلتك إلى بيت آخر إلى ضواحي البلد، إلى منتزه قريب لا يسمى سفرًا، هذا لا بأس بشرط ألا تكون خاليًا بها، أما مع الخلوة فلا يجوز.","link":"https://binbaz.org.sa/fatwas/2828/حكم-سفر-المراة-مع-القريب-غير-المحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1276.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6917,"question":"هل بنات الأخوال، وبنات العم، والعمات من ذوي الأرحام؟ وهل تجب صلاتهن؟ وهل يأثم من ترك ذلك؟","title":"بنات العم والخال من الأرحام","answer":"الجواب: نعم بنات العم، وبنات الخال، وأولاد العم، وأولاد الخال كلهم من الرحم، لكن من الرحم غير القريب، أقرب منهم الأعمام، والأخوال، والإخوة، والأخوات، هم من الأقارب البعيدين بعض البعد، فإذا استطاع أن يصلهما بالمواساة بالمال؛ فليفعل، وإلا فليصلهما بالكلام الطيب، والفعل الطيب، والزيارة الحسنة التي ليس فيها محذور شرعًا.\n\nالسؤال: إن مستشفى الملك خالد الجامعي لا يوجد به مسجد للصلاة، وجميع المراجعين لهذا المستشفى، والموظفين في وقت الصلاة مستمرين في العمل، ولا يعلم عن صدور الوقت، نرجو الأهمية بهذا؟ الجواب: ننظر في هذا بارك الله فيك.","link":"https://binbaz.org.sa/fatwas/2847/بنات-العم-والخال-من-الارحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1295.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":6918,"question":"... بين أحد الأعمام، وابن أخيه، حتى إنه وصل المقام إلى مقاطعة عمه تمامًا، حيث لا يرد عليه السلام، وهذا الوضع منذ مدة طويلة تزيد على السنتين، فقد حاول العم الإصلاح، ولكن ابن الأخ يصر على مقاطعته، علمًا بأنه شاب طيب، وملتزم بمبادئ الدين، ولكن مع هذا لا زال يقاطع عمه، فما رأي فضيلتكم في هذا؟ وما هي العقوبة المترتبة على ذلك؟","title":"حكم هجر أحد الأقارب","answer":"الجواب: ينظر في العم، إذا كان العم قد أتى معاصي ظاهرة، أو بدعًا ظاهرة معروفة؛فولد أخيه معذور إذا قطعه، وإذا هجره حتى يتوب.  أما إذا كان العم لا جرم له، ولكنها أمور نفسية، وأمور تتعلق بالدنيا؛ فلا يجوز للولد أن يقطعه، ولا يجوز أن يهجره أكثر من ثلاثة أيام، الهجر ثلاثة أيام، فأقل في أمور الدنيا، ويلزمه صلته بعد ذلك، والسلام عليه، والقيام بحقه؛ لأن العم بمنزلة الأب، فلا يجوز له أن يقطعه، ولا أن يهجره إلا إذا كان ذلك من أجل إظهار المعاصي، وإظهار البدع، فهذا لا بأس بهجره؛ حتى يتوب إلى الله من ذلك.","link":"https://binbaz.org.sa/fatwas/2848/حكم-هجر-احد-الاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1296.mp3","categories":["الدعوة والدعاة","الآداب والأخلاق"]},{"id":6987,"question":"رجل طلق زوجته ثلاث مرات متفاوتات، وقد أنجب منها عشرة أولاد، ما بين ذكور، وإناث، أفيدونا جزاكم الله خيرًا؟","title":"الطلاق الذي يحرم الزوجة من زوجها","answer":"الجواب:\n\nإذا طلقها ثلاثًا متفرقات؛ انتهت فَإِنْ طَلَّقَهَا فَلَا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنْكِحَ زَوْجًا غَيْرَهُ [البقرة:230] يعني في المرة الثالثة، قال أولًا: الطَّلَاقُ مَرَّتَانِ [البقرة: 229]، ثم قال: فَإِنْ طَلَّقَهَا [البقرة:230] يعني الثالثة، فإذا طلقها، ثم راجعها، ثم طلقها، ثم راجعها، ثم طلقها الثالثة؛ خرجت، انتهت، وحرمت عليه، حتى تنكح زوجًا غيره.\n\nوهكذا لو قال: طالق، ثم طالق، ثم طالق؛ انتهت، إذا كان الطلاق .. العقل ما وقع في حال سكر، ولا في حال شدة غضب يغير شعوره، ما ملك نفسه، ولا في حال الحيض، ولا في حال النفاس، ولا في طهر جامعها فيه، فإن الطلاق يمضي عليه على الصحيح عند أهل العلم جميعًا، إذا سلم الطلاق من الموانع؛ يمضي عليه الطلاق، إذا طلقها ثلاثًا؛ حرمت عليه، حتى تنكح زوجا غيره.\n\nأما إذا كان طالقًا بالثلاث، كلمة واحدة، أنت مطلقة بالثلاث، هذا فيه خلاف بين أهل العلم، الأكثرون يرون أنها تمضي عليه أيضًا، وتحرم عليه، إلا بعد الزوج.\n\n وذهب بعض أهل العلم إلى أنها تحسب واحدة، كما كان في عهد النبي ﷺ وعهد الصديق، وعهد عمر في أول خلافته، وهذا هو الأرجح، أنها تحسب واحدة إذا كان بكلمة واحدة، قال: هي مطلقة بالثلاث، أو طالق بالثلاث، الأرجح من قولي العلماء: أنها تحسب واحدة، وله مراجعتها.\n\nأما إذا كان في أوقات، أو بكلمات طالق، ثم طالق، ثم طالق، أو طلق، ثم راجع وطلق، ثم راجع، ثم طلق الثالثة؛ تحرم عليه حتى تنكح زوجا غيره، فهذا مقام الطلاق مقام فيه تفصيل.","link":"https://binbaz.org.sa/fatwas/2924/الطلاق-الذي-يحرم-الزوجة-من-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1372.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":6990,"question":"ما حكم الزواج بنية الطلاق لمدة سبعة أيام، أو عشرة أيام إذا خشي المسافر على نفسه من الزنا؟ وهل فتوى اللجنة الدائمة للإفتاء في جواز الزواج بنية الطلاق تشمل المدة القصيرة والطويلة، أم لا؟ لأن بعض الشباب الذين سافروا في الإجازة السابقة صوروا الفتوى بحجة أنها تنطبق عليهم، ولو كانت المدة قصيرة، فما الحكم في ذلك؟","title":"الفرق بين نكاح المتعة والزواج بنية الطلاق","answer":"الجواب:\n\nهذا ليس من المتعة، المتعة أن يتزوج الإنسان وهو على شرط بينه وبين أهل الزوجة، أو الزوجة على أيام معلومة، أو سنة معلومة، أو شهر معلوم، كما كان في الجاهلية، وفي أول الإسلام، ثم نسخ ذلك في أثناء الإسلام، في حجة الوداع، وقيل: في يوم الفتح، على خلاف بين أهل العلم.\n\nأما كونه ينوي الطلاق هذا ليس بمتعة، يتزوج، وفي نيته أنه متى سافر من أمريكا، أو من أوروبا؛ طلق، قد يهون، ولا يطلق، إنما نوى شيئًا مباحًا له، نوى طلاقًا مباحًا له، وليس هذا من المتعة في شيء، المتعة: المشارطة على مدة معلومة متى مضت؛ انتهى النكاح، وانقضى النكاح، كما يفعل الآن في بعض طوائف الرافضة.\n\nالمقصود: أن المتعة شيء معلوم، بزمن معلوم مقدر، هذا هو الذي نسخه الله إلى يوم القيامة، وهو محرم، أما كون الإنسان يتزوج، ونيته أنه يطلق بعد سنة، أو شهر، أو أسبوع، أو سنتين، أو كذا؛ فقد يرجع عن هذه النية، وقد لا ينفذ هذه النية، شيء بينه وبين ربه -جل وعلا- ليس مشارطة بينه وبين الزوجة، ولا بينه وبين الولي، ولا بينه وبين الأسرة، إنما هو شيء في نفسه، هذا لا يضره عند جمهور أهل العلم، حكاه صاحب المغني عن أكثر العلماء، وقال بعض أهل العلم: لا ينبغي له ذلك، ولا ينبغي أن تكون هذه النية، فإذا ترك هذه النية، وتزوج بدون هذه النية؛ يكون أفضل، وأكمل، وأحوط.\n\nالسؤال: أليس في ذلك غش لأهل الزوجة إذا كانوا لا يعلمون؟\n\nالجواب: ما في غش، هو مباح له الطلاق، ولو ما نوى، ما هو ملزم بأن يبقى معها ولو ما نوى الطلاق، لو أنت تزوجت امرأة، ثم رأيت من المصلحة أن تطلقها بعد ليلة من الزواج؛ لا حرج عليك، رأيتها ما تناسبك، فطلقتها بعد ليلة، أو ليلتين؛ ما في حرج. \n\nالسؤال: من ناحية الإدارة المكتبة، مختلطة، وكل يوم تزيد عن اليوم الذي قبله؟\n\nالجواب: أي إدارة؟ \n\nالطالب: ... وهذا نشر للرذيلة تأتي الفتاة في أي وقت؟\n\nالجواب: ...؟\n\nالطالب: كتبناها لك قبل أسبوعين.\n\nالجواب: يمكن لو كتبت في ... جزاك الله خيرًا على النسيان.\n\nالطالب: وبعد نخبركم: أن رئيس الجهاز العسكري بالحرس الوطني يمنع بعض من يرغب الالتحاق بمدرسة تحفيظ القرآن بالحرس، ولا يرضى بأن يدخل بها إلا عريفًا، وجنديًا فقط، وما فوق العريف، والجندي يمنعه قطعيًا، ولو كان يرغب، ونرجو من فضيلتكم النظر في ذلك؟\n\nالجواب: ينظر في الأمر إن شاء الله.","link":"https://binbaz.org.sa/fatwas/2919/الفرق-بين-نكاح-المتعة-والزواج-بنية-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1367.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":7007,"question":"نرجو الإجابة على سؤالي هذا: أحد الإخوة هنا يدرس في معهد، وهو من جيزان، وقته ضيق، وليس عنده راحة إلا يوم الخميس والجمعة، فيقول: أرجو الإجابة على سؤالي هذا، إنه صار بيني وبين زوجتي خلاف في شأن الحجاب، وأمور أخرى، وقد ذهبت إلى أهلها عدة مرات، وأعيدها، والمرة الأخيرة لا زالت عند أهلها إلى وقتنا الحاضر منذ ثلاثة أشهر تقريبًا، وقد أوصلتها هذه المرة في عدم الرغبة في معاشرتها مرة ثانية، وما عدا لي رغبة فيها، ولي منها بنت صغيرة، وأرغب استرجاعها، هل يجوز لي ذلك، أم لا، أرجو إفادتي جزاكم الله خيرًا؟","title":"حكم من نوى الطلاق ولم يتلفظ به","answer":"الجواب:\n\nما دامت لم تطلق، إنما نويت نية، فالنية لا يقع بها الطلاق، يقول النبي ﷺ: إن الله تجاوز عن أمتي ما حدثت بها أنفسها ما لم تعمل أو تتكلم ما دام ناوي طلاقها، ولكن ما تكلمت بشيء؛ فهي زوجتك باقية.\n\nأما إن كنت تكلمت، تقول: روحي لأهلك، نويت الطلاق، أو أنت مطلقة، أو خارجة من ذمتي، أو ما أشبه ذلك؛ تعتبر طلقة واحدة، إذا قلت هذا الكلام فقط، أما إن كان مجرد نية فقط في نفسك، ولكن ما تكلمت بشيء؛ فهي باقية في عصمتك.\n\nالسؤال: ... هل ممكن يأخذ البنت؟\n\nالجواب: هي وأمها يأتي يأخذهن كلهن.\n\nالسؤال: لا، لو ما يريد يأخذ الأم ..؟\n\nالجواب: هذا عند المحكمة يا ولدي.","link":"https://binbaz.org.sa/fatwas/2930/حكم-من-نوى-الطلاق-ولم-يتلفظ-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1378.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":7017,"question":"نرجو الإجابة على سؤالي هذا: أحد الإخوة هنا يدرس في معهد، وهو من جيزان، وقته ضيق، وليس عنده راحة إلا يوم الخميس والجمعة، فيقول: أرجو الإجابة على سؤالي هذا، إنه صار بيني وبين زوجتي خلاف في شأن الحجاب، وأمور أخرى، وقد ذهبت إلى أهلها عدة مرات، وأعيدها، والمرة الأخيرة لا زالت عند أهلها إلى وقتنا الحاضر منذ ثلاثة أشهر تقريبًا، وقد أوصلتها هذه المرة في عدم الرغبة في معاشرتها مرة ثانية، وما عدا لي رغبة فيها، ولي منها بنت صغيرة، وأرغب استرجاعها، هل يجوز لي ذلك، أم لا، أرجو إفادتي جزاكم الله خيرًا؟","title":"حكم من نوى الطلاق ولم يتلفظ به","answer":"الجواب:\n\nما دامت لم تطلق، إنما نويت نية، فالنية لا يقع بها الطلاق، يقول النبي ﷺ: إن الله تجاوز عن أمتي ما حدثت بها أنفسها ما لم تعمل أو تتكلم ما دام ناوي طلاقها، ولكن ما تكلمت بشيء؛ فهي زوجتك باقية.\n\nأما إن كنت تكلمت، تقول: روحي لأهلك، نويت الطلاق، أو أنت مطلقة، أو خارجة من ذمتي، أو ما أشبه ذلك؛ تعتبر طلقة واحدة، إذا قلت هذا الكلام فقط، أما إن كان مجرد نية فقط في نفسك، ولكن ما تكلمت بشيء؛ فهي باقية في عصمتك.\n\nالسؤال: ... هل ممكن يأخذ البنت؟\n\nالجواب: هي وأمها يأتي يأخذهن كلهن.\n\nالسؤال: لا، لو ما يريد يأخذ الأم ..؟\n\nالجواب: هذا عند المحكمة يا ولدي.","link":"https://binbaz.org.sa/fatwas/2930/حكم-من-نوى-الطلاق-ولم-يتلفظ-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1378.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":7031,"question":"ما هو شائع هنا في المملكة في الصلاة، عدم سد الفرج بين المصلين في صفوفهم، هذا فضلًا عن علو الأصوات في المسجد بقراءة القرآن، فما معنى قول الرسول ﷺ: لا يقرأ أحدكم على قراءة أخيه، وضح هذين الأمرين، وجزاكم الله خيرًا؟","title":"حكم سد الفرج في الصلاة، ورفع الصوت بالقراءة في المسجد","answer":"الجواب:\n\nعدم سد الفرج هذا من الجهل، ينبغي لمن وجد ذلك أن ينصح إخوانه، يسدوا الفرج دائمًا، الأئمة يقولون: استووا، سدوا الفرج، تراصوا، ولكن هذا يحتاج إلى قلوب تسمع، وإلى آذان تسمع، فسد الفرج واجب، والرسول ﷺ أمر بذلك قال: تراصوا سدوا الفرج سدوا الخلل هكذا أمر -عليه الصلاة والسلام- فالواجب على الصفوف أن يسدوا الفرج، ويتراصوا.\n\nوأما الجهر بالقراءة فلا ينبغي ذلك، الواجب على المؤمن أن يقرأ قراءة منخفضة حتى لا يؤذي من حوله، ولا يشوش على من حوله من المصلين والقراء، إن كان في الصف يقرأ، وهو خافت في قراءته، حتى لا يشوش على الناس الذين من حوله، إلا إذا كان حوله ناس لا يقرؤون، يحبون يسمعون صوته، يرفع بقدرهم، وأما أن يرفع ويؤذي من حوله من المصلين، أو القراء، ويشوش عليهم لا، النبي ﷺ خرج على قوم في المسجد يجهر بعضهم على بعض، فقال: كلكم يناجي الله، فلا يجهر بعضكم على بعض وفي لفظ: فلا يؤذ بعضكم بعضًا.\n\n \n\nالسؤال:...؟\nالجواب: لا، حتى في غير المساجد، لو كانوا في محل لو كانوا في مدرسة يوجههم المدرس الأستاذ حتى لا يشق بعضهم على بعض، لكن إذا كانوا يقرؤون جميعًا ما يشوش بعضهم على بعض إذا كانوا في درس واحد.","link":"https://binbaz.org.sa/fatwas/3011/حكم-سد-الفرج-في-الصلاة-ورفع-الصوت-بالقراءة-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1418.mp3","categories":["الآداب والأخلاق","صلاة الجماعة"]},{"id":7043,"question":"حدث نزاع بيني وبين زوجتي، وأنا سوري، وهي سورية، وهي طالبة بكلية الصيدلة، وكانت تطلب مني الطلاق دائمًا وتقول: إني أنتظر عليك حتى أتخرج من الجامعة، وسأتركك، وأدى ذلك الأمر إلى أن بصقت في وجهي، وضربتني، وتجرأت علي، ولولا أنني أخشى الطلاق؛ لأنه يغضب الله، وتهتز له السماوات السبع؛ لطلقتها من زمن، فلقد ساءت عشرتها معي، وتحتقرني، ولقد فشل أبوها وأمها معي في ذلك، وأهلها، ويطلبون مني الصبر، فما العمل، وأنا أكرهها، وهي تكرهني؟","title":"مشروعية الطلاق عند الحاجة إليه","answer":"الجواب:\n\nلا حول ولا قوة إلا بالله، هذه يا أخي حالتها سيئة، والطلاق من قال لك: إنه يغضب الله؟! ومن قال لك: أنها تهتز لها السماوات! هذا كذب، الطلاق ما تهتز له السماوات، ولا يغضب الله إذا كان في محله، الطلاق من رحمة الله، ومن نعم الله، إذا ساءت العشرة؛ طلقها واسترح منها. \n\nفالطلاق مباح، الله -جل وعلا- قال: الطَّلَاقُ مَرَّتَانِ [البقرة:229]، قال: يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1] فالطلاق مباح، لكن تركه أولى، إذا كان ما في حاجة يكره إذا كان ما له حاجة، أما إذا كان فيه حاجة، واحدة تتفل في وجهك، وتصفعك .. نسأل الله السلامة.\n\nالمقصود: لا بأس إذا كنت ترى فيها الصبر، فيه خير، فلا تعجل في الطلاق، وجاهدها بالكلام الطيب، وأعطها المال، أرضها بالمال، فإن صلحت وقبلت منك؛ وإلا طلقها، ويعطيك الله أبرك منها، هذا إذا كانت طيبة، إذا كانت سيرتها طيبة، غير العمل هذا، إن كانت تصلي وطيبة في دينها، وعفيفة، وبعيدة عن الفتنة، ومتسترة ومتححبة؛ فحافظ عليها، وأرضها بالمال، وتكلم .. من جهة عملها السيئ، واستعن عليها بالله، ثم بأقاربها الطيبين، وأهلها الطيبين، حتى ينصحوها، وحتى يوجهوها، فإن استقامت؛ وإلا فأبعدها وطلقها، والطلاق ما فيه شيء عليك، الطلاق للمرأة السيئة يرضي الله، ما هو يغضب الله -نسأل الله السلامة-.","link":"https://binbaz.org.sa/fatwas/3066/مشروعية-الطلاق-عند-الحاجة-اليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1453.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":7063,"question":"العديد من الإخوان -هدانا الله وإياهم- يأتون متأخرين قبل ما تقام صلاة العشاء، وإذا قامت الصلاة يزاحمون في الصف الأول، حتى إن بعض الذي في الصف الأول يفضلون الصفوف الأخرى؟","title":"مزاحمة المتأخرين للمتقدمين في الصفوف الأول","answer":"الجواب:\n\nهذا لا يجوز، الواجب على المسلم إذا جاء أن يقف في الصف الذي يليه، والذي يتيسر له، ولا يزاحم الناس، ويؤذيهم، الله -جل وعلا- يقول: وَالَّذِينَ يُؤْذُونَ الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ بِغَيْرِ مَا اكْتَسَبُوا فَقَدِ احْتَمَلُوا بُهْتَانًا وَإِثْمًا مُبِينًا [الأحزاب:58]. \n\nوفي الحديث: من ضار مسلمًا؛ ضاره الله، ومن شق على مسلم؛ شق الله عليه الواجب أن الإنسان ينتهي حيث تنتهي الصفوف، ولا يضار الناس إلا إذا وجد فرجة تتسع له؛ تقدم لها، أو راص بينهما حتى يتسع له المكان، فيدخل.","link":"https://binbaz.org.sa/fatwas/3023/مزاحمة-المتاخرين-للمتقدمين-في-الصفوف-الاول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1430.mp3","categories":["الآداب والأخلاق","صلاة الجماعة"]},{"id":7068,"question":"حدث نزاع بيني وبين زوجتي، وأنا سوري، وهي سورية، وهي طالبة بكلية الصيدلة، وكانت تطلب مني الطلاق دائمًا وتقول: إني أنتظر عليك حتى أتخرج من الجامعة، وسأتركك، وأدى ذلك الأمر إلى أن بصقت في وجهي، وضربتني، وتجرأت علي، ولولا أنني أخشى الطلاق؛ لأنه يغضب الله، وتهتز له السماوات السبع؛ لطلقتها من زمن، فلقد ساءت عشرتها معي، وتحتقرني، ولقد فشل أبوها وأمها معي في ذلك، وأهلها، ويطلبون مني الصبر، فما العمل، وأنا أكرهها، وهي تكرهني؟","title":"مشروعية الطلاق عند الحاجة إليه","answer":"الجواب:\n\nلا حول ولا قوة إلا بالله، هذه يا أخي حالتها سيئة، والطلاق من قال لك: إنه يغضب الله؟! ومن قال لك: أنها تهتز لها السماوات! هذا كذب، الطلاق ما تهتز له السماوات، ولا يغضب الله إذا كان في محله، الطلاق من رحمة الله، ومن نعم الله، إذا ساءت العشرة؛ طلقها واسترح منها. \n\nفالطلاق مباح، الله -جل وعلا- قال: الطَّلَاقُ مَرَّتَانِ [البقرة:229]، قال: يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1] فالطلاق مباح، لكن تركه أولى، إذا كان ما في حاجة يكره إذا كان ما له حاجة، أما إذا كان فيه حاجة، واحدة تتفل في وجهك، وتصفعك .. نسأل الله السلامة.\n\nالمقصود: لا بأس إذا كنت ترى فيها الصبر، فيه خير، فلا تعجل في الطلاق، وجاهدها بالكلام الطيب، وأعطها المال، أرضها بالمال، فإن صلحت وقبلت منك؛ وإلا طلقها، ويعطيك الله أبرك منها، هذا إذا كانت طيبة، إذا كانت سيرتها طيبة، غير العمل هذا، إن كانت تصلي وطيبة في دينها، وعفيفة، وبعيدة عن الفتنة، ومتسترة ومتححبة؛ فحافظ عليها، وأرضها بالمال، وتكلم .. من جهة عملها السيئ، واستعن عليها بالله، ثم بأقاربها الطيبين، وأهلها الطيبين، حتى ينصحوها، وحتى يوجهوها، فإن استقامت؛ وإلا فأبعدها وطلقها، والطلاق ما فيه شيء عليك، الطلاق للمرأة السيئة يرضي الله، ما هو يغضب الله -نسأل الله السلامة-.","link":"https://binbaz.org.sa/fatwas/3066/مشروعية-الطلاق-عند-الحاجة-اليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1453.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":7073,"question":"حدث نزاع بيني وبين زوجتي، وأنا سوري، وهي سورية، وهي طالبة بكلية الصيدلة، وكانت تطلب مني الطلاق دائمًا وتقول: إني أنتظر عليك حتى أتخرج من الجامعة، وسأتركك، وأدى ذلك الأمر إلى أن بصقت في وجهي، وضربتني، وتجرأت علي، ولولا أنني أخشى الطلاق؛ لأنه يغضب الله، وتهتز له السماوات السبع؛ لطلقتها من زمن، فلقد ساءت عشرتها معي، وتحتقرني، ولقد فشل أبوها وأمها معي في ذلك، وأهلها، ويطلبون مني الصبر، فما العمل، وأنا أكرهها، وهي تكرهني؟","title":"مشروعية الطلاق عند الحاجة إليه","answer":"الجواب:\n\nلا حول ولا قوة إلا بالله، هذه يا أخي حالتها سيئة، والطلاق من قال لك: إنه يغضب الله؟! ومن قال لك: أنها تهتز لها السماوات! هذا كذب، الطلاق ما تهتز له السماوات، ولا يغضب الله إذا كان في محله، الطلاق من رحمة الله، ومن نعم الله، إذا ساءت العشرة؛ طلقها واسترح منها. \n\nفالطلاق مباح، الله -جل وعلا- قال: الطَّلَاقُ مَرَّتَانِ [البقرة:229]، قال: يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1] فالطلاق مباح، لكن تركه أولى، إذا كان ما في حاجة يكره إذا كان ما له حاجة، أما إذا كان فيه حاجة، واحدة تتفل في وجهك، وتصفعك .. نسأل الله السلامة.\n\nالمقصود: لا بأس إذا كنت ترى فيها الصبر، فيه خير، فلا تعجل في الطلاق، وجاهدها بالكلام الطيب، وأعطها المال، أرضها بالمال، فإن صلحت وقبلت منك؛ وإلا طلقها، ويعطيك الله أبرك منها، هذا إذا كانت طيبة، إذا كانت سيرتها طيبة، غير العمل هذا، إن كانت تصلي وطيبة في دينها، وعفيفة، وبعيدة عن الفتنة، ومتسترة ومتححبة؛ فحافظ عليها، وأرضها بالمال، وتكلم .. من جهة عملها السيئ، واستعن عليها بالله، ثم بأقاربها الطيبين، وأهلها الطيبين، حتى ينصحوها، وحتى يوجهوها، فإن استقامت؛ وإلا فأبعدها وطلقها، والطلاق ما فيه شيء عليك، الطلاق للمرأة السيئة يرضي الله، ما هو يغضب الله -نسأل الله السلامة-.","link":"https://binbaz.org.sa/fatwas/3066/مشروعية-الطلاق-عند-الحاجة-اليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1453.mp3","categories":["الطلاق","الآداب والأخلاق"]},{"id":7120,"question":"نرجو نصح سماحتكم فيما يحصل من مدينة جيزان أنه إذا حصل عندهم مناسبة زواج، أو ختان؛ يدخلون الرجال يطبلون، ويسمونهم مزلفين، ويطبلون هؤلاء في وسط النساء، والنساء ينثرن عليهم النقود، وهم يرقصون بدون حياء من الله؟","title":"حكم دخول الرجال بين النساء في مناسبات الزواج","answer":"الجواب:\n\nهذا قد بُيِّنَ لهم، وكتب لهم في هذا، والدعاة الذين هناك مكلفون بهذا الشيء، ببيان هذا الشيء، ونسأل الله أن يهدي الجميع. \n\nكثير من الناس قد يسمع النصيحة ولا يلتفت إليها، ويرى أن العادة التي اعتادها شيئًا لازمًا، يقدمها على ما قاله الله ورسوله، وهل عودي الرسل والمصلحون إلا بالعوائد الضارة، العوائد المخالفة للشرع، عوائد الجاهلية هي التي عودي بها الرسل، وعودي بها المصلحون. \n\nفالواجب على المسلم أن يبتعد عن العادة السيئة المخالفة للشرع، وألا يغتر بما عليه أسلافه إذا كان شيئًا باطلًا، فالعوائد لا يحتج بها، بل تعرض على الأدلة الشرعية، فإن جادت؛ أخذ بها، وإلا وجب طرحها وإن كانت عادة للآباء والأسلاف.\n\nولا ينبغي للعاقل أن يكون مثل ما قال الجاهلون من الكفار: إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِمْ مُقْتَدُونَ [الزخرف:23] هذه حجة الكفرة التي احتجوا بها على الرسل إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِمْ مُقْتَدُونَ [الزخرف:23] هذه حجة داحضة باطلة، ما يجوز لأي مسلم أن يحتج بها، بل يجب أن يعرض ما أشكل عليه على الأدلة الشرعية، ويسأل أهل العلم بالشرع عن ذلك، ولا يقول هذه عادة أبي، أو جدي، أو أهل بلدي، ويكتفي بها، ولو خالفت الشرع.\n\nالسؤال: العامة قلت تكتبون لهم، وأنا في روحة أهلي وجدتهم لا زالوا على حالتهم وأشد؟\n\nالجواب: ولو، الرسائل جاءتهم عدة رسائل في هذا، وقرأها عليهم الدعاة، ولكن العادات مثل ما قيل قاهرات، قل من يتركها، نسأل السلامة، نسأل الله أن يهدينا وإياهم.","link":"https://binbaz.org.sa/fatwas/3168/حكم-دخول-الرجال-بين-النساء-في-مناسبات-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1526.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":7129,"question":"صوت المرأة؟","title":"صوت المرأة ليس بعورة لكن لا تخضع بالقول","answer":"الجواب: أما صوت المرأة فليس بعورة، قد كان النساء يخاطبن النبي ﷺ ويخاطبن الصحابة، ويسلم الرجال على النساء، والنساء على الرجال، ليس بعورة، إنما العورة خضوعها بالقول، وتكسرها في القول، وتغنجها في القول قال -جل وعلا- : يَا نِسَاءَ النَّبِيِّ لَسْتُنَّ كَأَحَدٍ مِنَ النِّسَاءِ إِنِ اتَّقَيْتُنَّ فَلَا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ وَقُلْنَ قَوْلًا مَعْرُوفًا [الأحزاب: 32] المرض، يعني مرض الشهوة. فالحاصل: أن الخضوع بالقول، واللين في القول خلاف العادة، هذا هو الذي ينهى عنه، أما القول المعتاد، والكلام المعتاد فلا بأس به، وليس بعورة، ولهذا قال: وَقُلْنَ قَوْلًا مَعْرُوفًا [الأحزاب: 32] يعني القول المعتاد الذي ليس فيه خضوع، ولا تغنج، ولا غير ذلك مما يدعو إلى الفتنة.","link":"https://binbaz.org.sa/fatwas/3170/صوت-المراة-ليس-بعورة-لكن-لا-تخضع-بالقول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1528.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":7134,"question":"نظر المرأة إلى الرجل؟","title":"حكم نظر المرأة إلى الرجل","answer":"الجواب:\n\nمثل ما قال الله -جل وعلا-: وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ [النور:31] مثل الرجل، عليها أن تغض، وعليه أن يغض، والنظر العارض لا يضر، النظر العارض الذي ليس بمقصود لا يضر، مثل ما تنظر إلى الرجال في طريقها، أو في المصلى، في المسجد، إذا صلت مع الناس هذا نظر عارض لا يضر، أما النظر الذي يكون معه الشهوة، أو معه الفتنة؛ فلا يجوز.","link":"https://binbaz.org.sa/fatwas/3171/حكم-نظر-المراة-الى-الرجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1529.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":7142,"question":"فضيلة شيخي! جنوب المملكة يستبيحون كشف الوجه لأخي الزوج وأقاربه، فما هو الرد على هؤلاء مع أمرها بذلك؟","title":"حكم كشف الوجه لأخي الزوج وأقاربه","answer":"الجواب:\n\nهذا في الجنوب وفي غير الجنوب، الرسول ﷺ قال: إياكم والدخول على النساء قيل: يا رسول الله أرأيت الحمو؟ قال: الحمو الموت الحمو: أخو الرجل، وعم الرجل.\n\nفإذا تساهلت في الكشف له هذا من وسائل الشر، إذا تساهلت؛ دل على ضعف إيمانها، ودعاه ذلك إلى الطمع فيها، فلا يجوز لها أن تكشف لا لأخي زوجها، ولا لعم زوجها، ولا لخال زوجها، وليس لها أن تكشف أيضًا لزوج أختها، ولا زوج خالتها، ولا زوج عمتها، كلهم أجانب بالنسبة إليها.\n\nإنما الكشف يكون لأبي زوجها، لجد زوجها، لأولاد زوجها، هؤلاء هم المحارم: أولاد الزوج، وأولاد أولاده، وأولاد بناته، هم المحارم، أما زوج الأخت، زوج العمة، زوج الخالة، هؤلاء ليسوا محارمًا، المحارم زوج بنتها، وزوج أمها، هؤلاء محارم.","link":"https://binbaz.org.sa/fatwas/3167/حكم-كشف-الوجه-لاخي-الزوج-واقاربه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1525.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":7147,"question":"سفر المرأة بدون محرم حرام، ولكن ما هو مفهوم قول الرسول ﷺ في الحديث: سفر يوم وليلة هل سفرها من أي دولة إلى هنا بطريق الطائرة وهي لا تمكث أكثر من ساعة ونصف يعتبر سفرًا أقل من يوم وليلة؟","title":"ضابط السفر للمرأة","answer":"الجواب:\n\nكل ما سمي سفر؛ فهو ممنوع، لقوله ﷺ: لا تسافر المرأة إلا مع ذي محرم هكذا جاء في الحديث الصحيح في الصحيحين من حديث ابن عباس -رضي الله عنهما-. \n\nأما ما ورد في بعض الروايات ثلاثة أيام، وبعضها يوم وليلة، وبعضها يوم، وبعضها ليلة، وبعضها بريد. فأجاب العلماء عن ذلك بأنها على حسب الأسئلة، هذا يسأل عن يوم، وهذا يسأل عن بريد، وهذا يسأل عن يوم وليلة، وهذا يسأل عن يومين، على حسب الأسئلة، ليس للتقييد، ولكنها تقع من باب سؤال السائل، فيجيبه النبي ﷺ على ما سأل، وليس المراد التقيد، ولهذا جاءت متنوعة في بعضها ثلاثة أيام، وفي بعضها يومين، وفي بعضها يوم وليلة، وفي بعضها ليلة، وفي بعضها يوم، وفي بعضها بريد، والضابط في هذا هو السفر، كل ما يسمى سفر في الطائرة أو في القطار أو في السيارة أو في الإبل، كل ما يسمى سفر؛ يمنع سفرها إلا بمحرم.\n\nالسؤال: هو أحد الموظفين هنا، وأرسل لزوجته من دولة ثانية تأتي له ما يقدر ينزل يأتي بها ...؟\n\nالجواب: كل هذا غلط، كله غلط، لا بد ينزل لها، ويجيبها أخوها، أو عمها، أو نحو ذلك، أما أنها تأتي بالطائرة، قد يحصل لها من يفسدها في الطائرة، يغامزها، ويتكلم معها، ويواعدها للفساد، وقد لا يوافقها أحد عند وصولها، قد يعرض عارض، فلا يخرج لها محرم عند وصولها إلى المطار، قد يعرض عارض في الطائرة، فترجع إلى بلد أخرى.","link":"https://binbaz.org.sa/fatwas/3182/ضابط-السفر-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1540.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":7153,"question":"ما حكم الجلوس مع بنات العم، وبنات الخال مع حضور المحرم؟","title":"حكم الجلوس مع بنات العم أو الخال","answer":"الجواب:\n\nإذا كن متسترات، ولا في فتنة؛ فلا بأس، أما إذا كان الحضور لأجل الفتنة ولأجل التمتع بالنظر إليهن وهن سافرات؛ لا يجوز هذا.\n\nأما الجلوس معهن للسلام عليهن، أو السؤال عن حال مريضهن، وهن متسترات متحجبات بعيدات عن الفتنة على طريق الحشمة؛ فلا بأس، هكذا المسلمون فيما بينهم.","link":"https://binbaz.org.sa/fatwas/3184/حكم-الجلوس-مع-بنات-العم-او-الخال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1542.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":7157,"question":"هل يجوز أن أصافح عمات وخالات زوجتي؟","title":"حكم مصافحة عمات وخالات الزوجة","answer":"الجواب:\n\nليس لك أن تصافح لا عماتها ولا خالاتها ولا أخواتها أيضًا، ليس لك ذلك، إنما هذا مع الأم، مع أمها، أو بنتها بعد الدخول بها، أما عماتها وخالاتها وأخواتها فليسوا محارم، وإنما تسلم عليهن بالكلام فقط، كيف حالكم؟ كيف أنتم؟ السلام عليكم، وعليكم السلام، من دون مصافحة.","link":"https://binbaz.org.sa/fatwas/3185/حكم-مصافحة-عمات-وخالات-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1543.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":7162,"question":"لماذا ينظر النبي ﷺ إلى الخثعمية، ويدير وجه الفضل؟ هل ذلك مباح له وحده ﷺ أم ماذا؟","title":"شبهة توجيه نظر رسول الله إلى الخثعمية","answer":"الجواب:\n\nمثلما تقدم، مثلما سمعتم، هذا من باب ترك أسباب الفتنة؛ لأن النظر قد يكون من أسباب الفتنة، ولو إلى قدها، وحسن صوتها، لا يلزم من هذا السفور. \n\nوالخثعمية ما فيه أنها كانت سافرة، إنما كان ينظر إليها، وتنظر إليه، قد يكون من أجل سماع صوتها، وحسن صوتها، أو لأسباب أخرى، فلهذا خاف عليه النبي ﷺ والنبي لا يخشى عليه من هذا -عليه الصلاة والسلام- لأن الله قد عصمه من هذه الفتنة.","link":"https://binbaz.org.sa/fatwas/3186/شبهة-توجيه-نظر-رسول-الله-الى-الخثعمية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1544.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":7170,"question":"هل يجوز إذا مر رجل بنساء أن يسلم عليهن، أم لا؟","title":"حكم إلقاء السلام على النساء","answer":"الجواب:\n\nنعم، النبي ﷺ سلم على النساء، وسلم عليهن، وأومأ بيده كما سمعتم في الندوة، فإذا سلم عليهن قال: السلام عليكم؛ فعليهن أن يقلن: وعليكم السلام، وإن كن بعيدات أشار بيده وسلم ليفهموا، وهكذا غيرهم من الرجال إذا بعدوا، أو في محل يخشى ألا يسمعوه؛ يسلم ويشير.","link":"https://binbaz.org.sa/fatwas/3208/حكم-القاء-السلام-على-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1557.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":7173,"question":"هل يجوز معانقة ومقابلة الخالة، أو العمة، أو ما شابههما؟","title":"حكم معانقة المحارم","answer":"الجواب:\n\nنعم محارم، كان النبي ﷺ إذا دخلت عليه ابنته فاطمة؛ قام إليها، وأخذ بيدها وقبلها، فإذا دخلت عليه خالته، أو أمه أو عمته أو أخته، إذا قام إليها وقابلها وصافحها أو عانقها؛ لا بأس بذلك.\n\nالسؤال: طيب زوجة عمه؟\n\nالجواب: لا، زوجة عمه ما هي بمحرم.\n\nالطالب: ما يقابلها؟\n\nالجواب: زوجة عمه، وزوجة أخيه، وزوجة خاله ليست بمحرم له، إنما يسلم عليها بالكلام فقط بدون مصافحة، وبدون معانقة، بالكلام، يعني كيف حالك يا فلانة؟ كيف الأولاد؟ كيف عمي؟ كيف خالي؟ أما أنه يقبلها ويصافحها لا. \n\nالسؤال: مقابلتها ما يجوز؟\n\nالجواب: المقابلة تختلف، المقابلة بالكلام لا بأس مع كونها محتجبة مستترة، أما مقابلتها بالمصافحة، أو بالمعانقة، والتقبيل، لا.","link":"https://binbaz.org.sa/fatwas/3212/حكم-معانقة-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1560.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":7237,"question":"ما رأيكم فيمن يربي شعره وهو يلبس غترة، وأحيانًا لا يلبس، ولكن لا يريد تقليد الكفار، كما نعلم أن هناك بعض الصحابة -رضي الله عنهم وأرضاهم- كان بعضهم يربي الرأس ويطوله؟","title":"حكم تربية شعر الرأس","answer":"الجواب:\n\nلا حرج في تربية الرأس، النبي ربى رأسه -عليه الصلاة والسلام- كان رأسه يضرب بعض الأحيان إلى منكبه -عليه الصلاة والسلام- المقصود أن التربية للرأس لا بأس، ولا حرج في ذلك، لكن بشرط ألا يكون قصده من ذلك التعرض للنساء والفواحش، أما إذا كان يتعرض بذلك للنساء، والفتن؛ فيمنع.\n\nولهذا لما بلغ عمر قصة نصر بن الحجاج وما يتعرض له من إغراء النساء؛ أمر بجلده، وحلق رأسه، جلده عن الخمر، وحلق رأسه الذي رباه للفتنة. \n\nفالحاصل: إذا كانت التربية للتأسي بالصحابة، والتأسي بالنبي ﷺ ولا يتعرض للفتن مع النساء، والمغازلات للنساء؛ فلا بأس، ولا حرج، أما إذا كان يظهر من حاله قصده الفتنة، ومغازلة النساء، والتعرض للنساء؛ فهذا يمنع، ويحلق رأسه، يكون عقوبة.","link":"https://binbaz.org.sa/fatwas/3292/حكم-تربية-شعر-الراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1617.mp3","categories":["الآداب والأخلاق","اللباس والزينة"]},{"id":7239,"question":"الجارية المملوكة يجوز لسيدها أن يجامعها، فهل يجوز للعبد المملوك أن يجامع سيدته بإذنها لقوله تعالى: إِلَّا مَا مَلَكَتْ أَيْمَانُكُمْ [النساء:24]؟","title":"حكم جماع العبد المملوك لسيدته","answer":"الجواب:\n\nلا، هذا منكر، هذا إنما هو في الرجال، قال تعالى: وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ ۝ إِلَّا عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ [المؤمنون:5، 6] المراد به الإماء للسيد، ولهذا ذكر ... فالسيد له أن يتصل بزوجته الشرعية، وبأمته الشرعية التي يملكها ملكًا شرعيًا، إما بالسبي، وإلا بالشراء من قوم قد توثق ملكهم لها، فإذا اشتراها، واستبرأها بحيضة؛ جاز له أن يباشرها إذا كان ملكًا شرعيًا، كما يباشر زوجته.\n\nأما العبد لا، ليس له أن يباشر سيدته، لا يقبل، ولا يجامع، هذا منكر بإجماع المسلمين، ليس له أن يباشر سيدته، لا بجماع ولا بغيره، وإنما يخدمها بأوامرها، ولا يلزمها الحجاب عنه، لكن ليس محرمًا لها.\n\nوإنما أباح الله لها عدم الحجاب؛ لأنها تتضرر بذلك، بأسباب كثرة دخوله عليها، وخدمته لها، ولكن ليست حلًا له، فلا يقبل، ولا يجامع، فهي حرام عليه.","link":"https://binbaz.org.sa/fatwas/3298/حكم-جماع-العبد-المملوك-لسيدته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1623.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":7307,"question":"ما رأي سماحتكم في استمرار الزواج بين الزوج والزوجة الذين لا يصلون، هل يبطل عقد زواجهما، وإذا عادا وتابا إلى الله، وقاما للصلاة فهل يجدد العقد، أم لا؟","title":"حكم عقد الزوجية للزوجين تاركي الصلاة","answer":"الجواب: إذا كانا جميعًا لا يصليان؛ صار العقد صحيحًا مثل عقود الكفرة، أما إذا كان الزوج لا يصلي، وهي تصلي، أو هو يصلي، وهي لا تصلي؛ فلا يصح العقد، يجدد؛ لأن من تركها كفر على الصحيح، فيجدد العقد بعد توبة الذي لا يصلي. السؤال: يعني إذا عادا إلى الصلاة يجدد العقد؟ الجواب: يجدد العقد، وقبل ذلك يمنع منها وتمنع منه.","link":"https://binbaz.org.sa/fatwas/3370/حكم-عقد-الزوجية-للزوجين-تاركي-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1688.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":7308,"question":"إذا كان عند الرجل أربع نساء، ثم طلق إحداهن، وتزوج بأخرى قبل أن تتم عدة المطلقة؟","title":"حكم الزواج بالخامسة قبل تمام عدة الطلاق للرابعة","answer":"الجواب: ليس له ذلك، لا يجوز له التزوج حتى تخرج من العدة إن كانت رجعية، لا يجوز له بإجماع المسلمين؛ لأنها زوجة، الرجعية إن طلقها واحدة، أو ثنتين؛ فهي رجعية، ليس له الزواج بالخامسة حتى تخرج هذه من العدة.  وإن كان الطلاق بائنًا؛ ففيه خلاف بين أهل العلم، والذي ينبغي ألا يتزوج، هذا هو الصواب؛ عليه أن لا يتزوج حتى تخرج من العدة؛ حسمًا لمادة التساهل؛ وسدًّا لذريعة التزوج في عدة أخرى.","link":"https://binbaz.org.sa/fatwas/3388/حكم-الزواج-بالخامسة-قبل-تمام-عدة-الطلاق-للرابعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1704.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":7314,"question":"إذا كان عند الرجل أربع نساء، ثم طلق إحداهن، وتزوج بأخرى قبل أن تتم عدة المطلقة؟","title":"حكم الزواج بالخامسة قبل تمام عدة الطلاق للرابعة","answer":"الجواب: ليس له ذلك، لا يجوز له التزوج حتى تخرج من العدة إن كانت رجعية، لا يجوز له بإجماع المسلمين؛ لأنها زوجة، الرجعية إن طلقها واحدة، أو ثنتين؛ فهي رجعية، ليس له الزواج بالخامسة حتى تخرج هذه من العدة.  وإن كان الطلاق بائنًا؛ ففيه خلاف بين أهل العلم، والذي ينبغي ألا يتزوج، هذا هو الصواب؛ عليه أن لا يتزوج حتى تخرج من العدة؛ حسمًا لمادة التساهل؛ وسدًّا لذريعة التزوج في عدة أخرى.","link":"https://binbaz.org.sa/fatwas/3388/حكم-الزواج-بالخامسة-قبل-تمام-عدة-الطلاق-للرابعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1704.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":7319,"question":"ما حكم زواج المسلم من أهل السنة والجماعة من الشيعة؟","title":"حكم زواج السنة من الشيعة","answer":"الجواب: لا ينبغي أن يتزوج من الشيعة؛ لأن الشيعة فيهم من يعبد عليًا، ويستغيث بأهل البيت، ويشرك بهم، ويدعوهم من غير الله، فهذا شرك أكبر، ولاسيما الشيعة الموجودة الآن، والتي في غالب الدنيا يغلب عليهم الغلو في أهل البيت. فالذي ينبغي لأهل السنة أن لا يتزوج منها إلا إذا عرف أنها ليست على دين قومها، وأنها دخلت في السنة، واستقامت على السنة، والبعد عما عليه أهلها من الغلو في أهل البيت، فإنهم يغلون في أهل البيت، ويدعون عليًّا من دون الله، والحسين وفاطمة، ويستغيثون بهم، حتى المرأة عند الطلاق تقول: يا علي! إلا من شاء الله منهم، إلا من هداه الله منهم، فينبغي التثبت في هذ الأمور، نسأل الله لنا ولهم الهداية.","link":"https://binbaz.org.sa/fatwas/3391/حكم-زواج-السنة-من-الشيعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1706.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":7335,"question":"تقدمت للعمل في إحدى المستشفيات كمترجم، وفي هذه المستشفى كما في المستشفيات الأخرى الاختلاط موجود بين الرجال والنساء، سؤالي: هو بحكم عملي اضطر إلى مخالطة النساء المرضى والعاملات، فما رأي فضيلتكم في هذا الموضوع، أفيدونا -جزاكم الله خيرًا- علمًا أنني في حاجة ماسة إلى هذه الوظيفة؟","title":"حكم العمل في أماكن الاختلاط","answer":"الجواب:  إذا كان عملك يجعلك تختلط بالنساء؛ فابتعد واحذر، احذر لئلا تُفترس، يفترسك الشيطان بواسطتهن، احذر. أما إذا كان عملك بعيدًا عنهن، إنما أنت مترجم لما يساق إليك، ويوصل إليك في مكتبك، تترجمه وتعطيهم إياه؛ فلا بأس، أما أنك تختلط بالنساء، بمريضات، وغير مريضات، وربما سبب لك ذلك مشاكل كثيرة، وأخطارًا كثيرة، وهن شبه عاريات، وكثير منهن لا يبالي بالستر والحجاب، أو كلهن، فأنت على خطر، فاحذر وابتعد، والرزق عند الله.","link":"https://binbaz.org.sa/fatwas/3414/حكم-العمل-في-اماكن-الاختلاط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1726.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":7379,"question":"نشأت يتيم الأب والأم، وتولى رعايتي عمي، فرباني وأحسن رعايتي، وذلك من صغري، وعمري سبع سنوات، وشاركته في ذلك امرأته الحنونة، فلبثت عندها حتى أصبح عمري عشرين عامًا، وعمي تولى رعايتي، وأنفق عليَّ أثناء دراستي رغم فقره، والسؤال هنا: هل يجوز أن تكشف علي امرأة عمي، أم لا يجوز؟ وأنا اعتبرها أخت بحيث أنها لم تحتجب مني قبل ذلك وظلت تكشف علي إلى آخره؟","title":"حكم الكشف والمصافحة لزوجة العم التي ربته","answer":"الجواب: هذا عمل طيب من عمك جزاه الله خيرًا، الذي أحسن إليك، ورباك، وأنفق عليك، فالعم مثل الأب لا يستغرب، العم بمنزلة الأب كما قال النبي ﷺ: إن عم الرجل صنو أبيه فإذا أحسن إليك ورباك وأنفق عليك؛ فهذا عمل مشكور، وعليك أن تدعو له وتشكره على هذا العمل، سواء كان حيًّا أو ميتًا.  وأما زوجته التي أحسنت إليك فهي بمنزلة أمك، ما هي أختك، بمنزلة الأم التي ربتك وأحسنت إليك، لكن لا تكشف لك، وليست محرمًا لك، لكن تدعو لها، وتشكرها على عملها الطيب مع زوجها، ولكن لا تخلو بها، ولا تكشف لك، بل تحتجب عنك، هي أجنبية إلا إذا كانت أرضعتك، أو أرضعتك بنتها، أو أختها؛ تكون خالة لك، لا بأس، إذا كان بينك وبينها رضاعة، إما أرضعتك هي وأنت صغير، أو أرضعتك أختها؛ تكون خالة لك، أو أرضعتك بنتها؛ تكون جدة لك، لا بأس، أما مجرد كونها ربتك ما تكون محرمًا لك، ولا تكشف لك، بل عليها أن تحتجب عنك وعليك أن لا تنظر إليها، ولكن عليك أن تشكرها وتحسن إليها، وتعرف قدرها، وإحسانها، وإحسان زوجها -عمك هذا- عليك؛ لأن النبي ﷺ يقول: من صنع إليكم معروفًا؛ فكافئوه، فإن لم تجد ما تكافئوه فادعوا له حتى تروا أنكم قد كافأتموه ويقول النبي ﷺ: من لا يشكر الناس لا يشكر الله. السؤال: وإن كانت كبيرة؟ الجواب: إلا إذا كانت عجوزًا يعني ما تشتهى، ولا تزين، ولا شيء مثل ما قال الله: وَالْقَوَاعِدُ مِنَ النِّسَاءِ اللَّاتِي لَا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَنْ يَضَعْنَ ثِيَابَهُنَّ [النور:60] إذا كانت عجوزًا كبيرة، لا تتعاطى الزينة؛ فلا بأس، أما إذا كانت تتعاطى الزينة، ويظهر منها ما قد يميل الرجال إليها؛ فلا يجوز لها أن تكشف، وليس لأحد أن ينظر إليها. والمصافحة لا يصافح الرجل النساء لا، المصافحة بين الرجل والرجال، أو بين الرجل ومحارمه، كأمه وخالته، أما أن يصافح النساء لا، النبي ﷺ قال: إني لا أصافح النساء لا كبيرة ولا صغيرة، كل ساقطة لها لاقطة.","link":"https://binbaz.org.sa/fatwas/3462/حكم-الكشف-والمصافحة-لزوجة-العم-التي-ربته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1766.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":7392,"question":"لي أخت متزوجة وزوجها يجبرها على أن لا تحتجب من إخوانه، فهل يحق لي مقاطعتهم، علمًا بأنني نصحت لهم وللزوج خاصة، ولكن الزوج رفض، فماذا علي أنا؟ وماذا على الزوجة؟","title":"حكم كشف المرأة وجهها أمام إخوة زوجها","answer":"الجواب: عليها أن تحتجب ولو لم يرض، ليس لها طاعته في المعصية، يقول النبي ﷺ: إنما الطاعة في المعروف فإذا كان ضعيف الغيرة وأمرها أن تكشف لإخوانه وأعمامه وأصحابه وأصدقائه؛ فليس لها طاعته في ذلك -نسأل الله للجميع الهداية-.","link":"https://binbaz.org.sa/fatwas/3510/حكم-كشف-المراة-وجهها-امام-اخوة-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1814.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":7410,"question":"لي أخت متزوجة وزوجها يجبرها على أن لا تحتجب من إخوانه، فهل يحق لي مقاطعتهم، علمًا بأنني نصحت لهم وللزوج خاصة، ولكن الزوج رفض، فماذا علي أنا؟ وماذا على الزوجة؟","title":"حكم كشف المرأة وجهها أمام إخوة زوجها","answer":"الجواب: عليها أن تحتجب ولو لم يرض، ليس لها طاعته في المعصية، يقول النبي ﷺ: إنما الطاعة في المعروف فإذا كان ضعيف الغيرة وأمرها أن تكشف لإخوانه وأعمامه وأصحابه وأصدقائه؛ فليس لها طاعته في ذلك -نسأل الله للجميع الهداية-.","link":"https://binbaz.org.sa/fatwas/3510/حكم-كشف-المراة-وجهها-امام-اخوة-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1814.mp3","categories":["الخِطْبَة والاختيار ","النظر والخلوة والاختلاط","قضايا المرأة","الآداب والأخلاق"]},{"id":12392,"question":"مستمع مصري مقيم في المملكة (يوسف. ع) يقول: عندما يطلب مني أحد الأشخاص قرضًا أعتذر عن ذلك بحجة أنني لا أملك المال مع أنني أملكه، وذلك خوفًا من ضياع المال؛ لأني سبق أن أقرضت الكثيرين؛ فامتنعوا عن السداد؟","title":"حكم الكذب لرد المدين المماطل","answer":"الجواب:  الواجب أن تعتذر بغير عدم المال، تعتذر بعذر يحتمل، وتترك عدم وجود المال، لا تكذب، لا حاجة إلى الكذب، تعتذر بعذر آخر من الأعذار المناسبة التي تقنع خصمك، تقنع صاحبك، والحمد لله، وإذا كنت تثق بصاحبك، وأنت موسر؛ فأحسن إليه، وفرج كربته، وأبشر بالخير، يقول النبي ﷺ: من نفس عن مؤمن كربة من كرب الدنيا؛ نفس الله عنه كربة من كرب يوم القيامة. والقرض فيه تنفيس، فإذا استطعت أن تنفس؛ فافعل، فإذا كنت تخشى الضياع، وأن هذا المقترض لا يقوم بالواجب؛ فاعتذر بعذر آخر، كأن تقول -مثلاً- لا أستطيع، وتنوي لا تستطيع؛ لأنك لا تثق به، ولا تطمئن إليه، أو تأتي بعذر آخر تقول مثلاً: إن هناك مانعًا يمنعني من القرض، ولا تبين وايش المانع. والمقصود: تأتي بعذر يحتمل، لا تكون فيه كاذبًا، نعم. المقدم: الله المستعان، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10598/حكم-الكذب-لرد-المدين-المماطل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_401/40117.mp3","categories":["الآداب والأخلاق"]},{"id":13359,"question":"فضيلة الشيخ! هذا السائل عبدالعزيز من الرياض يقول: كثير من الناس هداهم الله يذهبون في رمضان للمساجد البعيدة عن بيوتهم لأداء صلاة التراويح؛ طلبًا لحسن الصوت لبعض الأئمة، ولكن المشكلة يا سماحة الشيخ بأنهم يذهبون متأخرين جدًا، فنراهم قد تفوتهم صلاة العشاء، فيقضون جماعات في آخر المسجد، هل من كلمة لهؤلاء يا سماحة الشيخ؟","title":"توجيه لمن يقصد مسجدًا بعيدًا لأجل التراويح وتفوته العشاء","answer":"الجواب: نعم، نصيحتي للجميع أن يتقوا الله، وأن يحرصوا على أداء الفريضة، وإذا ذهب بعد الفريضة، أو مبكرًا حتى يدرك الفريضة إلى شخص آخر، يرى أن صوته أحسن، وأنه يخشع لقراءته، ويستفيد؛ فلا بأس، ولو كان بعيدًا عن بيته، لكن يحرص على أداء الفريضة، لا تفوته الفريضة، إما يصليها في المساجد القريبة، وإلا أن يبكر حتى يصلي مع ذاك الإمام الفريضة، ولا يعرض نفسه أن تفوته الفريضة؛ لأن الفريضة فرض عليه، والتراويح مستحبة، فلا يضيع الفرض من أجل المستحب. يجب أن يعتني بالفريضة حتى يؤديها مع إخوانه المسلمين، وإذا أحب أن يصلي مع شخص آخر؛ فليبكر، يذهب قبل العشاء حتى يدرك الفريضة معه، أو بعد العشاء إذا صلى الفريضة، ولا بأس. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11644/توجيه-لمن-يقصد-مسجدا-بعيدا-لاجل-التراويح-وتفوته-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_524/52402.mp3","categories":["الآداب والأخلاق","نصائح وتوجيهات","وقت الصلاة"]},{"id":13508,"question":"في ثاني أسئلته يقول هذا السائل: لدينا قبيلة -هداهم الله- لا زالوا على بعض العادات، وقد وضعوا طريقة للمهر، وشروط، فمن الناس من رفض ذلك، فهجرناهم، وقررنا أن نهجرهم، وأن نقاطعهم، ولا نحضر احتفالاتهم، أو المناسبات التي يقيمونها، وكان فيهم أقرباء لنا، وجيران، فما رأي سماحتكم؟","title":"حكم مقاطعة وهجر من يغالون في المهور","answer":"الجواب: لا، لا يجوز هجرهم، ولا مقاطعتهم، ولكن ينصحون إذا قرروا المهور لبناتهم لبنته بكذا، وأخته بكذا، ينصحون بالتخفيف. أما هجرهم، هذه لهم شبهة، ما تسمى معصية، لا يهجرون، بل ينصحون، ويوجهون للخير، ويتعاون معهم على الخير والبر بالكلام الطيب، والأسلوب الحسن، مع الرجل، ومع المرأة، ومع أمها، ومع أبيها وعمها، ونحو ذلك من باب التناصح، والتواصي بالحق، هكذا ينبغي. أما الهجران والمقاطعة فلا وجه لهذا؛ لأن لهم شبهة، وقد يكون لهم أسباب، قد يكونوا شرطوا أشياء يحتاجونها، ولا يمكن -يعني- يجرون الزواج إلا بها، لكن إذا كان هناك مهور زائدة، وتكلف زائد ينصحون من باب النصيحة .. من باب التعاون على البر والتقوى .. من باب التواصي بالحق، لا من باب الهجر والشدة. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11821/حكم-مقاطعة-وهجر-من-يغالون-في-المهور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_531/53107.mp3","categories":["الصداق","الآداب والأخلاق"]},{"id":13629,"question":"المستمعة (ن. ع) من منطقة سدير بعثت برسالة ضمنتها ثلاثة أسئلة، في سؤالها الأول تقول: بعض الناس عندما يكتبون اسم الرسول الكريم ﷺ يضعون بدلًا من الصلاة عليه -عليه أفضل الصلاة والسلام- رمزًا حرف الصاد، هل ما يفعلونه صحيح؟","title":"هل يصح كتابة (ص) أو (صلعم) اختصارا؟","answer":"الجواب: لا هذا لا ينبغي، بل المشروع أن يصلوا عليه ﷺ صلاة مكتوبة ﷺ وبعضهم يحط (صلعم) صاد لام عين ميم إشارة إلى ﷺ وهذا أيضًا غلط لا ينبغي، قد نبه العلماء على ذلك، فالسنة لمن تكلم باسمه ﷺ أو كتبه أن يصلي عليه ﷺ صريحًا يقول: ﷺ ولا يضع (ص) بدلًا من ذلك ولا (صلعم). نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11957/هل-يصح-كتابة-ص-او-صلعم-اختصارا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_480/48015.mp3","categories":["الآداب والأخلاق"]},{"id":13664,"question":"السائل الذي رمز لاسمه بهذا الرمز (رمضان . ح. ر) يقول: ماذا يفعل من مات والديه وهو عاق لهما، وهو نادم الآن بعد وفاتهما على هذا العقوق، ولا يدري ماذا يفعل حتى يتوب الله عليه جزاكم الله خيرًا سماحة الشيخ؟","title":"الواجب على من مات والداه وهو عاق لهما","answer":"الجواب: عليه التوبة إلى الله، كل ذنب فيه توبة، إذا مات عاقًا لوالديه؛ عليه التوبة إلى الله، أو ظالمًا لأحد؛ عليه التوبة إلى الله، والندم، والإقلاع، والدعاء لهم بالمغفرة والرحمة، يكثر من الدعاء لهم، والصدقة عنهم، وهذا مما يخفف عنه، ويزيل عنه الإثم، التوبة تجب ما قبلها، الحمد لله. يقول النبي ﷺ: الإسلام يهدم ما كان قبله، والتوبة تجب ما قبلها ويقول الله -جل وعلا-: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38] فإذا كان الكفر يغفر بالتوبة؛ فالعقوق من باب أولى. فالواجب على من عق والديه، أو أحدهما، أو قطع رحمه أن يتوب إلى الله، وأن يصلهم بعد الموت بالدعاء لهم، وتنفيذ وصاياهم الشرعية، وإكرام أصدقائهم، وأقاربهم، هذا كله من برهم بعد الموت، قال رجل: يا رسول الله! هل بقي من بر أبوي شيء أبرهما بعد الموت؟ قال: نعم، الصلاة عليهما صلاة الجنازة. والدعاء والاستغفار لهما، وإنفاذ عهدهما من بعدهما الوصية الشرعية وإكرام صديقهما، وصلة الرحم التي لا توصل إلا بهما كعمك، وعماتك، وجدتك أم أبيك، وأم أمك، وإخوتك، كلها صلتهم من التوبة، صلتهم والدعاء للوالدين، والدعاء للأقارب الذين قطعتهم وماتوا، الدعاء لهم والترحم عليهم، وإكرام أصدقائهم، والصدقة عنهم، وإنفاذ وصاياهم الشرعية، كل هذا من مكافأتهم ومن أسباب تكفير السيئات. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12007/الواجب-على-من-مات-والداه-وهو-عاق-لهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_529/52907.mp3","categories":["الآداب والأخلاق"]},{"id":14086,"question":"يقول: ألاحظ أن كثيرًا من الناس يأكلون على الجرائد والصحف، بينما هي تحوي ذكر الله وتحوي آيات قرآنية وبعض الأحاديث النبوية، وجهوا الناس حول هذا الموضوع جزاكم الله خيرًا.","title":"حكم اتخاذ الصحف والمجلات سفر للطعام","answer":"الجواب: هذا لا يجوز، لا يجوز اتخاذ الجرائد مفارش للطعام سفر للطعام، ولا ملفات للحاجات هذا امتهان؛ لأنها لا تخلو من ذكر الله، إما آيات قرآنية، أو أحاديث أو ذكر الله ، فالواجب أن تصان وتحفظ أو تدفن في محل طيب أو تحرق، أما أن تتخذ سفرًا هذا امتهان لا يجوز، وهكذا اتخاذها ملاف للحاجات هذا لا يجوز، الواجب صيانتها بحفظها في الدواليب ونحوها، أو دفنها في محل طيب أو إحراقها حتى لا تمتهن.\nوهكذا الأوراق الأخرى التي فيها ذكر الله، أو مصاحف مقطعة، تدفن في أرض طيبة أو تحرق، ولا تستعمل سفرًا ولا ملافًا بل هذا منكر. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12517/حكم-اتخاذ-الصحف-والمجلات-سفر-للطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48410.mp3","categories":["الأطعمة والأشربة","الآداب والأخلاق"]},{"id":14198,"question":"رسالة وصلت إلى البرنامج من المستمع (ع. ح. ع. العتيبي) أخونا يقول في رسالته: أرجو إفادتي في هذه القضية: لي أخت ليست متزوجة والآن استحقت الزواج تقدم لخطبتها أحد الأشخاص وقال لوالدي: زوجني ابنتك وأزوجك ابنتي، والمعنى على ما يدل بالبدل وقرر والدي بزواجها بدلًا، وكما سمعنا بأن البدل حرام ولذلك اعترضته - أنا أخوها - اعترضت على والدي حتى لا يتم هذا الزواج لكن في نفسي شيء هل أكون آثمًا عندما أعترض على الوالد في مثل هذه الأشياء؟","title":"حكم الاعتراض على الوالد في نكاح الشغار","answer":"الجواب: قد أحسنت فيما فعلت، ولكن يكون ذلك بالأسلوب الحسن والنصيحة؛ لأن الوالد حقه عظيم، فيكون الاعتراض عليه بالأسلوب الحسن والنصيحة والتوجيه وإرشاده إلى سؤال أهل العلم حتى يعلم الحكم الشرعي. وهذا النكاح الذي ذكرت يسمى: نكاح الشغار، ويسميه بعض الناس الآن: البدل؛ وهو: أن يزوج الرجل ابنته أو أخته أو غيرهما من مولياته كبنت أخيه ونحو ذلك على آخر بشرط أن يزوجه الآخر ابنته أو أخته أو غيرهما أو يزوج ابنه، هذا لا يجوز، سواء سمي مهرًا أم لم يسم مهرًا؛ لأنه ثبت عن رسول الله عليه الصلاة والسلام أنه نهى عن الشغار في عدة أحاديث عنه عليه الصلاة والسلام من حديث ابن عمر وحديث جابر وحديث أبي هريرة وغيرهم، وقال عليه الصلاة والسلام: لا شغار في الإسلام، وقال: الشغار أن يقول الرجل: زوجني بنتك وأزوجك بنتي أو زوجني أختك وأزوجك أختي. وثبت في مسند أحمد وسنن أبي داود عن معاوية  أنه كتب إلى أمير المدينة في شخصين تزوجا بالشغار وبينهما مهر فأمره أن يفرق بينهما، وقال: هذا هو الشغار الذي نهى عنه النبي عليه الصلاة والسلام. وقد ذهب بعض أهل العلم إلى أنه إذا كان هناك مهر كالمعتاد فليس بشغار، ولكنه قول مرجوح وضعيف، والصواب أنه شغار مطلقًا سواء كان فيه مهر أم لم يكن فيه مهر، إذا كان كل واحد شرط على الآخر التزويج؛ زوجني وأزوجك، أو لا أزوجك حتى تزوجني.. أو ما أشبهه من العبارات الدالة على أنه شرط. أما إذا خطب بنت ووافق ثم خطب الآخر ووافق من دون مشارطة فلا حرج في ذلك، الممنوع المشارطة وأن هذا لا يزوج هذا إلا بشرط تزويجه موليته، وهذا فيه فساد كبير؛ من ذلك أنه جعل بضع هذه مهرًا لهذه هذا هو المعنى في الحقيقة، ومن ذلك أنه يفضي إلى إجبار النساء وظلمهن من أجل مصلحة الولي، ومن ذلك أنه يفضي إلى خصومات كثيرة ونزاع كلما حصل بين هذه وزوجها شيء حصل بين الأخرى وزوجها شيء، وهذا يفضي إلى مفاسد لا تنتهي، ومن حكمة الله  ومن إحسانه إلى عباده ومن رحمته لهم أن حرم هذا العقد. فالواجب على أهل العلم وعلى كل مسلم أن يحذروا الناس من هذا العقد، وأن يمتثلوا أمر الرسول عليه الصلاة والسلام في ذلك، وفيما أحل الله غنية وكفاية عما حرم الله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12651/حكم-الاعتراض-على-الوالد-في-نكاح-الشغار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_616/61602.mp3","categories":["الأنكحة المحرمة","قضايا المرأة","الآداب والأخلاق"]},{"id":14288,"question":"رسالة وصلت إلى البرنامج من مكة المكرمة وباعثها المستمع: سليمان الحمد، أخونا يسأل ويقول: ما صحة إذا نام الإنسان وله أقارب ويراهم في المنام يتحدث إليهم ويتحدثون إليه؟ هل في ذلك تفسير شرعي؟ وجهونا، جزاكم الله خيرًا.","title":"هل التحدث مع الأقارب في المنام لها تأويل معين؟","answer":"الجواب: لا أعلم في ذلك شيئًا خاصًا، ولكن جاءت السنة عن النبي ﷺ بأن الإنسان إذا رأى في منامه ما يكره فإنه من الشيطان، وبيَّن عليه الصلاة والسلام أنه يشرع له أن ينفث عن يساره ثلاث مرات - يعني: يتفل عن يساره ثلاث مرات -، ويقول: أعوذ بالله من الشيطان، ومن شر ما رأيت.. ثلاث مرات، ثم لينقلب على جنبه الآخر، وقال: إنها لا تضره، ولا يخبر بها أحدًا هكذا قال عليه الصلاة والسلام، والحديث يقول عليه الصلاة والسلام: الرؤيا الصالحة من الله والحلم من الشيطان، فإذا رأى أحدكم ما يكره فلينفث عن يساره ثلاث مرات ويتعوذ بالله من الشيطان ومن شر ما رأى ثلاث مرات ثم لينقلب على جنبه الآخر؛ فإنها لا تضره ولا يخبر بها أحدًا. وجاء في الحديث الثاني: إنه إذا رأى ما يحب فإنه يحمد الله ويخبر بذلك من يحب هذا هو السنة في هذا المقام. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12765/هل-التحدث-مع-الاقارب-في-المنام-لها-تاويل-معين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_618/61803.mp3","categories":["الآداب والأخلاق"]},{"id":15103,"question":"الأخت نورة عبدالعزيز العبيد من القصيم من عنيزة، تبعث بهذه الرسالة، مع الشكر والسؤال بطول العمر على زود عمل صالح، وتقول: ما حكم اختصار اسم الرسول ﷺ مثل (صلعم)؟","title":"حكم اختصار كتابة ﷺ بـ (صلعم) أو (ص)","answer":"الجواب: ما ينبغي هذا، ينبغي لمن كتب اسم النبي ﷺ، أو نطق به، أن يصلي صلاة كاملة، يقول: ﷺ، ولا يقول: (صلعم) ولا (ص) فقط، فالكسل لا ينبغي، بل السنة والمشروع أن يكتب الصلاة صريحة فيقول: ﷺ، أو عليه الصلاة والسلام؛ لأن الله قال -جل وعلا-: إِنَّ اللَّهَ وَمَلائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا [الأحزاب:56] ويقول النبي ﷺ: من صلى علي واحدة صلى الله عليه بها عشرًا وجاء عنه : أن جبريل أخبره: أن من صلى عليه واحدة صلى الله عليه بها عشرًا، ومن سلم عليه واحدة، سلم الله عليه بها عشرًا الحسنة بعشر أمثالها، فلا ينبغي للمؤمن أن يكسل، ولا للمؤمنة أن تكسل عند الكتابة، أو عند النطق باسمه ﷺ عن الصلاة والسلام عليه خطًا ولفظًا، أما الإشارة بالصاد أو بـ(صلعم) فهذا لا ينبغي، نعم.","link":"https://binbaz.org.sa/fatwas/13605/حكم-اختصار-كتابة-ﷺ-بـ-صلعم-او-ص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_656/nour_65606.mp3","categories":["الآداب والأخلاق","الأدعية والأذكار"]},{"id":17894,"question":"المستمع (ع. ع. م) من المنطقة الجنوبية يسأل ويقول: مشكلتي في علاقتي بالناس فهناك من أرتاح إليهم وأجالسهم وأجد فيهم الصديق والرفيق وأشعر بالارتياح لوجودي معهم وهؤلاء قلة، وهناك قسم آخر ممن أعرف لا أطيق الجلوس معهم ولا التحدث إليهم ولا أرتاح لهم أبدًا، وأجد بأن طبعي لا يوافق طبعهم، وأحيانًا أضطر إلى البقاء معهم والحديث إليهم والتعامل معهم لارتباطي معهم بقرابة أو في عمل أو غير ذلك مما يضطرني للمجاملة معهم.الشيخ: أعد أعد.المقدم: يقول: مشكلتي في علاقتي بالناس فهناك من أرتاح إليهم وأجالسهم وأجد فيهم الصديق والرفيق وأشعر بالارتياح لوجودي معهم وهؤلاء قلة، وهناك قسم آخر ممن أعرف لا أطيق الجلوس معهم ولا التحدث إليهم ولا أرتاح لهم أبدًا، وأجد بأن طبعي لا يوافق طبعهم، وأحيانًا أضطر إلى البقاء معهم والحديث إليهم والتعامل معهم لارتباطي معهم بقرابة أو في عمل أو غير ذلك، مما يضطرني للمجاملة معهم وإظهار البشاشة والارتياح غصبًا عني، وأحس أثناء وجودي معهم أنني بحاجة إلى التكلف في الكلام والمعاملة، وهذا لا أجيده مما يزيدني نفورًا وبعدًا عنهم وعدم ارتياح نحوهم، ولهذا أصبحت أفضل تجنب كل من لا أرتاح إليه بقدر الإمكان، وهذا يؤدي إلى العزلة نوعًا ما، علمًا بأنني في حالة العزلة وبقائي لوحدي أحس بالراحة وأستفيد من وقتي في تلاوة القرآن وقراءة الكتب النافعة؟","title":"الحث على اختيار الأصدقاء الفضلاء","answer":"الجواب: عليك أن تعمل ما هو أصلح لقلبك وأن تختار الأصحاب والجلساء الطيبين، أما الذين تنفر منهم ولا تلائمك طبائعهم ولا تأنس بالجلوس معهم فابتعد عنهم، واختر لنفسك ما هو أصلح ولو بالجلوس في بيتك لقراءة القرآن والتسبيح والتهليل ونحو ذلك، المؤمن يحاسب نفسه ويجاهدها في صحبة الأخيار والبعد عن الأشرار، وفي اختيار الوقت الفاضل والصاحب الفاضل، أنت تجاهد نفسك فيما تراه أصلح لدينك وأسلم لدينك، فتصحب الأخيار، وتستر عليهم حتى تستفيد منهم، وتبتعد عن الأشرار ولو كانوا من الأقارب حتى لا يضرك الجلوس معهم، ولا تحمل نفسك ما لا تطيق.\nأما إن كنت لا ترغب في الجلوس مع الأخيار فهذا مرض في قلبك إذا كانوا طيبين أهل دين جاهد نفسك حتى تبقى معهم وتستفيد منهم، ولو نفرت نفسك منهم لما فيها من مرض المعصية لا تبال بذلك عليك بصحبة الأخيار والصبر عليهم والاستفادة منهم ولو كنت تحس بشيء من الكلفة والشدة؛ لأن صحبة الأخيار لا تأتي إلا بالخير، أما صحبة الأشرار فإنها وسيلة للشر العظيم.\nفالحاصل أنك تحكم الشرع المطهر فيما هو أصلح لقلبك وأنفع لدينك في الجلساء وغير الجلساء فتجلس مع الطيبين ومع الأخيار ومع من تنفعك مجالستهم وتبتعد عما يضرك الجلوس معهم من أقارب أو غيرهم، وبيتك خير لك من الجلوس مع من يضرك، ومن لا تطيق البقاء معه لسوء أفعاله أو سوء أخلاقه أو سوء تصرفه، نسأل الله للجميع التوفيق.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16934/الحث-على-اختيار-الاصدقاء-الفضلاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_846/nour_84610.mp3","categories":["الأطعمة والأشربة","الآداب والأخلاق","نصائح وتوجيهات"]},{"id":17953,"question":"السائل: محمد (ع. خ) يقول: قريب لي عاق لوالديه كثيرًا، فما هو حق الوالدين على الأبناء؟ وهل من كلمة يا سماحة الشيخ لمن لهم هذه الصفة في والديهم أو أحدهما؟","title":"حق الوالدين على أبنائهم","answer":"الجواب: الواجب على الولد بر والديه، والحذر من العقوق، يقول النبي ﷺ: ألا أنبئكم بأكبر الكبائر؟ قلنا: بلى يا رسول الله! قال: الإشراك بالله وعقوق الوالدين فجعل عقوق الوالدين من أكبر الكبائر، ويقول ﷺ: من الكبائر شتم الرجل والديه! قيل: يا رسول الله! وهل يسب الرجل والديه؟! قال: يسب أبا الرجل فيسب أباه، ويسب أمه فيسب أمه فعقوقهما والسب في ذلك من الكبائر، فالواجب الحذر. والله يقول جل وعلا: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلاهُمَا فَلا تَقُلْ لَهُمَا أُفٍّ وَلا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا  ۝  وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا [الإسراء:23، 24].. يقول جل وعلا: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14]، فالواجب برهما والإحسان إليهما وشكرهما، والحذر من عقوقهما، نسأل الله العافية. نعم.\nالمقدم: اللهم آمين، أحسن الله إليكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16968/حق-الوالدين-على-ابناىهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59832.mp3","categories":["الأطعمة والأشربة","الآداب والأخلاق","نصائح وتوجيهات"]}]
